// ⭐ Round 7.75r38r15dd: Attendance constants (MVP Phase 1)
//   เกณฑ์สาย: ontime (-15→+9'), late_15 (10-15'), late_over (>15')
const ATTENDANCE_LATE_THRESHOLDS = {
  ontime: 9,    // ≤ 9 min late = ontime
  late_15: 15,  // 10-15 min = late_15
  // > 15 min = late_over
};

// ⭐ Helper: classify lateness (เทียบเวลาเข้ากับ schedule)
function classifyAttendanceLateness(scheduledStartMin, actualClockInMin) {
  const diff = actualClockInMin - scheduledStartMin;
  if (diff <= ATTENDANCE_LATE_THRESHOLDS.ontime) return 'ontime';
  if (diff <= ATTENDANCE_LATE_THRESHOLDS.late_15) return 'late_15';
  return 'late_over';
}
