// ⭐ Round 7.75r37: ปลดล็อคแก้ไขย้อนหลัง — เก็บใน sessionStorage (จะ reset เมื่อ reload)
//   Owner → ผ่านได้เสมอ (ไม่ต้องใส่ PIN)
//   PR → ต้องใส่ PIN ที่ Owner ตั้งไว้
// ⭐ r38r26z32: เพิ่ม timestamp → expire 30 นาที (PR ต้องใส่ PIN ใหม่)
const PAST_UNLOCK_TTL_MIN = 30;

function isPastUnlocked() {
  if (state.user?.role === 'owner') return true;
  try {
    const raw = sessionStorage.getItem('pastUnlocked');
    if (raw !== '1') return false;
    // ⭐ z32: เช็ค timestamp
    const tsRaw = sessionStorage.getItem('pastUnlockedAt');
    if (tsRaw) {
      const ts = parseInt(tsRaw);
      const elapsed = (Date.now() - ts) / 60000;  // นาที
      if (elapsed > PAST_UNLOCK_TTL_MIN) {
        // หมดอายุ → clear + return false
        sessionStorage.removeItem('pastUnlocked');
        sessionStorage.removeItem('pastUnlockedAt');
        return false;
      }
    }
    return true;
  } catch { return false; }
}
function setPastUnlocked(v) {
  try {
    if (v) {
      sessionStorage.setItem('pastUnlocked', '1');
      sessionStorage.setItem('pastUnlockedAt', String(Date.now()));
    } else {
      sessionStorage.removeItem('pastUnlocked');
      sessionStorage.removeItem('pastUnlockedAt');
    }
  } catch {}
}

// ⭐ r38r29p19: PR แก้ไข "ข้อมูลพนักงาน" ได้ — ต้องใส่ PIN (Owner ตั้งได้ · default 0000)
//   เก็บใน sessionStorage · หมดอายุ 30 นาที · Owner ผ่านตลอด
const STAFF_EDIT_UNLOCK_TTL_MIN = 30;
const STAFF_EDIT_PIN_DEFAULT = '0000';

function isStaffEditUnlocked() {
  if (state.user?.role === 'owner') return true;
  try {
    if (sessionStorage.getItem('staffEditUnlocked') !== '1') return false;
    const ts = parseInt(sessionStorage.getItem('staffEditUnlockedAt') || '0', 10);
    if (ts && (Date.now() - ts) / 60000 > STAFF_EDIT_UNLOCK_TTL_MIN) {
      sessionStorage.removeItem('staffEditUnlocked');
      sessionStorage.removeItem('staffEditUnlockedAt');
      return false;
    }
    return true;
  } catch { return false; }
}
function setStaffEditUnlocked(v) {
  try {
    if (v) {
      sessionStorage.setItem('staffEditUnlocked', '1');
      sessionStorage.setItem('staffEditUnlockedAt', String(Date.now()));
    } else {
      sessionStorage.removeItem('staffEditUnlocked');
      sessionStorage.removeItem('staffEditUnlockedAt');
    }
  } catch {}
}
function staffEditMinsLeft() {
  try {
    const ts = parseInt(sessionStorage.getItem('staffEditUnlockedAt') || '0', 10);
    if (!ts) return 0;
    return Math.max(0, Math.ceil(STAFF_EDIT_UNLOCK_TTL_MIN - (Date.now() - ts) / 60000));
  } catch { return 0; }
}
// สิทธิ์แก้ข้อมูลพนักงาน (Owner = ตลอด · PR = หลังใส่ PIN)
function canEditStaffProfile() {
  return state.user?.role === 'owner' || isStaffEditUnlocked();
}

// ⭐ r38r26z28: Backfill helpers — ลงรอบย้อนหลัง
//   PR/Manager: ค่าเริ่มต้น 15 วัน (Owner ตั้งได้ในหน้าตั้งค่า) · Owner: ไม่จำกัด
const BACKFILL_DAYS_PR = 15;

function getBackfillLimitDays() {
  if (state.user?.role === 'owner') return Infinity;
  // ⭐ r38r29gq: Owner ตั้งจำนวนวันได้ใน Settings (ไม่ฮาร์ดโค้ด) · default = BACKFILL_DAYS_PR (14)
  const _cfg = parseInt(state.config?.security?.backfillLimitDays, 10);
  return (Number.isFinite(_cfg) && _cfg > 0) ? _cfg : BACKFILL_DAYS_PR;
}

function calcDaysAgo(dateStr) {
  if (!dateStr) return 0;
  const today = new Date(); today.setHours(0,0,0,0);
  const target = parseYmd(dateStr); 
  if (!target) return 0;
  target.setHours(0,0,0,0);
  return Math.floor((today - target) / 86400000);
}

function canBackfillDate(dateStr) {
  const daysAgo = calcDaysAgo(dateStr);
  if (daysAgo < 0) return { ok: false, reason: 'ดูอนาคตไม่ได้', daysAgo };
  if (daysAgo === 0) return { ok: true, daysAgo: 0 };
  const limit = getBackfillLimitDays();
  if (daysAgo > limit) {
    return { ok: false, reason: `ย้อนหลังเกิน ${limit} วัน — ติดต่อ Owner`, daysAgo };
  }
  return { ok: true, daysAgo };
}

