function getBackfillReasonLabel(code) {
  const r = BACKFILL_REASONS.find(x => x.code === code);
  return r ? `${r.icon} ${r.label}` : code;
}

// ⭐ r38r26z28: ตรวจว่า date อยู่ในงวด payslip ที่ปิดแล้วหรือไม่
//   "ปิดแล้ว" = payslip ของ week นั้น status === 'pending_check' หรือ 'confirmed'
//   - PR ถูก block (toast)
//   - Owner ผ่านได้ + confirm dialog
function getClosedPayslipForDate(dateStr) {
  if (!dateStr) return null;
  // หา week start ของ date (วันจันทร์ของสัปดาห์)
  const d = parseYmd(dateStr);
  if (!d) return null;
  const dow = d.getDay(); // 0=Sun, 1=Mon, ...
  const daysToMon = (dow === 0) ? -6 : (1 - dow);
  const mon = new Date(d);
  mon.setDate(d.getDate() + daysToMon);
  const weekStart = ymd(mon);
  // หา payslip ที่ปิดแล้วใน state (ถ้ามี)
  const closedSlip = (state.staff_payments || []).find(p => 
    p.weekStart === weekStart && 
    (p.status === 'pending_check' || p.status === 'confirmed')
  );
  return closedSlip || null;
}

