// ⭐ Round 7.75r37: Group course helpers
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// คอร์สเดี่ยว/คู่/3-คน/4-คน/ทาส — ทั้งหมดใช้ schema เดียวกัน:
//   walkin.staffIds = [id1, id2, ...]  (ใหม่ — array ทุกคน)
//   walkin.staffId  = staffIds[0]      (compat — หลัก)
//   walkin.staffId2 = staffIds[1]      (compat — couple)
//   walkin.bookingType = 'single' | 'couple' | 'group3' | 'group4' | ...
//   walkin.groupSize = 1 | 2 | 3 | 4 | ...

// แกะ staffIds[] จาก walkin/booking — ทำงานได้ทั้งของเก่า (staffId/staffId2) + ใหม่ (staffIds[])
function getStaffIdsFromRecord(r) {
  if (Array.isArray(r.staffIds) && r.staffIds.length > 0) {
    return r.staffIds.filter(Boolean);
  }
  // Fallback — ของเก่า
  const arr = [];
  if (r.staffId) arr.push(r.staffId);
  if (r.staffId2) arr.push(r.staffId2);
  return arr;
}

// หา service.groupSize — fallback จาก isCouple
function getServiceGroupSize(svc) {
  if (!svc) return 1;
  if (svc.groupSize) return svc.groupSize;
  return svc.isCouple ? 2 : 1;
}

// แปลง groupSize → bookingType code
function groupSizeToBookingType(n) {
  if (n === 1) return 'single';
  if (n === 2) return 'couple';
  return `group${n}`;
}

// ⭐ Round 7.75r38r9: Global helper — bookingType → required staff count
function getRequiredCount(bt) {
  if (!bt) return 1;
  if (bt === 'single') return 1;
  if (bt === 'couple') return 2;
  if (bt.startsWith('group')) return parseInt(bt.slice(5)) || 1;
  return 1;
}

// นับ TOP/Hot ในรายการ staff
function countTopHot(staffArr) {
  return staffArr.filter(s => s && (s.tier === 'Top' || s.tier === 'Hot')).length;
}

// ตรวจว่า service ใช้ได้ในร้าน shop ไหม
function isServiceAvailableInShop(svc, shop) {
  if (!svc) return false;
  const list = svc.availableShops;
  if (!Array.isArray(list) || list.length === 0) return true;
  return list.includes(shop);
}

