  // ⭐ r38r17j: tag_definitions — สี/icon ของแต่ละ tag
  // ⭐ r38r17r: One-time seed defaults into Firestore (จึง deletable ได้จริง)
  let _tagDefsSeeded = false;
  state.unsubs.push(onSnapshot(collection(db, 'tag_definitions'), async (snap) => {
    state.tagDefinitions = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    refreshAllViews();
    
    // Seed defaults ครั้งเดียว ถ้ายังไม่เคยมี seed marker
    if (!_tagDefsSeeded) {
      _tagDefsSeeded = true;
      try {
        const markerExists = state.tagDefinitions.some(t => t.name === '__seed_marker__');
        if (!markerExists && typeof TAG_DEFAULT_STYLES === 'object') {
          console.log('[tag_definitions] First-time seed: migrating', Object.keys(TAG_DEFAULT_STYLES).length, 'defaults to Firestore');
          const batch = writeBatch(db);
          // Marker doc — ป้องกัน re-seed
          batch.set(doc(collection(db, 'tag_definitions')), {
            name: '__seed_marker__',
            _internal: true,
            seededAt: serverTimestamp(),
          });
          // Seed each default that doesn't already exist
          Object.entries(TAG_DEFAULT_STYLES).forEach(([name, style]) => {
            const exists = state.tagDefinitions.find(t => t.name === name);
            if (!exists) {
              batch.set(doc(collection(db, 'tag_definitions')), {
                name,
                color: style.color,
                icon: style.icon,
                _isDefault: true,
                createdAt: serverTimestamp(),
                createdBy: 'system_seed',
              });
            }
          });
          await batch.commit();
          console.log('[tag_definitions] Seed complete');
        }
      } catch (e) {
        console.error('[tag_definitions] Seed failed:', e);
      }
    }
  }));

