    btn.classList.remove('active');
    delete btn.dataset.ownerOnly; btn.removeAttribute('data-owner-only');
    btn.innerHTML = '🎨 สร้างรูป';
    ref.after(btn);
    btn.onclick = () => switchView('image-hub');
    if (typeof applyTabPermissions === 'function') applyTabPermissions();
