function openHourlyUpdateModal(initShop, mode = 'broadcast') {
  // mode: 'broadcast' = ส่งอัปเดตทุกชั่วโมง (ปุ่ม 📲)
  //       'whosfree'  = ตอบลูกค้าที่ถาม "ตอนนี้ใครว่าง" (ปุ่ม ⚡)
  //       ใช้ template ข้อความเดียวกัน — แค่ title + helper ต่างกัน
  // Permission: PR ที่ดูแล 1 ร้าน → บังคับร้านนั้น
  let allowedShops = ['geisha', 'yoshi'];
  if (state.user?.role === 'pr') {
    allowedShops = Array.isArray(state.user.assignedShops) && state.user.assignedShops.length > 0
      ? state.user.assignedShops
      : [state.user.assignedShop || 'geisha'];
  }
  // ⭐ Round 7.75r24: respect master lock
  const masterLockedHU = state.shopFilter && state.shopFilter !== 'both';
  const showShopPicker = allowedShops.length >= 2 && !masterLockedHU;
  const defaultShop = initShop || (masterLockedHU ? state.shopFilter : (showShopPicker ? 'both' : allowedShops[0]));
  
  // ⭐ Round 7.75r37: state สำหรับเลือกวัน (0=วันนี้, 1=พรุ่งนี้)
  let currentDayOffset = 0;
  // ⭐ Round 7.75r37: state สำหรับเลือกภาษา (th/en)
  let currentLang = 'th';
  let currentShop = defaultShop;
  let currentText = buildHourlyUpdateText(currentShop, mode, currentDayOffset, currentLang);
  
  // ⭐ Round 7.75r37: รวม 3 picker เป็น pill style บรรทัดเดียว — ขยาย textarea
  // Pill: เล็ก compact, active = สี accent, inactive = soft bg
  const pillStyle = `
    padding:6px 12px; border:none; border-radius:999px; 
    font-size:12px; font-weight:600; cursor:pointer; 
    background:var(--bg-elev-2); color:var(--text-soft);
    transition:all 0.15s; white-space:nowrap;
  `;
  const pillActive = `background:var(--accent) !important; color:#fff !important;`;
  
  const dayPicker = `
    <div id="hu-day-pick" style="display:flex; gap:4px;">
      <button data-day="0" style="${pillStyle} ${pillActive}">วันนี้</button>
      <button data-day="1" style="${pillStyle}">พรุ่งนี้</button>
    </div>
  `;
  
  const langPicker = `
    <div id="hu-lang-pick" style="display:flex; gap:4px;">
      <button data-lang="th" style="${pillStyle} ${pillActive}">🇹🇭</button>
      <button data-lang="en" style="${pillStyle}">🇬🇧</button>
    </div>
  `;
  
  const shopButtons = showShopPicker ? `
    <div id="hu-shop-pick" style="display:flex; gap:4px; flex-wrap:wrap;">
      <button data-shop="both" style="${pillStyle} ${currentShop === 'both' ? pillActive : ''}">ทั้งคู่</button>
      <button data-shop="geisha" style="${pillStyle} ${currentShop === 'geisha' ? pillActive : ''}">🌸</button>
      <button data-shop="yoshi" style="${pillStyle} ${currentShop === 'yoshi' ? pillActive : ''}">🎌</button>
    </div>
  ` : `<div style="font-size:12px; color:var(--text-soft); align-self:center;">🏪 <strong>${currentShop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'}</strong></div>`;
  
  // ⭐ Round 7.75r36z: title + helper ตาม mode
  const modalTitle = mode === 'whosfree' ? '⚡ ตอนนี้ใครว่างบ้าง' : '📲 ส่งอัปเดตพนักงาน';
  const modalHelper = mode === 'whosfree'
    ? '💡 ตอบลูกค้าที่ถามว่าใครว่าง — ใช้ข้อมูลล่าสุด ส่งทาง LINE'
    : '💡 ส่งข้อความอัปเดตพนักงานล่าสุดให้ลูกค้าใน LINE · ใช้ทุกชั่วโมงได้';
  
  openModal(`
    <div class="modal" style="max-width:560px;">
      <div class="modal-head">
        <h3>${modalTitle}</h3>
        <div style="display:flex; align-items:center; gap:8px;">
          ${mode === 'whosfree' ? `<button id="hu-go-attime" style="background:linear-gradient(135deg,#0891b2,#0e7490); color:#fff; border:none; border-radius:999px; padding:7px 14px; font-size:12px; font-weight:700; cursor:pointer; white-space:nowrap; box-shadow:0 2px 6px rgba(8,145,178,0.25);">🕐 ระบุเวลา</button>` : ''}
          <button class="x-btn">×</button>
        </div>
      </div>
      <div class="modal-body">
        <div class="helper" style="margin-bottom:8px; font-size:11px;">
          ${modalHelper}
        </div>
        <!-- ⭐ Round 7.75r37: รวม 3 pickers แถวเดียว — ขยาย textarea -->
        <div style="display:flex; gap:8px; align-items:center; margin-bottom:10px; flex-wrap:wrap;">
          ${dayPicker}
          <span style="color:var(--text-mute); font-size:10px;">·</span>
          ${langPicker}
          <span style="color:var(--text-mute); font-size:10px;">·</span>
          ${shopButtons}
        </div>
        <textarea id="hu-text" rows="24" style="font-size:13px; line-height:1.6;">${escapeHtml(currentText)}</textarea>
        <div class="helper" style="margin-top:6px; font-size:11px;">
          💡 แก้ไขได้ก่อน Copy / ส่ง · กด "🔄" เพื่อใช้เวลาล่าสุด
        </div>
      </div>
      <div class="modal-foot">
        <button class="btn" id="hu-refresh">🔄 รีเฟรช</button>
        <div class="right-group">
          <button class="btn" id="hu-copy">📋 Copy</button>
          <button class="btn btn-accent btn-line" id="hu-share">📲 ส่งไป LINE</button>
        </div>
      </div>
    </div>
  `);
  
  // ⭐ Round 7.75r37: Helper — apply active state to pills
  function setPillActive(containerId, dataAttr, val) {
    $$(`#${containerId} button`).forEach(b => {
      const isAct = b.dataset[dataAttr] === val;
      if (isAct) {
        b.style.background = 'var(--accent)';
        b.style.color = '#fff';
      } else {
        b.style.background = 'var(--bg-elev-2)';
        b.style.color = 'var(--text-soft)';
      }
    });
  }
  
  // ⭐ Round 7.75r37: Day picker (วันนี้ / พรุ่งนี้)
  $$('#hu-day-pick button').forEach(b => {
    b.onclick = () => {
      currentDayOffset = parseInt(b.dataset.day, 10);
      setPillActive('hu-day-pick', 'day', String(currentDayOffset));
      $('#hu-text').value = buildHourlyUpdateText(currentShop, mode, currentDayOffset, currentLang);
    };
  });
  
  // ⭐ Round 7.75r37: Language picker (TH / EN)
  $$('#hu-lang-pick button').forEach(b => {
    b.onclick = () => {
      currentLang = b.dataset.lang;
      setPillActive('hu-lang-pick', 'lang', currentLang);
      $('#hu-text').value = buildHourlyUpdateText(currentShop, mode, currentDayOffset, currentLang);
    };
  });
  
  // Shop picker
  if (showShopPicker) {
    $$('#hu-shop-pick button').forEach(b => {
      b.onclick = () => {
        currentShop = b.dataset.shop;
        setPillActive('hu-shop-pick', 'shop', currentShop);
        $('#hu-text').value = buildHourlyUpdateText(currentShop, mode, currentDayOffset, currentLang);
      };
    });
  }
  
  // ⭐ r38r29af: ปุ่ม "🕐 ระบุเวลา" ใน header → เปิด modal เวลาแยก (ส่ง shop ปัจจุบันไปด้วย)
  const goAtTimeBtn = $('#hu-go-attime');
  if (goAtTimeBtn) goAtTimeBtn.onclick = () => {
    const passShop = (currentShop && currentShop !== 'both') ? currentShop : undefined;
    closeModal();
    setTimeout(() => openTimeAvailModal(passShop), 150);
  };
  
  // Refresh
  $('#hu-refresh').onclick = () => {
    $('#hu-text').value = buildHourlyUpdateText(currentShop, mode, currentDayOffset, currentLang);
    toast('✓ รีเฟรชแล้ว', 'success');
  };
  
  // Copy
  $('#hu-copy').onclick = async () => {
    const text = $('#hu-text').value;
    try {
      await navigator.clipboard.writeText(text);
      toast('✓ Copy แล้ว — ไปวางใน LINE ได้เลย', 'success');
    } catch (e) {
      $('#hu-text').select();
      document.execCommand('copy');
      toast('✓ Copy แล้ว', 'success');
    }
  };
  
  // Share to LINE
  $('#hu-share').onclick = async () => {
    const text = $('#hu-text').value;
    if (navigator.share) {
      try {
        await navigator.share({ text });
        return;
      } catch (e) {
        if (e.name === 'AbortError') return;
      }
    }
    window.open(`https://line.me/R/share?text=${encodeURIComponent(text)}`, '_blank');
  };
}

// ⭐ r38r29af: Modal แยก "เวลานี้ใครว่าง" — ใส่เวลา → กรอง → copy → จบ (ใช้ buildHourlyUpdateText atTimeStr)
function openTimeAvailModal(initShop) {
  let allowedShops = ['geisha', 'yoshi'];
  if (state.user?.role === 'pr') {
    allowedShops = Array.isArray(state.user.assignedShops) && state.user.assignedShops.length > 0
      ? state.user.assignedShops : [state.user.assignedShop || 'geisha'];
  }
  const masterLocked = state.shopFilter && state.shopFilter !== 'both';
  const showShopPick = allowedShops.length >= 2 && !masterLocked;
  let curShop = initShop || (masterLocked ? state.shopFilter : allowedShops[0]);
  if (curShop === 'both') curShop = allowedShops[0];
  let curLang = 'th';
  let curTime = '';
  
  const pill = `padding:6px 14px; border:none; border-radius:999px; font-size:13px; font-weight:600; cursor:pointer; background:#eee; color:#777;`;
  const pillAct = `background:#0891b2 !important; color:#fff !important;`;
  const preview = () => curTime ? buildHourlyUpdateText(curShop, 'whosfree', 0, curLang, curTime) : '';
  
  openModal(`
    <div class="modal" style="max-width:520px;">
      <div class="modal-head" style="background:linear-gradient(135deg,#0891b2,#0e7490); border:none;">
        <h3 style="color:#fff;">🕐 เวลานี้ใครว่าง</h3>
        <button class="x-btn" style="color:#fff;">×</button>
      </div>
      <div class="modal-body">
        <div class="helper" style="margin-bottom:10px; font-size:12px;">💡 ลูกค้าถามเวลาไหนว่าง → ใส่เวลา → คัดลอกส่งให้ลูกค้าได้เลย</div>
        <div style="display:flex; gap:8px; align-items:center; margin-bottom:12px; flex-wrap:wrap;">
          ${showShopPick ? `<div id="tav-shop" style="display:flex; gap:4px;">
            <button data-shop="geisha" style="${pill} ${curShop==='geisha'?pillAct:''}">🌸 Geisha</button>
            <button data-shop="yoshi" style="${pill} ${curShop==='yoshi'?pillAct:''}">🎌 Yoshi</button>
          </div>` : `<div style="font-size:13px; color:#666;">🏪 <strong>${curShop==='geisha'?'🌸 Geisha':'🎌 Yoshi'}</strong></div>`}
          <span style="color:#ccc;">·</span>
          <div id="tav-lang" style="display:flex; gap:4px;">
            <button data-lang="th" style="${pill} ${pillAct}">🇹🇭</button>
            <button data-lang="en" style="${pill}">🇬🇧</button>
          </div>
        </div>
        <label style="font-size:13px; font-weight:700; color:#0369a1; display:block; margin-bottom:6px;">🕐 ลูกค้าถามเวลาไหน?</label>
        <input type="text" id="tav-time" inputmode="numeric" maxlength="5" placeholder="เช่น 1400"
          style="width:100%; text-align:center; font-family:monospace; font-size:24px; padding:12px; border:2px solid #38bdf8; border-radius:10px; box-sizing:border-box; margin-bottom:4px;" autocomplete="off">
        <div id="tav-err" style="font-size:12px; color:#dc2626; margin-bottom:8px; text-align:center; min-height:16px;"></div>
        <textarea id="tav-out" rows="16" placeholder="ใส่เวลาด้านบนก่อน — ข้อความจะขึ้นที่นี่" style="font-size:13px; line-height:1.6;" readonly>${escapeHtml(preview())}</textarea>
      </div>
      <div class="modal-foot">
        <button class="btn x-btn">ปิด</button>
        <div class="right-group">
          <button class="btn" id="tav-copy" disabled style="opacity:0.5;">📋 Copy</button>
          <button class="btn btn-accent btn-line" id="tav-share" disabled style="opacity:0.5;">📲 ส่งไป LINE</button>
        </div>
      </div>
    </div>
  `);
  
  const rerender = () => {
    const out = $('#tav-out');
    if (out) out.value = preview();
    const has = !!curTime;
    ['tav-copy','tav-share'].forEach(id => { const b = $('#'+id); if (b) { b.disabled = !has; b.style.opacity = has ? '1' : '0.5'; } });
  };
  
  $$('.x-btn', $('#modal-host')).forEach(b => b.onclick = () => closeModal());
  $$('#tav-shop button').forEach(b => b.onclick = () => {
    curShop = b.dataset.shop;
    $$('#tav-shop button').forEach(x => { const a = x.dataset.shop===curShop; x.style.background = a?'#0891b2':'#eee'; x.style.color = a?'#fff':'#777'; });
    rerender();
  });
  $$('#tav-lang button').forEach(b => b.onclick = () => {
    curLang = b.dataset.lang;
    $$('#tav-lang button').forEach(x => { const a = x.dataset.lang===curLang; x.style.background = a?'#0891b2':'#eee'; x.style.color = a?'#fff':'#777'; });
    rerender();
  });
  const timeInp = $('#tav-time');
  if (timeInp && typeof bindNumericTimeInput === 'function') {
    bindNumericTimeInput(timeInp, { errorEl: $('#tav-err'), allowOutsideHours: true, onValid: (val) => {
      // ⭐ r38r29af: กันเวลาที่ผ่านไปแล้ว (< ตอนนี้) — ลูกค้าถามเวลาที่ยังมาทัน
      const now = new Date();
      const nowMin = now.getHours() * 60 + now.getMinutes();
      if (timeToMin(val) < nowMin) {
        curTime = '';
        const errEl = $('#tav-err'); if (errEl) errEl.textContent = `⚠️ ${val} ผ่านไปแล้ว (ตอนนี้ ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}) — ใส่เวลาถัดไป`;
        rerender();
        return;
      }
      const errEl = $('#tav-err'); if (errEl) errEl.textContent = '';
      curTime = val; rerender();
    } });
    setTimeout(() => timeInp.focus(), 100);
  }
  const copyBtn = $('#tav-copy');
  if (copyBtn) copyBtn.onclick = async () => {
    const text = $('#tav-out').value; if (!text) return;
    try { await navigator.clipboard.writeText(text); toast('✓ Copy แล้ว — วางใน LINE ได้เลย', 'success'); } catch (e) { toast('Copy ไม่ได้', 'error'); }
  };
  const shareBtn = $('#tav-share');
  if (shareBtn) shareBtn.onclick = async () => {
    const text = $('#tav-out').value; if (!text) return;
    if (navigator.share) { try { await navigator.share({ text }); return; } catch (e) { if (e.name === 'AbortError') return; } }
    window.open(`https://line.me/R/share?text=${encodeURIComponent(text)}`, '_blank');
  };
}
window.openTimeAvailModal = openTimeAvailModal;

// ⭐ Round 7.3: Wire up back button + Android hardware back
const _topbarBackBtn = $('#topbar-back-btn');
if (_topbarBackBtn) {
  _topbarBackBtn.onclick = () => goBack();
}
// Android hardware back / browser back: ถ้ามีประวัติใน VIEW_HISTORY ให้ใช้แทน
window.addEventListener('popstate', (e) => {
  if (state.user && VIEW_HISTORY.length > 1) {
    e.preventDefault();
    goBack();
    // Push state กลับเพื่อกัน Android ปิด app
    history.pushState({ app: true }, '');
  }
});
// ตอน app เริ่มทำงาน ใส่ initial state
if (typeof history !== 'undefined' && history.pushState) {
  history.replaceState({ app: true }, '');
}

// ⭐ Round 7.3 (7.10 fix): Navigation history stack — สำหรับปุ่มย้อนกลับ
// ใช้ var เพื่อ hoist (กัน TDZ ถ้า popstate fire ก่อนถึงบรรทัดนี้)
var VIEW_HISTORY = []; // stack of view names visited
var HOME_VIEW = 'dashboard';

function updateBackButton() {
  const backBtn = $('#topbar-back-btn');
  const brand = $('#topbar-brand');
  if (!backBtn || !brand) return;
  
  // ดูว่าปัจจุบันอยู่ที่ view ไหน
  const activeView = $$('.view').find(v => v.classList.contains('active'));
  const currentView = activeView?.id?.replace('view-', '') || HOME_VIEW;
  
  if (currentView === HOME_VIEW) {
    // หน้าหลัก → แสดง logo, ซ่อนปุ่ม back
    backBtn.style.display = 'none';
    brand.style.display = '';
  } else {
    // หน้าอื่น → แสดงปุ่ม back, ซ่อน logo
    backBtn.style.display = '';
    brand.style.display = 'none';
  }
}

function goBack() {
  // ถ้ามีประวัติ → ย้อนทีละขั้น, ถ้าไม่มี → กลับ home
  if (VIEW_HISTORY.length > 1) {
    VIEW_HISTORY.pop(); // เอา current ออก
    const prev = VIEW_HISTORY.pop(); // เอา previous (จะถูก push ซ้ำใน switchView)
    switchView(prev || HOME_VIEW);
  } else {
    switchView(HOME_VIEW);
  }
}

function switchView(name) {
  // ⭐ Round 7.22: Block PR from owner-only views
  const tabInfo = ALL_TABS_INFO.find(t => t.view === name);
  if (tabInfo?.ownerOnly && state.user?.role !== 'owner') {
    toast('เฉพาะ Owner ใช้งานได้', 'error');
    return;
  }
  
  // ⭐ Round 7.3: Push to history (skip duplicates ติดต่อกัน)
  const last = VIEW_HISTORY[VIEW_HISTORY.length - 1];
  if (last !== name) {
    VIEW_HISTORY.push(name);
    // จำกัด history ไม่ให้ยาวเกินไป
    if (VIEW_HISTORY.length > 20) VIEW_HISTORY.shift();
  }
  
  // Tabs (some tabs may be removed from .tabs since scan is in topbar)
  $$('.tabs button').forEach(b => b.classList.toggle('active', b.dataset.view === name));
  $$('.view').forEach(v => v.classList.toggle('active', v.id === 'view-' + name));

  // Highlight topbar scan button when on scan view
  const tsb = $('#topbar-scan-btn');
  if (tsb) tsb.classList.toggle('active-view', name === 'scan');

  // ⭐ Defensive: re-render bottom nav if missing/empty (fixes Round 7 bug: nav disappears after view switch)
  const bnEl = $('#bottom-nav');
  if (bnEl && (!bnEl.children.length || bnEl.children.length < 4)) {
    renderBottomNav();
  }

  // Update bottom nav active
  $$('.bottom-nav button').forEach(b => b.classList.toggle('active', b.dataset.view === name));

  // ⭐ Round 7.3: Update back button visibility
  updateBackButton();

  refreshAllViews();

  // start/stop scan camera
  if (name === 'scan') {
    // ⭐ r38r29et: sync ร้านสแกนตามแถบบน (GS/YS) ทุกครั้งที่เข้าหน้าสแกน
    try {
      const _eff = (typeof getEffectiveShop === 'function') ? getEffectiveShop() : null;
      if (_eff === 'geisha' || _eff === 'yoshi') _scanShop = _eff;
      $$('#scan-shop-pick button').forEach(x => x.classList.toggle('active', x.dataset.scanShop === _scanShop));
    } catch (e) {}
    initScanView();
  } else {
    stopQRScanner();
  }
  // load users list
  if (name === 'users') {
    renderUsersList();
  }
  // ⭐ Round 7.21: render day-staff view
  if (name === 'day-staff') {
    renderDayStaff();
  }
  // ⭐ Round 7.23: render manage-bookings
  if (name === 'manage-bookings') {
    renderManageBookings();
  }
  // ⭐ Round 7.61: render customers explicitly (fix bug: หน้าโล่งตอนกดเข้า)
  if (name === 'customers') {
    renderCustomers();
  }
  // ⭐ r38r29jt: render ค่าแรงทีมงาน
  if (name === 'team-payroll') {
    renderTeamPayroll();
  }
  // ⭐ r38r29m6: render ประชุม (เดิมไม่มี dispatch → กดบน PC แล้วหน้าว่าง)
  // ⭐ r38r29m7: bulletproof — สร้าง container + active ก่อน render (กรณี ensureMissingViewContainers หา main ไม่เจอตอน enterApp)
  if (name === 'meetings') {
    if (typeof ensureMissingViewContainers === 'function') ensureMissingViewContainers();
    const _vm = document.getElementById('view-meetings');
    if (_vm) $$('.view').forEach(v => v.classList.toggle('active', v === _vm));
    renderMeetingsView();
  }
  // ⭐ n32: render สร้างรูป (image hub)
  if (name === 'image-hub') {
    if (typeof ensureMissingViewContainers === 'function') ensureMissingViewContainers();
    const _vih = document.getElementById('view-image-hub');
    if (_vih) $$('.view').forEach(v => v.classList.toggle('active', v === _vih));
    renderImageHub();
  }
  // close any open mobile menu
  closeMobileMoreMenu();

  // scroll to top
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

// ─── PERMISSIONS — Owner เห็นทุก tab, PR เห็นทุก tab ยกเว้น "ผู้ใช้งาน" ──
function applyTabPermissions() {
  const isOwner = state.user?.role === 'owner';
  $$('.tabs button[data-owner-only]').forEach(b => {
    b.style.display = isOwner ? '' : 'none';
  });
}

// ═══════════════════════════════════════════════════════
// BOTTOM NAV — Mobile-first + Drag Reorder
// ═══════════════════════════════════════════════════════

