// ⭐ Round 7.75r38r15gg: Daily Attendance Report
// ════════════════════════════════════════════════════════════════
// ⭐ r38r15zzz: Weekly stats helpers + work-type classification
// ─────────────────────────────────────────

function getWorkTypeThresholds() {
  const cfg = state.config?.attendance || {};
  return {
    thresholdFreelance: parseInt(cfg.thresholdFreelance, 10) || 48,
    thresholdFulltime: parseInt(cfg.thresholdFulltime, 10) || 60,
  };
}

function classifyWorkType(totalHours) {
  const { thresholdFreelance, thresholdFulltime } = getWorkTypeThresholds();
  if (totalHours < thresholdFreelance) return 'freelance';
  if (totalHours <= thresholdFulltime) return 'parttime';
  return 'fulltime';
}

// ─── คำนวณวันจันทร์ของสัปดาห์ของวันที่ใดวันหนึ่ง ───
function getWeekStartMonday(dateStr) {
  const d = parseYmd ? parseYmd(dateStr) : new Date(dateStr);
  const day = d.getDay();  // 0=Sun, 1=Mon, ..., 6=Sat
  const diff = day === 0 ? -6 : 1 - day;
  d.setDate(d.getDate() + diff);
  return ymd(d);
}

function getWeekEndSunday(weekStart) {
  const d = parseYmd ? parseYmd(weekStart) : new Date(weekStart);
  d.setDate(d.getDate() + 6);
  return ymd(d);
}

function getDatesInWeek(weekStart) {
  const dates = [];
  const d = parseYmd ? parseYmd(weekStart) : new Date(weekStart);
  for (let i = 0; i < 7; i++) {
    const x = new Date(d);
    x.setDate(d.getDate() + i);
    dates.push(ymd(x));
  }
  return dates;
}

// ─── สรุปวันเดียวของพนง.คนหนึ่ง ───
//   ใช้ effectiveStart (ก่อน 11:00 นับเป็น 11:00) + หัก break + errand
function getStaffDailySummary(staffId, date) {
  const SHOP_OPEN_MIN = 11 * 60;
  const status = getStaffAttendanceStatus(staffId, date);
  
  if (!status.isClockedIn) {
    return {
      date,
      clockIn: null,
      clockOut: null,
      workedMin: 0,
      netWorkedMin: 0,
      totalBreakMin: 0,
      totalErrandMin: 0,
      breakCount: 0,
      errandCount: 0,
      lateness: null,
      lateMin: 0,
      shop: null,
      hasClockOut: false,
      autoClockOut: false,
    };
  }
  
  const clockInTimeMin = status.clockIn.timeMin;
  const effectiveStartMin = Math.max(clockInTimeMin, SHOP_OPEN_MIN);
  const lateMin = status.clockIn.lateMin || 0;
  const lateness = status.clockIn.lateness || null;
  
  let endMin;
  let hasClockOut = false;
  let autoClockOut = false;
  
  if (status.isClockedOut) {
    endMin = status.clockOut.timeMin;
    hasClockOut = true;
    autoClockOut = !!status.clockOut.autoClockOut;
  } else {
    // ยังไม่ออก — ใช้ now หรือ schedule end (ถ้าวันก่อน)
    const today = ymd(new Date());
    if (date < today) {
      // วันก่อนแต่ยังไม่ออก — fallback schedule end
      const sched = getStaffWorkingOn(date, staffId);
      endMin = sched ? timeToMin(sched.end) : effectiveStartMin;
    } else {
      // วันนี้ — ใช้ now
      const nowD = new Date();
      endMin = nowD.getHours() * 60 + nowD.getMinutes();
    }
  }
  
  const workedMin = Math.max(0, endMin - effectiveStartMin);
  const netWorkedMin = Math.max(0, workedMin - status.totalBreakMin - status.totalErrandMin);
  
  return {
    date,
    clockIn: status.clockIn.time,
    clockInActual: status.clockIn.time,
    effectiveStart: minToTime(effectiveStartMin),
    clockOut: status.clockOut?.time || null,
    workedMin,
    netWorkedMin,
    totalBreakMin: status.totalBreakMin,
    totalErrandMin: status.totalErrandMin,
    breakCount: status.breaks.length,
    errandCount: status.errands.length,
    lateness,
    lateMin,
    shop: status.clockIn.shop,
    hasClockOut,
    autoClockOut,
    autoClockOutReason: status.clockOut?.autoClockOutReason || null,
  };
}

// ─── สรุปสัปดาห์ของพนง.คนหนึ่ง ───
function getStaffWeeklySummary(staffId, weekStart) {
  const dates = getDatesInWeek(weekStart);
  const dailies = dates.map(d => ({
    ...getStaffDailySummary(staffId, d),
    dayOfWeek: parseYmd ? parseYmd(d).getDay() : new Date(d).getDay(),
  }));
  
  const workedDays = dailies.filter(d => d.clockIn);
  const totalMin = workedDays.reduce((sum, d) => sum + d.netWorkedMin, 0);
  const totalHours = totalMin / 60;
  
  // By shop
  const geishaMin = workedDays.filter(d => d.shop === 'geisha').reduce((sum, d) => sum + d.netWorkedMin, 0);
  const yoshiMin = workedDays.filter(d => d.shop === 'yoshi').reduce((sum, d) => sum + d.netWorkedMin, 0);
  
  // Lateness
  const ontimeCount = workedDays.filter(d => d.lateness === 'ontime').length;
  const late15Count = workedDays.filter(d => d.lateness === 'late_15').length;
  const lateOverCount = workedDays.filter(d => d.lateness === 'late_over').length;
  const totalLateMin = workedDays.reduce((sum, d) => sum + Math.max(0, d.lateMin || 0), 0);
  const latenessPct = workedDays.length > 0 
    ? Math.round((late15Count + lateOverCount) / workedDays.length * 100) 
    : 0;
  
  // Breaks + errands
  const totalBreakMin = workedDays.reduce((sum, d) => sum + d.totalBreakMin, 0);
  const totalErrandMin = workedDays.reduce((sum, d) => sum + d.totalErrandMin, 0);
  
  // Classification
  const workType = classifyWorkType(totalHours);
  
  return {
    staffId,
    weekStart,
    weekEnd: getWeekEndSunday(weekStart),
    dailies,
    totalDays: workedDays.length,
    totalMin,
    totalHours,
    geishaMin,
    yoshiMin,
    geishaHours: geishaMin / 60,
    yoshiHours: yoshiMin / 60,
    ontimeCount,
    late15Count,
    lateOverCount,
    totalLateMin,
    latenessPct,
    totalBreakMin,
    totalErrandMin,
    workType,
    needsReview: lateOverCount >= 3,  // alert if สาย >15' 3+ครั้ง
    overtime: totalHours > 60,
  };
}

// Expose
window.classifyWorkType = classifyWorkType;
window.getStaffWeeklySummary = getStaffWeeklySummary;
window.getStaffDailySummary = getStaffDailySummary;
window.getWeekStartMonday = getWeekStartMonday;

