// ════════════════════════════════════════════════════════
// ⭐ Round 7.74a: WALK-IN DETAIL MODAL (read-only view)
// ════════════════════════════════════════════════════════

// Permission: Owner หรือ PR ที่สร้าง walkin นั้น
function canEditWalkin(w) {
  if (!state.user || !w) return false;
  // ⭐ r38r26z33: cancelled walkin → ไม่อนุญาตแก้ (ต้อง undelete ก่อน)
  //   เคส: PR ลบรอบไปแล้ว → status='cancelled' + active=false
  //   ไม่ควรเปิด edit modal ได้ (สับสน)
  if (w.status === 'cancelled') return false;
  if (state.user.role === 'owner') return true;
  // ⭐ Round 7.75: PR แก้ได้ทุกอันใน shop ที่ตัวเองดูแล
  if (state.user.role === 'pr') {
    const allowedShops = Array.isArray(state.user.assignedShops) && state.user.assignedShops.length > 0
      ? state.user.assignedShops
      : [state.user.assignedShop || 'geisha'];
    if (!allowedShops.includes(w.shop)) return false;
    
    // ⭐ r38r26z30: เช็ค backfill limit สำหรับ PR
    //   - วันนี้ + grace period (00:00-06:00) → แก้ได้ปกติ
    //   - ย้อนหลัง > ลิมิต (default 15 · Owner ตั้งได้) → block
    //   - ย้อนหลัง 1-ลิมิต วัน → ต้องปลดล็อค (PIN) ก่อน
    if (w.date && typeof calcDaysAgo === 'function') {
      const daysAgo = calcDaysAgo(w.date);
      const grace = (new Date()).getHours() < 6;  // 00:00-06:00 grace
      if (daysAgo === 0) return true;             // วันนี้
      if (grace && daysAgo === 1) return true;    // grace period: เมื่อวาน
      if (daysAgo > getBackfillLimitDays()) return false;  // ⭐ r38r29gq: เกินลิมิต (Owner ตั้งได้) → block
      // 1-14 วัน → ต้องปลดล็อค (PIN)
      if (typeof isPastUnlocked === 'function' && !isPastUnlocked()) return false;
    }
    return true;
  }
  return false;
}

// ⭐ Round 7.75r38r14m: Conflict Override Modal
//   แสดงเมื่อ checkSlotAvailability fail + canOverride=true + setting=on
//   - แสดงรายละเอียด conflict (ใคร/เวลา/เบอร์)
//   - ปุ่ม โทร / LINE / ยกเลิก / ✓ ยืนยันลงทับ
//   - ถ้า confirm → callback onConfirm({forceOverride:true, overrideConflict:{...}})
// ════════════════════════════════════════════════════════════════
// ⭐ Round 7.75r38r14s — Room-Full Lock Module
//   PR ตัดสินใจเอง: ห้องเต็ม → ตั้งเวลาที่ห้องจะว่าง → ระบบ block ลงรอบใหม่ก่อนเวลานั้น
//   Storage: state.config.roomFullLock = { geisha: {active, openAt, setBy, setAt}, yoshi: {...} }
// ════════════════════════════════════════════════════════════════

// Get current lock for a shop — return null if not active or expired
function getRoomFullLockForShop(shop) {
  if (!shop || shop === 'both') return null;
  const lock = state.config?.roomFullLock?.[shop];
  if (!lock || !lock.active || !lock.openAt) return null;
  // ⭐ Auto-expire — ถ้าตอนนี้ผ่าน openAt ไปแล้ว → ถือว่าหมดอายุ
  const now = new Date();
  const nowMin = now.getHours() * 60 + now.getMinutes();
  const openMin = timeToMin(lock.openAt);
  if (nowMin >= openMin) return null;
  return lock;
}

// Check if start time is blocked by room-full lock
// Return { blocked: true, reason } | { blocked: false }
function checkRoomFullBlock(shop, startTime) {
  const lock = getRoomFullLockForShop(shop);
  if (!lock) return { blocked: false };
  const startMin = timeToMin(startTime);
  const openMin = timeToMin(lock.openAt);
  if (startMin < openMin) {
    return { 
      blocked: true, 
      reason: `ห้องเต็ม — รับรอบได้ตั้งแต่ ${lock.openAt}`,
      openAt: lock.openAt,
    };
  }
  return { blocked: false };
}

// ════════════════════════════════════════════════════════════════
// ⭐ r38r29bx: Room CAPACITY auto-warning (เตือนห้องไม่พอ)
//   แยกจาก Room-Full Lock (manual). อันนี้นับ "รอบพร้อมกัน" เทียบจำนวนห้องจริง
//   กฎนับ 1 ห้อง: เดี่ยว · คู่(รวม coupleId) · 3-4คน · ลูกค้าเดียวกันรอบติด(รวมช่วง)
//   ไม่บล็อก — แค่เตือนให้ PR ตัดสินใจ (รอ/โทรเลื่อน/ลงต่อ)
//   Storage: state.config.rooms = { geisha: 12, yoshi: 8 }
// ════════════════════════════════════════════════════════════════
const ROOM_CAP_DEFAULT = { geisha: 12, yoshi: 8 };

function getRoomCapacityForShop(shop) {
  const c = state.config?.rooms?.[shop];
  if (typeof c === 'number' && c > 0) return c;
  return ROOM_CAP_DEFAULT[shop] || 12;
}

// normalize customer key (phone > member > name, strip honorific + "คู่/กลุ่ม" suffix)
function _roomCustKey(rec) {
  const ph = String(rec.customerPhone || rec.phone || '').replace(/[^0-9]/g, '');
  if (ph) return 'p:' + ph;
  const mc = String(rec.memberCode || '').trim().toUpperCase();
  if (mc) return 'm:' + mc;
  const nm = String(rec.customerName || '').trim()
    .replace(/^(พี่|น้อง|คุณ|คุน|พี)\s*/, '')
    .replace(/\s*(คู่|กลุ่ม).*$/, '').trim().toLowerCase();
  if (nm && nm.length >= 2) return 'n:' + nm;
  return '';  // unknown → แต่ละอันเป็นห้องแยก
}

// gather active booking+walkin records for shop/date (skip cancelled + checked-in-dup)
function _roomGatherRecords(shop, dateStr, excludeId) {
  const recs = [];
  const ok = (x) => (shop === 'both') || (x.shop === shop);
  (state.bookings || []).forEach(b => {
    if (b.date !== dateStr || b.status === 'cancelled') return;
    if (b.checkedInWalkinId) return;
    if (excludeId && b.id === excludeId) return;
    if (!ok(b)) return;
    recs.push({ s: timeToMin(b.startTime), e: timeToMin(b.endTime), custKey: _roomCustKey(b), coupleId: b.coupleId || null, label: (b.customerName || b.memberCode || 'จอง'), kind: 'booking' });
  });
  (state.walkins || []).forEach(w => {
    if (w.date !== dateStr) return;
    if (!['active', 'walkin', 'early', 'completed'].includes(w.status)) return;
    if (excludeId && w.id === excludeId) return;
    if (!ok(w)) return;
    recs.push({ s: timeToMin(w.startTime), e: timeToMin(getEffectiveEndTime(w) || w.endTime || '00:00'), custKey: _roomCustKey(w), coupleId: w.coupleId || null, label: (w.customerName || w.memberCode || 'walk-in'), kind: 'walkin' });
  });
  return recs;
}

// merge records → room-occupancy UNITS (couple + same-customer consecutive → 1 unit)
function computeRoomUnits(shop, dateStr, extraRecords = [], excludeId = null) {
  let recs = _roomGatherRecords(shop, dateStr, excludeId).concat(extraRecords || []);
  if (recs.length === 0) return [];
  // 1) merge couples by coupleId → 1 unit
  const byCouple = {}; const units0 = [];
  recs.forEach(r => {
    if (r.coupleId) {
      if (!byCouple[r.coupleId]) { byCouple[r.coupleId] = { ...r, members: [r.label] }; units0.push(byCouple[r.coupleId]); }
      else { const u = byCouple[r.coupleId]; u.s = Math.min(u.s, r.s); u.e = Math.max(u.e, r.e); u.members.push(r.label); u.custKey = u.custKey || r.custKey; }
    } else { units0.push({ ...r, members: [r.label] }); }
  });
  // 2) merge same-customer adjacent/overlapping (gap ≤ BUFFER) → 1 unit (ลูกค้าเดียวกันรอบติด)
  const TOL = (typeof BUFFER_MIN === 'number' ? BUFFER_MIN : 5);
  const known = units0.filter(u => u.custKey);
  const unknown = units0.filter(u => !u.custKey);
  const byKey = {};
  known.forEach(u => { (byKey[u.custKey] = byKey[u.custKey] || []).push(u); });
  const merged = [];
  Object.values(byKey).forEach(arr => {
    arr.sort((a, b) => a.s - b.s);
    let cur = null;
    arr.forEach(u => {
      if (cur && u.s <= cur.e + TOL) { cur.e = Math.max(cur.e, u.e); cur.members = cur.members.concat(u.members); }
      else { cur = { ...u, members: u.members.slice() }; merged.push(cur); }
    });
  });
  return merged.concat(unknown).map(u => ({ s: u.s, e: u.e, label: u.members.join('+'), kind: u.kind }));
}

// peak concurrent units overlapping [winStart, winEnd]
function roomPeakInWindow(units, winStart, winEnd) {
  let peak = 0, peakAt = winStart;
  const pts = new Set([winStart]);
  units.forEach(u => { if (u.s >= winStart && u.s < winEnd) pts.add(u.s); });
  for (const t of pts) {
    if (t < winStart || t >= winEnd) continue;
    let c = 0;
    units.forEach(u => { if (u.s <= t && u.e > t) c++; });
    if (c > peak) { peak = c; peakAt = t; }
  }
  return { peak, peakAt };
}

// MAIN: would adding newRecord exceed capacity in its window?
//   newRecord = { shop, date, startTime, endTime, customerPhone/memberCode/customerName, coupleId? }
//   return { willExceed, peak, capacity, peakStart, conflictUnits[] }
function checkRoomCapacity(newRecord, opts = {}) {
  const shop = newRecord.shop, dateStr = newRecord.date;
  if (!shop || shop === 'both' || !dateStr) return { willExceed: false };
  const capacity = getRoomCapacityForShop(shop);
  const ns = timeToMin(newRecord.startTime), ne = timeToMin(newRecord.endTime);
  if (!(ne > ns)) return { willExceed: false };
  const extra = [{ s: ns, e: ne, custKey: _roomCustKey(newRecord), coupleId: newRecord.coupleId || null, label: (newRecord.customerName || newRecord.memberCode || 'รอบใหม่'), kind: 'new' }];
  const unitsWith = computeRoomUnits(shop, dateStr, extra, opts.excludeId || null);
  const { peak, peakAt } = roomPeakInWindow(unitsWith, ns, ne);
  if (peak <= capacity) return { willExceed: false, peak, capacity };
  const conflictUnits = unitsWith.filter(u => u.s <= peakAt && u.e > peakAt)
    .map(u => ({ label: u.label, start: minToTime(u.s), end: minToTime(u.e) }));
  return { willExceed: true, peak, capacity, peakAt, peakStart: minToTime(peakAt), conflictUnits };
}

// usage summary for dashboard indicator
function getRoomUsageSummary(shop, dateStr) {
  const cap = getRoomCapacityForShop(shop);
  const units = computeRoomUnits(shop, dateStr);
  const now = (new Date()).getHours() * 60 + (new Date()).getMinutes();
  let current = 0;
  units.forEach(u => { if (u.s <= now && u.e > now) current++; });
  const { peak, peakAt } = roomPeakInWindow(units, 0, 24 * 60);
  return { current, peak, peakAt, cap, peakTime: minToTime(peakAt) };
}

// small dashboard line: "🏠 ห้อง: ใช้อยู่ X/cap · peak HH:MM"
function buildRoomUsageLine(shop) {
  try {
    if (!shop || shop === 'both') return '';
    const ru = getRoomUsageSummary(shop, ymd(new Date()));
    const icon = shop === 'yoshi' ? '🎌' : '🌸';
    const col = ru.current >= ru.cap ? '#dc2626' : (ru.current >= ru.cap - 2 ? '#d97706' : '#16a34a');
    const peakTxt = ru.peak >= ru.cap
      ? ` · <span style="color:#dc2626; font-weight:700;">peak ${ru.peakTime} เต็ม</span>`
      : (ru.peak > 0 ? ` · peak ${ru.peakTime}: ${ru.peak}` : '');
    return `<div style="display:flex; align-items:center; gap:5px; font-size:11px; color:${col}; font-weight:600; margin:6px 2px 0;">🏠 <span>${icon} ห้อง: ใช้อยู่ <strong>${ru.current}/${ru.cap}</strong>${peakTxt}</span></div>`;
  } catch (e) { return ''; }
}

// async confirm gate — เด้ง modal เตือน, return Promise<boolean> (true=ลงต่อ)
function confirmRoomCapacity(rec, opts = {}) {
  return new Promise((resolve) => {
    let res;
    try { res = checkRoomCapacity(rec, opts); } catch (e) { console.error('checkRoomCapacity:', e); resolve(true); return; }
    if (!res || !res.willExceed) { resolve(true); return; }
    const shopLabel = rec.shop === 'yoshi' ? '🎌 Yoshi' : '🌸 Geisha';
    const list = (res.conflictUnits || []).slice(0, 8).map(u =>
      `<div style="display:flex; justify-content:space-between; gap:8px; padding:3px 0; border-bottom:1px solid #f3f4f6;"><span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">• ${escapeHtml(u.label)}</span><span style="color:#6b7280; flex-shrink:0; font-family:monospace;">${u.start}–${u.end}</span></div>`
    ).join('');
    const moreN = Math.max(0, (res.conflictUnits || []).length - 8);
    const ov = document.createElement('div');
    ov.id = 'room-cap-warn-overlay';
    ov.style.cssText = 'position:fixed; inset:0; z-index:99999; background:rgba(0,0,0,0.55); display:flex; align-items:center; justify-content:center; padding:16px;';
    ov.innerHTML = `<div style="background:#fff; border-radius:16px; max-width:440px; width:100%; overflow:hidden; box-shadow:0 12px 44px rgba(0,0,0,0.3);">
      <div style="background:linear-gradient(135deg,#fee2e2,#fecaca); padding:15px 18px; border-bottom:2px solid #ef4444;">
        <div style="font-size:17px; font-weight:800; color:#991b1b;">⚠️ ห้องอาจไม่พอ!</div>
      </div>
      <div style="padding:18px;">
        <div style="font-size:15px; color:#1f2937; line-height:1.55;">ช่วง <strong style="color:#dc2626;">${res.peakStart}</strong> จะมี <strong style="color:#dc2626;">${res.peak} รอบ</strong> · ${shopLabel} มี <strong>${res.capacity} ห้อง</strong> <span style="display:inline-block; background:#fee2e2; color:#991b1b; padding:1px 8px; border-radius:6px; font-weight:700; font-size:13px;">เกิน ${res.peak - res.capacity}</span></div>
        <div style="margin-top:12px; font-size:12px; color:#6b7280; font-weight:600;">รอบที่ใช้ห้องช่วงนั้น:</div>
        <div style="margin-top:4px; max-height:170px; overflow:auto; font-size:13px; color:#374151;">${list}${moreN > 0 ? `<div style="color:#9ca3af; font-size:12px; margin-top:4px;">+ อีก ${moreN} รอบ</div>` : ''}</div>
        <div style="margin-top:13px; padding:9px 12px; background:#fffbeb; border:1px solid #fde68a; border-radius:8px; font-size:12px; color:#92400e; line-height:1.5;">💡 ประเมินเอง: ให้ walk-in รอ · โทรเลื่อนลูกค้าจอง · หรือลงต่อถ้าจัดห้องได้</div>
        <div style="display:flex; gap:10px; margin-top:15px;">
          <button id="rcw-cancel" style="flex:1; padding:12px; background:#fff; border:1.5px solid #d1d5db; color:#374151; border-radius:10px; font-weight:700; font-size:14px; cursor:pointer;">ยกเลิก</button>
          <button id="rcw-proceed" style="flex:1; padding:12px; background:#dc2626; border:none; color:#fff; border-radius:10px; font-weight:700; font-size:14px; cursor:pointer;">ลงต่อ</button>
        </div>
        <button id="rcw-setfull" style="width:100%; margin-top:8px; padding:9px; background:transparent; border:1px dashed #f59e0b; color:#b45309; border-radius:8px; font-size:12px; font-weight:600; cursor:pointer;">🚪 ตั้งสถานะ "ห้องเต็ม" แทน</button>
      </div>
    </div>`;
    document.body.appendChild(ov);
    const done = (val) => { try { ov.remove(); } catch (e) {} resolve(val); };
    ov.querySelector('#rcw-cancel').onclick = () => done(false);
    ov.querySelector('#rcw-proceed').onclick = () => done(true);
    ov.querySelector('#rcw-setfull').onclick = () => { done(false); if (typeof openRoomFullLockModal === 'function') openRoomFullLockModal(rec.shop); };
    ov.onclick = (e) => { if (!_isDesktopNoTouch() && e.target === ov) done(false); };
  });
}

// Open modal — ตั้งค่าล็อก ห้องเต็ม
function openRoomFullLockModal(shop) {
  if (!shop || shop === 'both') {
    toast('กรุณาเลือกร้าน (Geisha หรือ Yoshi) ก่อน', 'info');
    return;
  }
  const shopLabel = shop === 'yoshi' ? '🎌 Yoshi' : '🌸 Geisha';
  const cur = state.config?.roomFullLock?.[shop];
  const defaultTime = cur?.openAt || (() => {
    // default = ตอนนี้ + 30 นาที ปัด :10
    const now = new Date();
    const future = new Date(now.getTime() + 30 * 60 * 1000);
    const m = Math.ceil(future.getMinutes() / 10) * 10;
    const h = future.getHours() + (m >= 60 ? 1 : 0);
    return String(h).padStart(2,'0') + ':' + String(m % 60).padStart(2,'0');
  })();
  
  const html = `
    <div class="modal" style="max-width:420px;">
      <div style="background:linear-gradient(135deg, #fef3c7, #fde68a); padding:16px 18px; border-bottom:2px solid #f59e0b;">
        <h3 style="margin:0; font-size:17px; color:#78350f; display:flex; align-items:center; gap:8px;">
          🚪 ตั้งล็อกห้องเต็ม — ${shopLabel}
        </h3>
      </div>
      <div style="padding:18px;">
        <div style="font-size:13px; color:var(--text-soft); margin-bottom:6px;">
          ห้องจะว่างเมื่อไหร่? <span style="color:var(--text-mute);">(พิมพ์ตัวเลข เช่น 1550)</span>
        </div>
        <input id="rfl-time" type="text" inputmode="numeric" maxlength="5" placeholder="เช่น 1550"
          value="${defaultTime}" autocomplete="off" style="
          width:100%; padding:14px; border:1.5px solid var(--line); border-radius:10px;
          font-size:22px; text-align:center; font-family:'JetBrains Mono', monospace; font-weight:700;
        "/>
        <div id="rfl-time-err" style="display:none; margin-top:6px; font-size:11px;"></div>
        
        <div style="background:#fef3c7; padding:11px 13px; border-radius:9px; margin-top:14px; font-size:12px; color:#92400e;">
          💡 ระบบจะไม่ให้ลงรอบ walkin/booking ก่อนเวลานี้<br>
          จนกว่าคุณจะปลดล็อก (เลื่อนปุ่มกลับ)
        </div>
      </div>
      <div style="padding:12px 18px 16px; border-top:1px solid var(--line); display:flex; gap:8px;">
        <button class="x-btn" style="
          flex:1; padding:11px; background:transparent; border:1.5px solid var(--line);
          border-radius:9px; cursor:pointer; color:var(--text); font-size:13px; font-weight:600;
        ">ยกเลิก</button>
        <button id="rfl-save" style="
          flex:1.5; padding:11px; background:linear-gradient(135deg, #f59e0b, #d97706); border:none;
          border-radius:9px; cursor:pointer; color:#fff; font-size:13px; font-weight:700;
          box-shadow:0 2px 6px rgba(245, 158, 11, 0.3);
        ">🔒 ล็อก</button>
      </div>
    </div>
  `;
  openModal(html);
  
  // Wire numeric time input
  const inp = $('#rfl-time');
  let validTime = defaultTime;
  if (inp && typeof bindNumericTimeInput === 'function') {
    bindNumericTimeInput(inp, {
      errorEl: $('#rfl-time-err'),
      onValid: (val) => { if (val) validTime = val; }
    });
  }
  
  // Save
  $('#rfl-save')?.addEventListener('click', async () => {
    if (!validTime) {
      toast('กรุณาใส่เวลา', 'error');
      return;
    }
    // Save to Firestore — merge into config/roomFullLock
    try {
      const existing = state.config?.roomFullLock || {};
      const payload = {
        ...existing,
        [shop]: {
          active: true,
          openAt: validTime,
          setBy: state.user?.name || state.user?.username || '?',
          setAt: serverTimestamp(),
        }
      };
      await setDoc(doc(db, 'config', 'roomFullLock'), payload, { merge: true });
      toast(`🔒 ล็อก ${shopLabel} — รับรอบได้ ${validTime}`, 'success', 3000);
      closeModal();
    } catch (e) {
      console.error('Room-full lock save error:', e);
      toast(`❌ บันทึกไม่สำเร็จ: ${e.message}`, 'error');
    }
  });
}
window.openRoomFullLockModal = openRoomFullLockModal;

// Unlock (toggle off)
async function unlockRoomFull(shop) {
  if (!shop || shop === 'both') return;
  if (!confirm(`ปลดล็อกห้องเต็ม ${shop === 'yoshi' ? 'Yoshi' : 'Geisha'} ?`)) return;
  try {
    const existing = state.config?.roomFullLock || {};
    const payload = {
      ...existing,
      [shop]: { active: false, openAt: null, unlockedBy: state.user?.name || '?', unlockedAt: serverTimestamp() }
    };
    await setDoc(doc(db, 'config', 'roomFullLock'), payload, { merge: true });
    toast(`✅ ปลดล็อก ${shop === 'yoshi' ? 'Yoshi' : 'Geisha'}`, 'success');
  } catch (e) {
    toast(`❌ ${e.message}`, 'error');
  }
}
window.unlockRoomFull = unlockRoomFull;

