    if (form.bookingType === 'couple' && !form.staffId2) { toast('คอร์สคู่ ต้องเลือกพนักงานคนที่ 2', 'error'); return; }
    if (form.bookingType === 'couple' && form.staffId === form.staffId2) { toast('พนักงานคนที่ 1 และ 2 ต้องคนละคน', 'error'); return; }
    // ⭐ Round 7.75r37: บังคับ PR Handler
    if (!form.prHandlerType || !form.prHandlerName) { toast('เลือก PR ผู้รับรอบ', 'error'); return; }
    
