function wireWalkinStep3_GroupSize() {
  // ⭐ Round 7.75r37: next from step 3 → step 12 (CustomerType) ก่อน step 4
  //   เหตุผล: เลือก member ก่อน → step 4 (name) จะบังคับใส่รหัสเมม + ราคาเมมทำงานทันที
  const nextAfterGroup = () => {
    walkinWiz.currentPersonIndex = 0;
    walkinWiz.step = 12;  // ไป CustomerType ก่อน
    renderWalkinWizard();
  };
  
  $$('.wlk-grp-btn').forEach(b => {
    b.onclick = () => {
      walkinWiz.groupSize = parseInt(b.dataset.size);
      $('#wlk-custom-size').value = '';
      nextAfterGroup();
    };
  });
  
  $('#wlk-custom-size').oninput = (e) => {
    const v = parseInt(e.target.value);
    if (!isNaN(v) && v >= 1 && v <= 20) {
      walkinWiz.groupSize = v;
      $$('.wlk-grp-btn').forEach(b => {
        b.style.borderColor = 'var(--line)';
        b.style.background = 'var(--bg-elev)';
        b.style.color = 'var(--text)';
      });
    }
  };
  
  const footEl = $('.modal-foot');
  if (footEl && !$('#wlk-next-custom')) {
    footEl.insertAdjacentHTML('beforeend',
      `<button class="btn btn-accent" id="wlk-next-custom">ถัดไป ▶</button>`
    );
    $('#wlk-next-custom').onclick = () => {
      if (walkinWiz.groupSize < 1) walkinWiz.groupSize = 1;
      nextAfterGroup();
    };
  }
}

