// ─── CUSTOMERS ──────────────────────────────────────
// ⭐ Round 7.61: Customer view state (filter + sort)
const custViewState = { filter: 'all', sort: 'recent' };

// ⭐ Round 7.63a: helpers — รองรับ memberships array + legacy single fields
function getCustomerMemberships(customer) {
  if (!customer) return [];
  if (Array.isArray(customer.memberships) && customer.memberships.length > 0) {
    return customer.memberships;
  }
  // Fallback to legacy single fields
  if (customer.memberCode) {
    return [{
      code: customer.memberCode,
      shop: customer.memberShop || 'geisha',
      since: customer.memberSince || ''
    }];
  }
  return [];
}

// ลูกค้าเป็นเมมร้านนั้นไหม
function isCustomerMemberOf(customer, shop) {
  return getCustomerMemberships(customer).some(m => m.shop === shop);
}

// ลูกค้าตรงกับร้านนั้นไหม (เมม OR เคยจองที่ร้านนั้น)
function customerBelongsToShop(customer, shop, bookings) {
  if (!customer) return false;
  if (isCustomerMemberOf(customer, shop)) return true;
  if (!Array.isArray(bookings)) return false;
  return bookings.some(b =>
    b.customerPhone === customer.id && b.shop === shop && b.status !== 'cancelled'
  );
}

// ⭐ Round 7.67: หา booking ครั้งแรกของลูกค้า (ใช้ทั้ง customerPhone และ id ถ้ามี)
//   return: timestamp (ms) ของ booking เก่าสุด หรือ null ถ้าไม่มี
function getFirstBookingTime(customerPhone) {
  if (!customerPhone) return null;
  const bookings = (state.bookings || []).filter(b => 
    b.customerPhone === customerPhone && b.status !== 'cancelled'
  );
  if (bookings.length === 0) return null;
  
  // ใช้ createdAt timestamp เป็นหลัก, fallback ไปใช้ date+startTime
  const times = bookings.map(b => {
    if (b.createdAt) {
      // Firestore Timestamp object
      if (typeof b.createdAt.toMillis === 'function') return b.createdAt.toMillis();
      // ms number
      if (typeof b.createdAt === 'number') return b.createdAt;
      // Date-like
      if (b.createdAt.seconds) return b.createdAt.seconds * 1000;
    }
    // Fallback: parse date + startTime
    if (b.date && b.startTime) {
      const [y, m, d] = b.date.split('-').map(Number);
      const [hh, mm] = b.startTime.split(':').map(Number);
      return new Date(y, m - 1, d, hh, mm).getTime();
    }
    return null;
  }).filter(t => t !== null);
  
  if (times.length === 0) return null;
  return Math.min(...times);
}

// ⭐ Round 7.67: ลูกค้าเป็นใหม่ไหม (ภายใน 7 วันจาก booking ครั้งแรก)
const NEW_CUSTOMER_DAYS = 7;
function isCustomerNew(customerPhone) {
  const firstTs = getFirstBookingTime(customerPhone);
  if (!firstTs) return false;   // ไม่มี booking เก่าเลย → ไม่ใช่ "ใหม่ 7 วัน"
  const now = Date.now();
  const ageDays = (now - firstTs) / (1000 * 60 * 60 * 24);
  return ageDays <= NEW_CUSTOMER_DAYS;
}

// ⭐ Round 7.67: helper - booking นี้ถือเป็น "ลูกค้าใหม่" ไหม
//   - ถ้า customerPhone ของ booking มี isCustomerNew → true
//   - fallback: ถ้าไม่มี customerPhone (booking เก่ามาก) → ใช้ flag เดิม
function isBookingFromNewCustomer(booking) {
  if (!booking) return false;
  if (booking.customerPhone) {
    return isCustomerNew(booking.customerPhone);
  }
  // fallback (legacy bookings ที่ไม่มี customerPhone)
  return booking.isNewCustomer === true || booking.customerType === 'new';
}

// ⭐ Round 7.75r38: นับจำนวนรอบของลูกค้าเดียวกันในวันเดียวกัน
//   ใช้แสดง badge "🔗 N รอบติด" บน booking card
function countSameCustomerBookings(booking) {
  if (!booking || !booking.customerPhone || !booking.date) return 1;
  return state.bookings.filter(b => 
    b.customerPhone === booking.customerPhone && 
    b.date === booking.date && 
    b.status !== 'cancelled' &&
    !b.checkedInWalkinId
  ).length;
}

// ════════════════════════════════════════════════════════════════
// ⭐ r38r28u: Linked Bookings (จองหลายรอบ) — Phase 1 helpers
// ════════════════════════════════════════════════════════════════
// กฎการผูกรอบ (priority):
//   1. 📞 เบอร์ตรง → ผูก (ข้ามวันได้ — จองชุดเดียว)
//   2. 👑 memberCode ตรง → ผูก (ข้ามวันได้)
//   3. 📝 ชื่อตรง + เวลาติดกัน ≤30 นาที + วันเดียว → ผูก (กันชื่อซ้ำคนละคน)
// ────────────────────────────────────────────────────────────────

// normalize เบอร์ — strip ทุกอย่างที่ไม่ใช่ตัวเลข
function _normPhoneLink(p) {
  return String(p || '').replace(/[^0-9]/g, '');
}

// เช็คว่า booking 2 ตัวเป็นลูกค้าคนเดียวกันไหม (สำหรับผูกรอบ)
//   strongOnly=true → ใช้เฉพาะเบอร์/เมม (ไม่ใช้ชื่อ)
function isSameCustomerForLink(a, b, opts = {}) {
  if (!a || !b) return false;
  const aPhone = _normPhoneLink(a.customerPhone);
  const bPhone = _normPhoneLink(b.customerPhone);
  if (aPhone && bPhone && aPhone === bPhone) return { match: true, by: 'phone' };
  
  const aMem = String(a.memberCode || '').trim().toUpperCase();
  const bMem = String(b.memberCode || '').trim().toUpperCase();
  if (aMem && bMem && aMem === bMem) return { match: true, by: 'member' };
  
  if (opts.strongOnly) return false;
  
  // ชื่อ — ต้องมีเวลาติดกัน + วันเดียวกันด้วย (กันชื่อซ้ำคนละคน)
  const aName = String(a.customerName || '').trim().toLowerCase();
  const bName = String(b.customerName || '').trim().toLowerCase();
  if (aName && bName && aName.length >= 2 && bName.length >= 2) {
    let nameMatch = (aName === bName);
    if (!nameMatch) {
      // partial: "พี่หนุ่ม" vs "พี่หนุ่ม คู่"
      const shorter = aName.length < bName.length ? aName : bName;
      const longer = aName.length < bName.length ? bName : aName;
      if (longer.startsWith(shorter + ' ') || longer.startsWith(shorter + '+') || longer.startsWith(shorter + '-')) nameMatch = true;
    }
    if (nameMatch && a.date === b.date) {
      // ต้องเวลาติดกัน ≤30 นาที (รอบจบ→รอบเริ่ม)
      const aStart = timeToMin(a.startTime), aEnd = timeToMin(a.endTime);
      const bStart = timeToMin(b.startTime), bEnd = timeToMin(b.endTime);
      const gap1 = Math.abs(bStart - aEnd);  // a จบ → b เริ่ม
      const gap2 = Math.abs(aStart - bEnd);  // b จบ → a เริ่ม
      if (gap1 <= 30 || gap2 <= 30) return { match: true, by: 'name+time' };
    }
  }
  return false;
}

// หา booking ทั้งหมดที่ผูกกับ booking นี้ (รวมตัวเอง) — เรียงตามวัน+เวลา
//   คืน { all, byPhoneOrMember, sameDayConsecutive }
function findLinkedBookings(booking) {
  if (!booking) return { all: [], sameDay: [], consecutive: [] };
  
  const candidates = (state.bookings || []).filter(b => {
    if (b.status === 'cancelled') return false;
    if (b.checkedInWalkinId) return false;  // check-in แล้ว
    return true;
  });
  
  // หาทั้งหมดที่ผูก (เบอร์/เมม → ข้ามวัน, ชื่อ → ติดกันวันเดียว)
  const linked = candidates.filter(b => {
    if (b.id === booking.id) return true;  // รวมตัวเอง
    return !!isSameCustomerForLink(booking, b);
  });
  
  // เรียงตามวัน + เวลา
  const sortFn = (a, b) => {
    if (a.date !== b.date) return (a.date || '').localeCompare(b.date || '');
    return timeToMin(a.startTime) - timeToMin(b.startTime);
  };
  linked.sort(sortFn);
  
  // กลุ่มย่อย: วันเดียวกับ booking
  const sameDay = linked.filter(b => b.date === booking.date).sort(sortFn);
  
  // กลุ่มย่อย: ติดกันในวันนี้ (chain ต่อเนื่อง ≤30 นาที) รวม booking
  const consecutive = [];
  if (sameDay.length > 0) {
    // หา index ของ booking ใน sameDay
    const selfIdx = sameDay.findIndex(b => b.id === booking.id);
    if (selfIdx >= 0) {
      consecutive.push(sameDay[selfIdx]);
      // ขยายไปข้างหน้า
      for (let i = selfIdx + 1; i < sameDay.length; i++) {
        const prev = consecutive[consecutive.length - 1];
        const gap = timeToMin(sameDay[i].startTime) - timeToMin(prev.endTime);
        if (gap >= -5 && gap <= 30) consecutive.push(sameDay[i]);
        else break;
      }
      // ขยายไปข้างหลัง
      for (let i = selfIdx - 1; i >= 0; i--) {
        const next = consecutive[0];
        const gap = timeToMin(next.startTime) - timeToMin(sameDay[i].endTime);
        if (gap >= -5 && gap <= 30) consecutive.unshift(sameDay[i]);
        else break;
      }
    }
  }
  
  return { all: linked, sameDay, consecutive };
}

// ⭐ r38r28u: Cascade — recompute เวลาทุกรอบหลังแก้รอบใดรอบหนึ่ง
//   rounds = [{ startTime, durationMin, ... }] เรียงตามเวลาแล้ว
//   fromIdx = แก้รอบนี้ → รอบถัดไปเลื่อนตาม (เริ่ม = รอบก่อนจบ)
//   คืน array ใหม่ที่ recompute startTime/endTime แล้ว (mutate ไม่กระทบ original)
function cascadeRoundTimes(rounds, fromIdx = 0) {
  const out = rounds.map(r => ({ ...r }));
  for (let i = Math.max(1, fromIdx + 1); i < out.length; i++) {
    const prevEnd = calcWalkinEndTime(out[i-1].startTime, out[i-1].durationMin);
    out[i].startTime = prevEnd;  // รอบถัดไปเริ่ม = รอบก่อนจบ
    out[i].endTime = calcWalkinEndTime(out[i].startTime, out[i].durationMin);
  }
  // recompute endTime ของรอบที่แก้เองด้วย
  if (out[fromIdx]) {
    out[fromIdx].endTime = calcWalkinEndTime(out[fromIdx].startTime, out[fromIdx].durationMin);
  }
  return out;
}

// ════════════════════════════════════════════════════════════════
// ⭐ r38r28u: Round Picker Sheet — Phase 2
//   เปิดเมื่อกด แก้/ยกเลิก booking ที่มีหลายรอบผูกกัน
//   ติ๊กเลือกรอบ + quick "ติดกันวันนี้" / "ทั้งหมด"
//   onConfirm(selectedBookings) → callback ทำ action ต่อ
// ════════════════════════════════════════════════════════════════
function openRoundPickerSheet(booking, action, onConfirm) {
  const { all, consecutive } = findLinkedBookings(booking);
  
  // ถ้ามีรอบเดียว → ไม่ต้องเปิด picker เรียก callback เลย
  if (all.length <= 1) {
    onConfirm([booking]);
    return;
  }
  
  const actionLabel = action === 'cancel' ? 'ยกเลิก' : action === 'edit' ? 'แก้ไข' : 'เลือก';
  const actionIcon = action === 'cancel' ? '❌' : action === 'edit' ? '✏️' : '📋';
  const actionColor = action === 'cancel' ? '#dc2626' : '#5a3a7a';
  
  const custName = booking.customerName || booking.memberCode || '(ลูกค้า)';
  
  // เริ่มต้น: เลือกเฉพาะรอบที่กด (booking)
  const selected = new Set([booking.id]);
  const consecIds = new Set(consecutive.map(b => b.id));
  
  // group by date
  const byDate = {};
  all.forEach(b => {
    const d = b.date || '?';
    if (!byDate[d]) byDate[d] = [];
    byDate[d].push(b);
  });
  const dates = Object.keys(byDate).sort();
  
  const svcName = (b) => {
    const svc = state.services.find(s => s.id === b.serviceId);
    return svc?.shortName || svc?.name || b.serviceName || '';
  };
  const staffName = (b) => {
    const ids = getStaffIdsFromRecord(b);
    const names = ids.map(id => {
      const s = state.staff.find(x => x.id === id);
      return s?.nickname || s?.shortCode || '?';
    });
    return names.join(' + ');
  };
  
  const renderRows = () => dates.map(d => {
    const isToday = (d === booking.date);
    const dLabel = formatBuddhistDate(d) || d;
    const rows = byDate[d].map(b => {
      const checked = selected.has(b.id) ? 'checked' : '';
      const isConsec = consecIds.has(b.id);
      const isSelf = b.id === booking.id;
      return `
        <label class="rps-row" style="display:flex; align-items:center; gap:10px; padding:10px 12px; border:1.5px solid ${isSelf ? actionColor : '#e6d5cf'}; border-radius:10px; margin-bottom:6px; cursor:pointer; background:${isSelf ? '#faf3f2' : '#fff'};">
          <input type="checkbox" class="rps-check" data-id="${b.id}" ${checked} style="width:20px; height:20px; accent-color:${actionColor}; flex-shrink:0;">
          <div style="flex:1; min-width:0;">
            <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
              <span style="font-family:monospace; font-weight:800; font-size:15px; color:#3a2d2a;">${displayTime(b.startTime)}</span>
              <span style="font-size:13px; color:#7a6058;">→ ${displayTime(b.endTime)}</span>
              <span style="font-weight:700; font-size:13px; color:#3a2d2a;">${escapeHtml(staffName(b))}</span>
              ${isConsec && isToday ? '<span style="font-size:9px; padding:1px 6px; background:#dbeafe; color:#1e40af; border-radius:999px; font-weight:700;">🔗 ติดกัน</span>' : ''}
            </div>
            <div style="font-size:11px; color:#a8928a; margin-top:2px;">${escapeHtml(svcName(b))}</div>
          </div>
        </label>
      `;
    }).join('');
    return `
      <div style="margin-bottom:12px;">
        <div style="font-size:12px; font-weight:700; color:${isToday ? actionColor : '#7a6058'}; margin-bottom:6px;">
          ── ${dLabel}${isToday ? ' (วันนี้)' : ''} ──
        </div>
        ${rows}
      </div>
    `;
  }).join('');
  
  const html = `
    <div class="modal-overlay" id="rps-modal">
      <div class="modal-card" style="max-width:480px;">
        <div style="padding:16px 18px 12px; border-bottom:1px solid #e6d5cf; background:linear-gradient(135deg, ${actionColor}, ${actionColor}dd); border-radius:14px 14px 0 0;">
          <h2 style="margin:0; font-size:17px; color:#fff; font-weight:800;">${actionIcon} ${actionLabel}รอบของ "${escapeHtml(custName)}"</h2>
          <div style="font-size:12px; color:#fff; opacity:0.9; margin-top:3px;">จอง ${all.length} รอบ · เลือกรอบที่ต้องการ${actionLabel}</div>
        </div>
        <div style="padding:14px 18px; overflow-y:auto; flex:1;">
          <div id="rps-rows">${renderRows()}</div>
        </div>
        <div style="padding:12px 18px; border-top:1px solid #e6d5cf; background:#fafafa; border-radius:0 0 14px 14px;">
          <div style="display:flex; gap:6px; margin-bottom:10px; flex-wrap:wrap;">
            ${consecutive.length > 1 ? `<button id="rps-pick-consec" style="flex:1; padding:7px; background:#dbeafe; border:1px solid #93c5fd; color:#1e40af; border-radius:8px; font-size:12px; font-weight:700; cursor:pointer;">🔗 ติดกันวันนี้ (${consecutive.length})</button>` : ''}
            <button id="rps-pick-all" style="flex:1; padding:7px; background:#f3e8ff; border:1px solid #d8b4fe; color:#6b21a8; border-radius:8px; font-size:12px; font-weight:700; cursor:pointer;">📋 ทั้งหมด (${all.length})</button>
          </div>
          <div style="display:flex; gap:10px; justify-content:flex-end;">
            <button id="rps-cancel" style="padding:10px 18px; background:#fff; border:1px solid #cbd5e1; color:#475569; border-radius:8px; font-size:14px; cursor:pointer; font-weight:600;">ยกเลิก</button>
            <button id="rps-confirm" style="padding:10px 20px; background:${actionColor}; border:none; color:#fff; border-radius:8px; font-size:14px; font-weight:800; cursor:pointer;">${actionLabel} <span id="rps-count">1</span> รอบ →</button>
          </div>
        </div>
      </div>
    </div>
  `;
  
  const wrap = document.createElement('div');
  wrap.innerHTML = html;
  const modal = wrap.firstElementChild;
  document.body.appendChild(modal);
  
  const updateCount = () => {
    const c = modal.querySelector('#rps-count');
    if (c) c.textContent = selected.size;
    const confirmBtn = modal.querySelector('#rps-confirm');
    if (confirmBtn) confirmBtn.disabled = selected.size === 0;
  };
  
  // Checkbox toggle
  modal.querySelectorAll('.rps-check').forEach(cb => {
    cb.addEventListener('change', () => {
      if (cb.checked) selected.add(cb.dataset.id);
      else selected.delete(cb.dataset.id);
      updateCount();
    });
  });
  
  // Quick: ติดกันวันนี้
  modal.querySelector('#rps-pick-consec')?.addEventListener('click', () => {
    selected.clear();
    consecutive.forEach(b => selected.add(b.id));
    modal.querySelectorAll('.rps-check').forEach(cb => {
      cb.checked = selected.has(cb.dataset.id);
    });
    updateCount();
  });
  
  // Quick: ทั้งหมด
  modal.querySelector('#rps-pick-all')?.addEventListener('click', () => {
    selected.clear();
    all.forEach(b => selected.add(b.id));
    modal.querySelectorAll('.rps-check').forEach(cb => cb.checked = true);
    updateCount();
  });
  
  modal.querySelector('#rps-cancel').addEventListener('click', () => modal.remove());
  
  modal.querySelector('#rps-confirm').addEventListener('click', () => {
    const picked = all.filter(b => selected.has(b.id));
    if (picked.length === 0) { toast('⚠️ เลือกอย่างน้อย 1 รอบ', 'error'); return; }
    modal.remove();
    onConfirm(picked);
  });
  
  updateCount();
}
window.findLinkedBookings = findLinkedBookings;
window.cascadeRoundTimes = cascadeRoundTimes;
window.openRoundPickerSheet = openRoundPickerSheet;

// ⭐ r38r28v: Phase 4 — ถามยกเลิกรอบที่ผูกกัน (เรียกหลังยกเลิก booking 1 รอบ)
function promptCancelLinkedBookings(justCancelledBooking) {
  // หารอบที่ผูก (ยังไม่ยกเลิก)
  const { all } = findLinkedBookings(justCancelledBooking);
  // กรองเอาเฉพาะที่ยังไม่ยกเลิก + ไม่ใช่ตัวที่เพิ่งยกเลิก
  const others = all.filter(b => 
    b.id !== justCancelledBooking.id && 
    b.status !== 'cancelled' &&
    !b.checkedInWalkinId
  );
  if (others.length === 0) return;  // ไม่มีรอบผูก → จบ
  
  // ใช้ Round Picker — เริ่มต้นเลือกทุกรอบที่เหลือ
  const custName = justCancelledBooking.customerName || justCancelledBooking.memberCode || '(ลูกค้า)';
  
  // สร้าง mini-modal ถาม
  const svcName = (b) => {
    const svc = state.services.find(s => s.id === b.serviceId);
    return svc?.shortName || svc?.name || b.serviceName || '';
  };
  const staffName = (b) => {
    const ids = getStaffIdsFromRecord(b);
    return ids.map(id => { const s = state.staff.find(x => x.id === id); return s?.nickname || s?.shortCode || '?'; }).join(' + ');
  };
  
  const rowsHtml = others.map(b => `
    <label style="display:flex; align-items:center; gap:10px; padding:10px 12px; border:1.5px solid #fca5a5; border-radius:10px; margin-bottom:6px; cursor:pointer; background:#fff;">
      <input type="checkbox" class="pcl-check" data-id="${b.id}" checked style="width:20px; height:20px; accent-color:#dc2626; flex-shrink:0;">
      <div style="flex:1; min-width:0;">
        <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
          <span style="font-family:monospace; font-weight:800; font-size:14px; color:#3a2d2a;">${formatBuddhistDate(b.date) || b.date}</span>
          <span style="font-family:monospace; font-weight:700; font-size:14px; color:#3a2d2a;">${displayTime(b.startTime)}</span>
          <span style="font-weight:700; font-size:13px; color:#3a2d2a;">${escapeHtml(staffName(b))}</span>
        </div>
        <div style="font-size:11px; color:#a8928a; margin-top:2px;">${escapeHtml(svcName(b))}</div>
      </div>
    </label>
  `).join('');
  
  const html = `
    <div class="modal-overlay" id="pcl-modal">
      <div class="modal-card" style="max-width:460px;">
        <div style="padding:16px 18px 12px; border-bottom:1px solid #e6d5cf; background:linear-gradient(135deg, #dc2626, #b91c1c); border-radius:14px 14px 0 0;">
          <h2 style="margin:0; font-size:17px; color:#fff; font-weight:800;">❌ ยกเลิกรอบที่ผูกกันด้วย?</h2>
          <div style="font-size:12px; color:#fff; opacity:0.9; margin-top:3px;">"${escapeHtml(custName)}" มีอีก ${others.length} รอบที่จองไว้</div>
        </div>
        <div style="padding:14px 18px; overflow-y:auto; flex:1;">
          <div style="font-size:13px; color:#7a6058; margin-bottom:10px;">เลือกรอบที่ต้องการยกเลิกเพิ่ม:</div>
          ${rowsHtml}
        </div>
        <div style="padding:12px 18px; border-top:1px solid #e6d5cf; background:#fafafa; border-radius:0 0 14px 14px; display:flex; gap:10px; justify-content:flex-end;">
          <button id="pcl-skip" style="padding:10px 18px; background:#fff; border:1px solid #cbd5e1; color:#475569; border-radius:8px; font-size:14px; cursor:pointer; font-weight:600;">ไม่ยกเลิก</button>
          <button id="pcl-confirm" style="padding:10px 20px; background:#dc2626; border:none; color:#fff; border-radius:8px; font-size:14px; font-weight:800; cursor:pointer;">ยกเลิก <span id="pcl-count">${others.length}</span> รอบ</button>
        </div>
      </div>
    </div>
  `;
  
  const wrap = document.createElement('div');
  wrap.innerHTML = html;
  const modal = wrap.firstElementChild;
  document.body.appendChild(modal);
  
  const selected = new Set(others.map(b => b.id));
  const updateCount = () => {
    const c = modal.querySelector('#pcl-count'); if (c) c.textContent = selected.size;
    const btn = modal.querySelector('#pcl-confirm'); if (btn) btn.disabled = selected.size === 0;
  };
  
  modal.querySelectorAll('.pcl-check').forEach(cb => {
    cb.addEventListener('change', () => {
      if (cb.checked) selected.add(cb.dataset.id); else selected.delete(cb.dataset.id);
      updateCount();
    });
  });
  
  modal.querySelector('#pcl-skip').addEventListener('click', () => modal.remove());
  
  modal.querySelector('#pcl-confirm').addEventListener('click', async () => {
    const ids = [...selected];
    if (ids.length === 0) { modal.remove(); return; }
    const btn = modal.querySelector('#pcl-confirm');
    btn.disabled = true; btn.innerHTML = '⏳ กำลังยกเลิก...';
    
    let ok = 0, fail = 0;
    for (const id of ids) {
      const b = others.find(x => x.id === id);
      if (!b) continue;
      try {
        await updateDoc(doc(db, 'bookings', id), {
          status: 'cancelled',
          updatedAt: serverTimestamp(),
          updatedBy: state.user?.name || 'unknown',
          cancelReason: 'linked_cancel',
        });
        try {
          await addDoc(collection(db, 'audit_logs'), {
            action: 'booking_linked_cancel',
            target: 'bookings', targetId: id,
            data: { customerName: custName, date: b.date, startTime: b.startTime, linkedTo: justCancelledBooking.id },
            user: state.user?.name || 'unknown', userRole: state.user?.role || 'unknown',
            timestamp: serverTimestamp(),
          });
        } catch (e) {}
        // webhook
        try { sendWebhook(buildBookingNotifyMessage('cancel', { ...b, status: 'cancelled' })); } catch (e) {}
        ok++;
      } catch (e) { console.error('Linked cancel failed:', e); fail++; }
    }
    modal.remove();
    toast(`❌ ยกเลิกเพิ่ม ${ok} รอบ${fail ? ` (พลาด ${fail})` : ''}`, ok ? 'success' : 'error', 4000);
  });
  
  updateCount();
}
window.promptCancelLinkedBookings = promptCancelLinkedBookings;

// ════════════════════════════════════════════════════════════════
// ⭐ r38r28w: Batch Edit Modal — Phase 5
//   แก้หลายรอบพร้อมกัน: พนง./คอร์ส (batch) + เวลาเริ่ม (cascade)
//   picked = booking ที่เลือกจาก Round Picker (เรียงเวลาแล้ว)
// ════════════════════════════════════════════════════════════════
function openBatchEditModal(picked, seedBooking) {
  if (!picked || picked.length === 0) return;
  // เรียงตามวัน+เวลา
  picked = picked.slice().sort((a, b) => {
    if (a.date !== b.date) return (a.date||'').localeCompare(b.date||'');
    return timeToMin(a.startTime) - timeToMin(b.startTime);
  });
  
  const shop = seedBooking.shop || picked[0].shop || 'geisha';
  const custName = seedBooking.customerName || seedBooking.memberCode || '(ลูกค้า)';
  
  // editState — เก็บค่าที่จะแก้ (null = ไม่แก้ field นั้น)
  const editState = {
    newStaffId: null,       // เปลี่ยนพนง.ทุกรอบ (null=คงเดิม)
    newServiceId: null,     // เปลี่ยนคอร์สทุกรอบ (null=คงเดิม)
    // เวลาเริ่มรายรอบ — เก็บ array ใช้ cascade
    rounds: picked.map(b => ({
      id: b.id,
      startTime: b.startTime,
      durationMin: (() => {
        const svc = state.services.find(s => s.id === b.serviceId);
        return svc?.durationMin || b.durationMin || (timeToMin(b.endTime) - timeToMin(b.startTime));
      })(),
      serviceId: b.serviceId,
      orig: b,
    })),
  };
  
  // staff list (ร้านนี้ + active)
  const staffOptions = (state.staff || [])
    .filter(s => !isStaffResigned?.(s) && (s.homeShop === shop || !s.homeShop))
    .sort((a,b) => (a.nickname||'').localeCompare(b.nickname||'', 'th'));
  
  // service list (ร้านนี้, เดี่ยว)
  const svcOptions = (state.services || [])
    .filter(s => s.active !== false && (s.groupSize === 1 || !s.groupSize))
    .filter(s => { const p = getServicePriceForShop?.(s, shop); return p != null || s.basePrice; });
  
  const recompute = () => {
    // cascade เวลา
    editState.rounds = cascadeRoundTimes(editState.rounds, 0);
  };
  recompute();
  
  function render() {
    const staffSel = `
      <select id="be-staff" style="width:100%; padding:10px; border:1px solid #e6d5cf; border-radius:8px; font-size:14px;">
        <option value="">— คงพนง.เดิมแต่ละรอบ —</option>
        ${staffOptions.map(s => `<option value="${s.id}" ${editState.newStaffId===s.id?'selected':''}>${escapeHtml(s.nickname||s.shortCode||'?')}${s.tier&&s.tier!=='อื่นๆ'?` (${s.tier})`:''}</option>`).join('')}
      </select>`;
    const svcSel = `
      <select id="be-service" style="width:100%; padding:10px; border:1px solid #e6d5cf; border-radius:8px; font-size:14px;">
        <option value="">— คงคอร์สเดิมแต่ละรอบ —</option>
        ${svcOptions.map(s => `<option value="${s.id}" ${editState.newServiceId===s.id?'selected':''}>${escapeHtml(s.shortName||s.name)} (${s.durationMin}m)</option>`).join('')}
      </select>`;
    
    const roundsHtml = editState.rounds.map((r, i) => {
      const dt = formatBuddhistDate(r.orig.date) || r.orig.date;
      const dur = editState.newServiceId 
        ? (svcOptions.find(s=>s.id===editState.newServiceId)?.durationMin || r.durationMin)
        : r.durationMin;
      const endT = calcWalkinEndTime(r.startTime, dur);
      return `
        <div style="display:flex; align-items:center; gap:10px; padding:10px 12px; border:1px solid #e6d5cf; border-radius:10px; margin-bottom:6px; background:#fff;">
          <div style="flex-shrink:0; width:54px; font-size:11px; color:#a8928a;">${dt}</div>
          <div style="flex-shrink:0; font-size:13px; color:#7a6058;">รอบ ${i+1}</div>
          <input type="text" inputmode="numeric" maxlength="5" class="be-time" data-idx="${i}"
            value="${r.startTime}" placeholder="1430"
            style="width:64px; text-align:center; font-family:monospace; font-size:16px; padding:8px 4px; border:1.5px solid ${i===0?'#3b82f6':'#e6d5cf'}; border-radius:8px;"
            ${i>0?'readonly':''}>
          <span style="font-size:13px; color:#7a6058;">→ ${displayTime(endT)}</span>
          ${i===0?'<span style="font-size:9px; padding:1px 6px; background:#dbeafe; color:#1e40af; border-radius:999px; font-weight:700;">แก้ได้</span>':'<span style="font-size:9px; color:#a8928a;">(auto)</span>'}
        </div>
      `;
    }).join('');
    
    const html = `
      <div class="modal-overlay" id="be-modal">
        <div class="modal-card" style="max-width:480px;">
          <div style="padding:16px 18px 12px; border-bottom:1px solid #e6d5cf; background:linear-gradient(135deg, #2563eb, #1d4ed8); border-radius:14px 14px 0 0;">
            <h2 style="margin:0; font-size:17px; color:#fff; font-weight:800;">✏️ แก้ ${editState.rounds.length} รอบ · "${escapeHtml(custName)}"</h2>
            <div style="font-size:12px; color:#fff; opacity:0.9; margin-top:3px;">เปลี่ยนพนง./คอร์ส = ทุกรอบ · เวลา = แก้รอบแรก รอบอื่นเลื่อนตาม</div>
          </div>
          <div style="padding:16px 18px; overflow-y:auto; flex:1;">
            <div style="margin-bottom:14px;">
              <label style="font-size:13px; font-weight:700; color:#3a2d2a; display:block; margin-bottom:6px;">👤 พนักงาน (ทุกรอบ)</label>
              ${staffSel}
            </div>
            <div style="margin-bottom:16px;">
              <label style="font-size:13px; font-weight:700; color:#3a2d2a; display:block; margin-bottom:6px;">💆 คอร์ส (ทุกรอบ)</label>
              ${svcSel}
            </div>
            <div>
              <label style="font-size:13px; font-weight:700; color:#3a2d2a; display:block; margin-bottom:6px;">⏰ เวลาเริ่ม (แก้รอบแรก → เลื่อนตามทั้งหมด)</label>
              ${roundsHtml}
            </div>
          </div>
          <div style="padding:12px 18px; border-top:1px solid #e6d5cf; background:#fafafa; border-radius:0 0 14px 14px; display:flex; gap:10px; justify-content:flex-end;">
            <button id="be-cancel" style="padding:10px 18px; background:#fff; border:1px solid #cbd5e1; color:#475569; border-radius:8px; font-size:14px; cursor:pointer; font-weight:600;">ยกเลิก</button>
            <button id="be-save" style="padding:10px 20px; background:#2563eb; border:none; color:#fff; border-radius:8px; font-size:14px; font-weight:800; cursor:pointer;">💾 บันทึก ${editState.rounds.length} รอบ</button>
          </div>
        </div>
      </div>
    `;
    
    const old = document.getElementById('be-modal');
    if (old) old.remove();
    const wrap = document.createElement('div');
    wrap.innerHTML = html;
    document.body.appendChild(wrap.firstElementChild);
    bind();
  }
  
  function bind() {
    const modal = document.getElementById('be-modal');
    
    modal.querySelector('#be-staff').onchange = (e) => {
      editState.newStaffId = e.target.value || null;
    };
    modal.querySelector('#be-service').onchange = (e) => {
      editState.newServiceId = e.target.value || null;
      // เปลี่ยน duration ทุกรอบ → recompute cascade
      if (editState.newServiceId) {
        const svc = svcOptions.find(s => s.id === editState.newServiceId);
        if (svc) editState.rounds.forEach(r => r.durationMin = svc.durationMin);
      } else {
        // คืน duration เดิม
        editState.rounds.forEach(r => {
          const svc = state.services.find(s => s.id === r.serviceId);
          r.durationMin = svc?.durationMin || (timeToMin(r.orig.endTime) - timeToMin(r.orig.startTime));
        });
      }
      recompute();
      render();
    };
    
    // เวลารอบแรก — bindNumericTimeInput
    const t0 = modal.querySelector('.be-time[data-idx="0"]');
    if (t0 && typeof bindNumericTimeInput === 'function') {
      bindNumericTimeInput(t0, {
        allowOutsideHours: true,
        onValid: (val) => {
          editState.rounds[0].startTime = val;
          recompute();
          render();
        },
      });
    }
    
    modal.querySelector('#be-cancel').onclick = () => modal.remove();
    
    modal.querySelector('#be-save').onclick = async () => {
      const btn = modal.querySelector('#be-save');
      btn.disabled = true; btn.innerHTML = '⏳ บันทึก...';
      
      recompute();  // final cascade
      const newSvc = editState.newServiceId ? svcOptions.find(s=>s.id===editState.newServiceId) : null;
      const newStaff = editState.newStaffId ? state.staff.find(s=>s.id===editState.newStaffId) : null;
      
      let ok = 0, fail = 0;
      for (let i = 0; i < editState.rounds.length; i++) {
        const r = editState.rounds[i];
        const dur = newSvc ? newSvc.durationMin : r.durationMin;
        const endT = calcWalkinEndTime(r.startTime, dur);
        const patch = {
          startTime: r.startTime,
          endTime: endT,
          updatedAt: serverTimestamp(),
          updatedBy: state.user?.name || 'unknown',
          batchEdited: true,
        };
        if (newStaff) {
          patch.staffId = newStaff.id;
          patch.staffIds = [newStaff.id];
          patch.staffId2 = null;
        }
        if (newSvc) {
          patch.serviceId = newSvc.id;
          patch.serviceName = newSvc.name;
          const price = getServicePriceForShop?.(newSvc, shop) || newSvc.basePrice || newSvc.price || 0;
          patch.price = price;
          patch.basePrice = price;
        }
        try {
          await updateDoc(doc(db, 'bookings', r.id), patch);
          ok++;
        } catch (e) { console.error('Batch edit failed:', e); fail++; }
      }
      
      // Audit
      try {
        await addDoc(collection(db, 'audit_logs'), {
          action: 'booking_batch_edit',
          target: 'bookings',
          data: {
            customerName: custName,
            roundCount: editState.rounds.length,
            changedStaff: newStaff ? (newStaff.nickname||newStaff.shortCode) : null,
            changedService: newSvc ? newSvc.name : null,
            startTimeFirst: editState.rounds[0].startTime,
            bookingIds: editState.rounds.map(r => r.id),
          },
          user: state.user?.name || 'unknown', userRole: state.user?.role || 'unknown',
          timestamp: serverTimestamp(),
        });
      } catch (e) {}
      
      modal.remove();
      toast(`✅ แก้ ${ok} รอบสำเร็จ${fail?` (พลาด ${fail})`:''}`, ok?'success':'error', 4000);
    };
  }
  
  render();
}
window.openBatchEditModal = openBatchEditModal;

// ⭐ r38r28v-debug: ทดสอบ findLinkedBookings ผ่าน console
//   ใช้: window.testLinked("095-645-6536")  หรือ  window.testLinked("69MB21")
window.testLinked = function(phoneOrMemberOrName) {
  const q = String(phoneOrMemberOrName).trim();
  const qn = q.replace(/[^0-9]/g, '');
  // หา booking ตัวแรกที่ตรง
  const seed = (state.bookings || []).find(b => {
    if (b.status === 'cancelled') return false;
    const bp = String(b.customerPhone||'').replace(/[^0-9]/g,'');
    if (qn && bp === qn) return true;
    if (String(b.memberCode||'').toUpperCase() === q.toUpperCase()) return true;
    if (String(b.customerName||'').toLowerCase().includes(q.toLowerCase())) return true;
    return false;
  });
  if (!seed) { console.log('❌ ไม่พบ booking ที่ตรงกับ:', q); return; }
  const result = findLinkedBookings(seed);
  const fmt = (b) => `${b.date} ${b.startTime}-${b.endTime} · ${b.customerName||b.memberCode||'?'} · ${(getStaffIdsFromRecord(b).map(id=>state.staff.find(s=>s.id===id)?.nickname||'?')).join('+')}`;
  console.log('🌱 Seed:', fmt(seed));
  console.log(`🔗 ผูกทั้งหมด (${result.all.length}):`);
  result.all.forEach(b => console.log('   ', (b.id===seed.id?'⭐':'  '), fmt(b)));
  console.log(`📅 วันเดียวกัน (${result.sameDay.length})`);
  console.log(`⏱️ ติดกัน (${result.consecutive.length}):`, result.consecutive.map(fmt));
  return result;
};

