// ─── Round 7.63b: Add Member Modal ─────────────────
// Auto-generate next member code (e.g. 69MB01 in 2026, 70MB01 in 2027)
function generateNextMemberCode(shop) {
  // ⭐ Round 7.72t: ใช้ปีพ.ศ.จริง 2 หลักท้าย (พ.ศ. = ค.ศ. + 543)
  const yr = String((new Date().getFullYear() + 543) % 100).padStart(2, '0');
  const prefix = shop === 'geisha' ? `${yr}MB` : `${yr}MY`;
  const codes = [];
  // เก็บ codes ทั้งจาก legacy field + memberships array
  (state.customers || []).forEach(c => {
    getCustomerMemberships(c).forEach(m => {
      if (m.code && m.code.startsWith(prefix)) codes.push(m.code);
    });
  });
  // หาเลขถัดไป
  let maxNum = 0;
  codes.forEach(code => {
    const numPart = code.slice(prefix.length).replace(/[^0-9]/g, '');
    const n = parseInt(numPart, 10);
    if (!isNaN(n) && n > maxNum) maxNum = n;
  });
  const nextNum = maxNum + 1;
  return `${prefix}${String(nextNum).padStart(2, '0')}`;
}

// Get today as YYYY-MM-DD (Thailand timezone)
function getTodayISODate() {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

// Normalize phone (เก็บแต่ตัวเลข)
function normalizePhone(phone) {
  return String(phone || '').replace(/[^0-9]/g, '');
}

function openAddMemberModal() {
  const html = `
    <div class="modal" style="max-width:480px;">
      <div class="modal-head">
        <h3>👑 เพิ่มเมม</h3>
        <button class="x-btn">×</button>
      </div>
      <div class="modal-body">
        <div class="add-mem-form">
          <!-- ร้าน -->
          <div class="amf-row">
            <label class="amf-label">ร้าน <span class="req">*</span></label>
            <div class="amf-shop-radios" id="amf-shop-radios">
              <button type="button" class="amf-shop-radio active" data-shop="geisha">🌸 Geisha</button>
              <button type="button" class="amf-shop-radio" data-shop="yoshi">🎌 Yoshi</button>
            </div>
          </div>
          <!-- รหัสเมม -->
          <div class="amf-row">
            <label class="amf-label">รหัสเมม <span class="req">*</span></label>
            <div class="amf-code-row">
              <input type="text" id="amf-code" class="amf-input" placeholder="${String((new Date().getFullYear() + 543) % 100).padStart(2,'0')}MB01" autocomplete="off">
              <button type="button" id="amf-code-auto" class="amf-mini-btn">🎲 สร้าง</button>
            </div>
            <div class="amf-help">กดปุ่ม "🎲 สร้าง" เพื่อสร้างรหัสอัตโนมัติ</div>
          </div>
          <!-- ชื่อ -->
          <div class="amf-row">
            <label class="amf-label">ชื่อ <span class="req">*</span></label>
            <input type="text" id="amf-name" class="amf-input" placeholder="เช่น น้องนัท" autocomplete="off">
          </div>
          <!-- เบอร์ -->
          <div class="amf-row">
            <label class="amf-label">เบอร์โทร <span class="req">*</span></label>
            <input type="tel" id="amf-phone" class="amf-input" placeholder="0881234567" autocomplete="off" inputmode="tel">
            <div id="amf-detect"></div>
          </div>
          <!-- วันสมัคร -->
          <div class="amf-row">
            <label class="amf-label">วันสมัคร</label>
            <div class="amf-date-row">
              <input type="date" id="amf-since" class="amf-input">
              <button type="button" id="amf-since-now" class="amf-mini-btn">📅 วันนี้</button>
            </div>
          </div>
          <!-- หมายเหตุ -->
          <div class="amf-row">
            <label class="amf-label">หมายเหตุ</label>
            <textarea id="amf-note" class="amf-textarea" placeholder="(ไม่จำเป็น)"></textarea>
          </div>
        </div>
      </div>
      <div class="modal-foot">
        <button class="btn modal-close">ยกเลิก</button>
        <button class="btn btn-primary" id="amf-save">บันทึก</button>
      </div>
    </div>
  `;
  openModal(html);
  
  // Default values
  let selectedShop = 'geisha';
  $('#amf-since').value = getTodayISODate();
  $('#amf-code').value = generateNextMemberCode('geisha');
  
  // Shop radio handler
  $('#amf-shop-radios').addEventListener('click', (e) => {
    const btn = e.target.closest('.amf-shop-radio');
    if (!btn) return;
    selectedShop = btn.dataset.shop;
    $$('#amf-shop-radios .amf-shop-radio').forEach(b =>
      b.classList.toggle('active', b.dataset.shop === selectedShop));
    // Re-generate code for new shop (if user hasn't manually edited)
    const codeInput = $('#amf-code');
    if (!codeInput.dataset.manual) {
      codeInput.value = generateNextMemberCode(selectedShop);
    }
    // Re-detect (for shop-specific message)
    runDetect();
  });
  
  // Auto-gen code button
  $('#amf-code-auto').addEventListener('click', () => {
    $('#amf-code').value = generateNextMemberCode(selectedShop);
    delete $('#amf-code').dataset.manual;
  });
  
  // Mark code as manual when user edits
  $('#amf-code').addEventListener('input', (e) => {
    e.target.dataset.manual = '1';
  });
  
  // วันนี้ button
  $('#amf-since-now').addEventListener('click', () => {
    $('#amf-since').value = getTodayISODate();
  });
  
  // Auto-detect existing customer when phone is entered
  function runDetect() {
    const phone = normalizePhone($('#amf-phone').value);
    const detectEl = $('#amf-detect');
    if (!detectEl) return;
    if (phone.length < 9) { detectEl.innerHTML = ''; return; }
    
    const existing = (state.customers || []).find(c => c.id === phone);
    if (!existing) {
      detectEl.innerHTML = `<div class="amf-detect success">✓ เบอร์ใหม่ — จะสร้างลูกค้าใหม่</div>`;
      return;
    }
    
    const memberships = getCustomerMemberships(existing);
    const shopMember = memberships.find(m => m.shop === selectedShop);
    
    if (shopMember) {
      detectEl.innerHTML = `<div class="amf-detect error">⚠️ <strong>${escapeHtml(existing.name || 'ไม่มีชื่อ')}</strong> เป็นเมม ${selectedShop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'} อยู่แล้ว (รหัส ${escapeHtml(shopMember.code)})</div>`;
    } else if (memberships.length > 0) {
      const otherShops = memberships.map(m => `${m.shop === 'geisha' ? '🌸' : '🎌'} ${m.code}`).join(', ');
      detectEl.innerHTML = `<div class="amf-detect warn">👤 พบ <strong>${escapeHtml(existing.name || 'ไม่มีชื่อ')}</strong> เป็นเมม: ${otherShops}<br><span style="font-size:11.5px;">→ บันทึกแล้วจะถามว่าเพิ่มเมม ${selectedShop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'} ให้คนเดิม หรือคนละคน</span></div>`;
    } else {
      detectEl.innerHTML = `<div class="amf-detect info">ℹ️ พบ <strong>${escapeHtml(existing.name || 'ไม่มีชื่อ')}</strong> ในระบบ (เคยจอง)<br><span style="font-size:11.5px;">→ บันทึกแล้วจะอัปเดตเป็นเมมโดยคงประวัติ</span></div>`;
    }
  }
  $('#amf-phone').addEventListener('input', runDetect);
  
  // Save handler
  let saving = false;
  $('#amf-save').addEventListener('click', async () => {
    if (saving) return;
    
    const code = ($('#amf-code').value || '').trim();
    const name = ($('#amf-name').value || '').trim();
    const phone = normalizePhone($('#amf-phone').value);
    const since = $('#amf-since').value || '';
    const note = ($('#amf-note').value || '').trim();
    
    // Validate
    if (!code) { alert('กรุณาใส่รหัสเมม'); return; }
    if (!name) { alert('กรุณาใส่ชื่อ'); return; }
    if (phone.length < 9) { alert('เบอร์โทรไม่ถูกต้อง (อย่างน้อย 9 หลัก)'); return; }
    
    // ตรวจรหัสซ้ำ (ในระบบทั้งหมด)
    let codeExistsCustomer = null;
    for (const c of (state.customers || [])) {
      const ms = getCustomerMemberships(c);
      if (ms.some(m => m.code === code)) {
        codeExistsCustomer = c;
        break;
      }
    }
    if (codeExistsCustomer && codeExistsCustomer.id !== phone) {
      alert(`❌ รหัสเมม "${code}" ใช้แล้วโดยลูกค้าคนอื่น (${codeExistsCustomer.name || codeExistsCustomer.id})\nกด "🎲 สร้าง" เพื่อสร้างรหัสใหม่`);
      return;
    }
    
    saving = true;
    $('#amf-save').disabled = true;
    $('#amf-save').textContent = 'กำลังบันทึก...';
    
    try {
      const existing = (state.customers || []).find(c => c.id === phone);
      
      if (!existing) {
        // เคสที่ 1: ลูกค้าใหม่ → สร้าง doc ใหม่
        await saveNewMember({ phone, name, code, shop: selectedShop, since, note });
      } else {
        // เคสที่ 2: ลูกค้าเก่า → ตรวจ membership
        const ms = getCustomerMemberships(existing);
        const sameShop = ms.find(m => m.shop === selectedShop);
        
        if (sameShop) {
          // เป็นเมมร้านนี้แล้ว — block
          alert(`❌ ${existing.name || 'ลูกค้าคนนี้'} เป็นเมม ${selectedShop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'} อยู่แล้ว (รหัส ${sameShop.code})`);
          saving = false;
          $('#amf-save').disabled = false;
          $('#amf-save').textContent = 'บันทึก';
          return;
        }
        
        // เคสซ้ำเบอร์ — ใช้ inline confirm
        const otherShops = ms.length > 0
          ? ms.map(m => `${m.shop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'} (${m.code})`).join(', ')
          : '(เคยจอง — ยังไม่ใช่เมม)';
        
        const msg = `⚠️ เบอร์ ${existing.id} มีในระบบแล้ว:\n` +
          `${existing.name || '(ไม่มีชื่อ)'}\n` +
          `→ ${otherShops}\n\n` +
          `เป็นคนเดียวกันใช่ไหม?\n\n` +
          `[ตกลง] = ใช่ คนเดียวกัน → เพิ่มเมม ${selectedShop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'} ให้คนนี้\n` +
          `[ยกเลิก] = คนละคน → ใส่เบอร์ใหม่`;
        
        if (confirm(msg)) {
          await mergeMembership(existing, { code, shop: selectedShop, since, note });
        } else {
          // user เลือก "คนละคน" → กลับไปแก้เบอร์
          saving = false;
          $('#amf-save').disabled = false;
          $('#amf-save').textContent = 'บันทึก';
          $('#amf-phone').focus();
          $('#amf-phone').select();
          return;
        }
      }
      
      closeModal();
      alert(`✅ เพิ่มเมม ${selectedShop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'} สำเร็จ!\nรหัส: ${code}\nชื่อ: ${name}`);
    } catch (err) {
      console.error('Add member failed:', err);
      alert('❌ บันทึกไม่สำเร็จ: ' + (err?.message || err));
      saving = false;
      $('#amf-save').disabled = false;
      $('#amf-save').textContent = 'บันทึก';
    }
  });
}

// สร้างเมมใหม่ (ลูกค้าใหม่)
async function saveNewMember({ phone, name, code, shop, since, note }) {
  const newMembership = { code, shop, since: since || '' };
  if (note) newMembership.note = note;
  
  await setDoc(doc(db, 'bookingCustomers', phone), {
    name,
    phone,
    memberships: [newMembership],
    // backward compat single fields (ลูกค้าเก่ายังอ่านได้)
    memberCode: code,
    memberShop: shop,
    memberSince: since || '',
    bookingCount: 0,
    bookingCreatedAt: serverTimestamp()
  });
  
  await writeAuditLog('create', 'member', phone, {
    customerName: name, code, shop, source: 'add-member-modal'
  });
}

// เพิ่ม membership ให้ลูกค้าเก่า (เมม 2 ร้าน หรือ ลูกค้าจองเก่าสมัครเมม)
async function mergeMembership(existing, { code, shop, since, note }) {
  const oldMs = getCustomerMemberships(existing);
  const newMembership = { code, shop, since: since || '' };
  if (note) newMembership.note = note;
  const newMs = [...oldMs, newMembership];
  
  await updateDoc(doc(db, 'bookingCustomers', existing.id), {
    memberships: newMs,
    // อัปเดต legacy single fields ด้วย — ใช้ของล่าสุดที่เพิ่ม
    memberCode: code,
    memberShop: shop,
    memberSince: since || ''
  });
  
  await writeAuditLog('update', 'member', existing.id, {
    customerName: existing.name, code, shop, action: 'add-membership', totalMemberships: newMs.length
  });
}

// ─── Round 7.63c: Import Excel ─────────────────────
// Sheet names ที่ใช้ (ตามไฟล์ template)
const IMPORT_SHEET_GEISHA = 'เมมเกอิชา 69';
const IMPORT_SHEET_YOSHI = 'เมมโยชิ 69';

// State สำหรับ import flow
const importState = {
  rows: [],      // ทุก row ที่ parse ได้
  fileName: ''
};

// แปลง Excel date serial number → 'YYYY-MM-DD'
function excelDateToISO(value) {
  if (!value) return '';
  if (value instanceof Date) {
    const yyyy = value.getFullYear();
    const mm = String(value.getMonth() + 1).padStart(2, '0');
    const dd = String(value.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  }
  if (typeof value === 'number') {
    // Excel serial: days since 1900-01-01 (with bug for 1900-02-29)
    const epochMs = (value - 25569) * 86400 * 1000;
    const d = new Date(epochMs);
    if (isNaN(d.getTime())) return '';
    const yyyy = d.getUTCFullYear();
    const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
    const dd = String(d.getUTCDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
  }
  // string — try parsing
  const s = String(value).trim();
  // already ISO?
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  // DD/MM/YY (Thai BE)
  const m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
  if (m) {
    let [, dd, mm, yyyy] = m;
    yyyy = parseInt(yyyy, 10);
    if (yyyy < 100) yyyy = 2000 + yyyy;
    if (yyyy > 2400) yyyy -= 543;  // Thai BE → CE
    return `${yyyy}-${String(mm).padStart(2,'0')}-${String(dd).padStart(2,'0')}`;
  }
  return s;  // last resort — keep as-is
}

function openImportExcelModal() {
  importState.rows = [];
  importState.fileName = '';
  
  const html = `
    <div class="modal" style="max-width:520px;">
      <div class="modal-head">
        <h3>📥 นำเข้าเมมจาก Excel</h3>
        <button class="x-btn">×</button>
      </div>
      <div class="modal-body">
        <div class="imp-step-1">
          <div class="imp-help">
            <strong>📋 รูปแบบไฟล์ Excel</strong><br>
            ต้องมีชีต <code>${IMPORT_SHEET_GEISHA}</code> หรือ <code>${IMPORT_SHEET_YOSHI}</code><br>
            คอลัมน์: <strong>#</strong> | <strong>รหัสเมม</strong> | <strong>ชื่อ</strong> | <strong>เบอร์โทร</strong> | <strong>วันสมัคร</strong> | <strong>หมายเหตุ</strong>
          </div>
          <div class="imp-file-row">
            <button class="imp-file-btn" id="imp-pick-file">📁 เลือกไฟล์ Excel</button>
            <input type="file" id="imp-file-input" accept=".xlsx,.xls" style="display:none;">
            <div class="imp-file-name" id="imp-file-name">ยังไม่ได้เลือกไฟล์</div>
          </div>
        </div>
      </div>
      <div class="modal-foot">
        <button class="btn modal-close">ยกเลิก</button>
      </div>
    </div>
  `;
  openModal(html);
  
  $('#imp-pick-file').addEventListener('click', () => $('#imp-file-input').click());
  $('#imp-file-input').addEventListener('change', async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    importState.fileName = file.name;
    $('#imp-file-name').textContent = `📄 ${file.name}`;
    
    try {
      const buf = await file.arrayBuffer();
      const wb = XLSX.read(buf, { type: 'array', cellDates: true });
      const allRows = parseImportWorkbook(wb);
      if (allRows.length === 0) {
        alert(`❌ ไม่พบข้อมูลในไฟล์\nต้องมีชีต "${IMPORT_SHEET_GEISHA}" หรือ "${IMPORT_SHEET_YOSHI}" และมีข้อมูลอย่างน้อย 1 แถว`);
        return;
      }
      importState.rows = classifyImportRows(allRows);
      showImportPreview();
    } catch (err) {
      console.error('Parse Excel failed:', err);
      alert('❌ อ่านไฟล์ไม่สำเร็จ: ' + (err?.message || err));
    }
  });
}

// อ่าน 2 sheets และ extract rows — return [{shop, code, name, phone, since, note, _origRow}]
function parseImportWorkbook(wb) {
  const rows = [];
  const sheetMap = [
    { name: IMPORT_SHEET_GEISHA, shop: 'geisha' },
    { name: IMPORT_SHEET_YOSHI, shop: 'yoshi' }
  ];
  
  for (const { name, shop } of sheetMap) {
    if (!wb.SheetNames.includes(name)) continue;
    const ws = wb.Sheets[name];
    // header: row 1 (#, รหัสเมม, ชื่อ, เบอร์โทร, วันสมัคร, หมายเหตุ)
    // ใช้ array-of-arrays
    const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false, defval: '' });
    
    // data rows: index 1 onwards
    for (let i = 1; i < aoa.length; i++) {
      const row = aoa[i];
      if (!row || row.length === 0) continue;
      const code = String(row[1] || '').trim();
      const nameVal = String(row[2] || '').trim();
      const phone = normalizePhone(row[3] || '');
      const since = excelDateToISO(row[4]);
      const note = String(row[5] || '').trim();
      
      // skip empty rows
      if (!code && !nameVal && !phone) continue;
      
      rows.push({
        shop,
        code,
        name: nameVal,
        phone,
        since,
        note,
        _origRow: i + 1,    // 1-indexed for display
        _sheet: name
      });
    }
  }
  return rows;
}

// ตรวจ + classify แต่ละ row → status: 'valid' | 'merge' | 'skip' | 'error'
function classifyImportRows(rows) {
  const seen = new Map();   // phone+shop → row index (เพื่อ detect dup ในไฟล์)
  const seenCodes = new Set();  // code ในไฟล์
  
  rows.forEach((r, idx) => {
    r.status = 'valid';
    r.message = '';
    
    // 1. Required fields
    if (!r.code) { r.status = 'error'; r.message = 'ไม่มีรหัสเมม'; return; }
    if (!r.name) { r.status = 'error'; r.message = 'ไม่มีชื่อ'; return; }
    if (!r.phone) { r.status = 'error'; r.message = 'ไม่มีเบอร์โทร'; return; }
    if (r.phone.length < 9) { r.status = 'error'; r.message = `เบอร์สั้นเกิน (${r.phone.length} หลัก)`; return; }
    
    // 2. Code format check (warning เฉยๆ — ไม่ block)
    // ⭐ Round 7.72t: รองรับทุกปี (\d{2}MB / \d{2}MY) ไม่ hard-code "69"
    const expectedPattern = r.shop === 'geisha' ? /^\d{2}MB/i : /^\d{2}MY/i;
    if (!expectedPattern.test(r.code)) {
      r._codeMismatch = true;  // visual hint แต่ไม่ block
    }
    
    // 3. Dup ในไฟล์ (phone+shop ซ้ำ)
    const dupKey = `${r.phone}|${r.shop}`;
    if (seen.has(dupKey)) {
      r.status = 'error';
      r.message = `ซ้ำในไฟล์ (แถว ${seen.get(dupKey) + 1})`;
      return;
    }
    seen.set(dupKey, idx);
    
    // 4. Dup code ในไฟล์
    if (seenCodes.has(r.code)) {
      r.status = 'error';
      r.message = `รหัส ${r.code} ซ้ำในไฟล์`;
      return;
    }
    seenCodes.add(r.code);
    
    // 5. ตรวจกับ DB ปัจจุบัน
    const existing = (state.customers || []).find(c => c.id === r.phone);
    
    // 5a. รหัสซ้ำกับลูกค้าคนอื่นใน DB
    let codeOwner = null;
    for (const c of (state.customers || [])) {
      const ms = getCustomerMemberships(c);
      if (ms.some(m => m.code === r.code)) {
        codeOwner = c;
        break;
      }
    }
    if (codeOwner && codeOwner.id !== r.phone) {
      r.status = 'error';
      r.message = `รหัส ${r.code} ใช้แล้ว (${codeOwner.name || codeOwner.id})`;
      return;
    }
    
    // 5b. ถ้า phone มีใน DB แล้ว
    if (existing) {
      const ms = getCustomerMemberships(existing);
      const sameShopMember = ms.find(m => m.shop === r.shop);
      if (sameShopMember) {
        // เป็นเมมร้านนี้แล้ว — skip (อาจ update ภายหลัง แต่ตอนนี้ skip)
        r.status = 'skip';
        r.message = `เป็นเมม ${r.shop === 'geisha' ? 'Geisha' : 'Yoshi'} อยู่แล้ว (${sameShopMember.code})`;
        return;
      }
      // ลูกค้าเก่า + ยังไม่ใช่เมมร้านนี้ → merge
      r.status = 'merge';
      r.message = ms.length > 0
        ? `เพิ่มเมม ${r.shop === 'geisha' ? '🌸' : '🎌'} ให้ ${existing.name || existing.id}`
        : `อัปเดตลูกค้าเก่า (เคยจอง)`;
      r._existing = existing;
      return;
    }
    
    // ถ้ามาถึงนี่ = valid new
    r.message = `เพิ่มเมม ${r.shop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'} (ลูกค้าใหม่)`;
  });
  
  return rows;
}

// แสดง preview screen (Step 2)
function showImportPreview() {
  const rows = importState.rows;
  const counts = {
    valid: rows.filter(r => r.status === 'valid').length,
    merge: rows.filter(r => r.status === 'merge').length,
    skip: rows.filter(r => r.status === 'skip').length,
    error: rows.filter(r => r.status === 'error').length
  };
  const willImport = counts.valid + counts.merge;
  
  const tableRows = rows.map((r, i) => {
    // ⭐ Round 7.63c hotfix: status "ใหม่" → "เมม Geisha/Yoshi" — ลดความสับสนกับ tier "New"
    const validLabel = r.shop === 'geisha' ? '🌸 เมม Geisha' : '🎌 เมม Yoshi';
    const statusLabel = {
      valid: validLabel,
      merge: '🔄 รวม',
      skip: '⊘ ข้าม',
      error: '✗ ผิด'
    }[r.status];
    const codeWarn = r._codeMismatch ? ' ⚠️' : '';
    return `<tr class="imp-row-${r.status}">
      <td><span class="imp-row-status ${r.status}">${statusLabel}</span></td>
      <td>${r.shop === 'geisha' ? '🌸' : '🎌'}</td>
      <td><code>${escapeHtml(r.code)}${codeWarn}</code></td>
      <td>${escapeHtml(r.name)}</td>
      <td class="mono">${escapeHtml(r.phone)}</td>
      <td style="font-size:11.5px; color:var(--text-soft);">${escapeHtml(r.message)}</td>
    </tr>`;
  }).join('');
  
  const html = `
    <div class="modal" style="max-width:720px;">
      <div class="modal-head">
        <h3>📥 ตรวจสอบก่อน import</h3>
        <button class="x-btn">×</button>
      </div>
      <div class="modal-body">
        <div style="font-size:13px; color:var(--text-soft); margin-bottom:8px;">
          ไฟล์: <strong>${escapeHtml(importState.fileName)}</strong> · ${rows.length} แถว
        </div>
        <div class="imp-summary">
          <div class="imp-stat valid"><span class="num">${counts.valid}</span><span class="lbl">✓ เพิ่มเมมใหม่</span></div>
          <div class="imp-stat merge"><span class="num">${counts.merge}</span><span class="lbl">🔄 รวมเข้าลูกค้าเก่า</span></div>
          <div class="imp-stat skip"><span class="num">${counts.skip}</span><span class="lbl">⊘ ข้าม (เป็นเมมแล้ว)</span></div>
          <div class="imp-stat error"><span class="num">${counts.error}</span><span class="lbl">✗ ผิดพลาด</span></div>
        </div>
        <div class="imp-table-wrap">
          <table class="imp-table">
            <thead>
              <tr>
                <th>สถานะ</th>
                <th>ร้าน</th>
                <th>รหัส</th>
                <th>ชื่อ</th>
                <th>เบอร์</th>
                <th>หมายเหตุ</th>
              </tr>
            </thead>
            <tbody>${tableRows}</tbody>
          </table>
        </div>
        ${counts.error > 0 ? `<div style="margin-top:10px; padding:8px 11px; background:#fee2e2; color:#991b1b; border-radius:8px; font-size:12.5px;">⚠️ มี ${counts.error} แถวที่ผิด — จะถูกข้าม ไม่ import</div>` : ''}
      </div>
      <div class="modal-foot">
        <button class="btn modal-close">ยกเลิก</button>
        <button class="btn btn-accent" id="imp-confirm" ${willImport === 0 ? 'disabled' : ''}>
          ${willImport === 0 ? 'ไม่มีรายการที่จะ import' : `✅ ยืนยัน import (${willImport} รายการ)`}
        </button>
      </div>
    </div>
  `;
  openModal(html);
  
  if (willImport > 0) {
    $('#imp-confirm').addEventListener('click', () => runImport());
  }
}

// Execute import (writeBatch — chunk 400 ops)
async function runImport() {
  const rows = importState.rows.filter(r => r.status === 'valid' || r.status === 'merge');
  if (rows.length === 0) return;
  
  const total = rows.length;
  let done = 0;
  let failed = 0;
  
  // Show progress modal
  const progHtml = `
    <div class="modal" style="max-width:420px;">
      <div class="modal-head"><h3>📥 กำลัง import...</h3></div>
      <div class="modal-body">
        <div class="imp-progress">
          <div id="imp-prog-text">กำลังบันทึก...</div>
          <div class="imp-progress-bar"><div class="imp-progress-fill" id="imp-prog-fill" style="width:0%"></div></div>
          <div id="imp-prog-count" style="font-size:12px; color:var(--text-soft);">0 / ${total}</div>
        </div>
      </div>
    </div>
  `;
  openModal(progHtml);
  
  const updateProg = (n) => {
    const pct = Math.round((n / total) * 100);
    const fill = $('#imp-prog-fill'); if (fill) fill.style.width = pct + '%';
    const cnt = $('#imp-prog-count'); if (cnt) cnt.textContent = `${n} / ${total}`;
  };
  
  // Group rows by phone (กรณีไฟล์เดียวมีคนเดียวกันเป็นเมม 2 ร้าน)
  const byPhone = new Map();
  rows.forEach(r => {
    if (!byPhone.has(r.phone)) byPhone.set(r.phone, []);
    byPhone.get(r.phone).push(r);
  });
  
  // ใช้ writeBatch — 1 batch ต่อ 1 customer (เพราะแต่ละ doc คือ 1 op)
  // chunk ขนาด 400 ops/batch (Firestore limit = 500)
  const BATCH_SIZE = 400;
  const phoneEntries = Array.from(byPhone.entries());
  
  try {
    for (let i = 0; i < phoneEntries.length; i += BATCH_SIZE) {
      const chunk = phoneEntries.slice(i, i + BATCH_SIZE);
      const batch = writeBatch(db);
      
      for (const [phone, phoneRows] of chunk) {
        const existing = (state.customers || []).find(c => c.id === phone);
        const oldMs = existing ? getCustomerMemberships(existing) : [];
        
        // สร้าง memberships ใหม่ — เก็บของเก่า + เพิ่มของใหม่จาก import
        const newMs = [...oldMs];
        let lastNew = null;
        for (const r of phoneRows) {
          const m = { code: r.code, shop: r.shop, since: r.since || '' };
          if (r.note) m.note = r.note;
          // ถ้าเคยมี shop นี้ → skip (กันเขียนทับ — แต่จริง ๆ classifyImportRows ก็กันแล้ว)
          if (newMs.some(om => om.shop === m.shop)) continue;
          newMs.push(m);
          lastNew = r;
        }
        if (newMs.length === oldMs.length) continue;  // nothing new
        
        const docRef = doc(db, 'bookingCustomers', phone);
        const data = {
          name: existing?.name || lastNew.name,
          phone,
          memberships: newMs,
          // legacy single fields — ใช้ของล่าสุด
          memberCode: lastNew.code,
          memberShop: lastNew.shop,
          memberSince: lastNew.since || ''
        };
        // ลูกค้าใหม่ → init bookingCount + timestamp
        if (!existing) {
          data.bookingCount = 0;
          data.bookingCreatedAt = serverTimestamp();
        }
        
        batch.set(docRef, data, { merge: true });
        done++;
      }
      
      await batch.commit();
      updateProg(done);
    }
    
    // Audit log
    await writeAuditLog('import', 'member', importState.fileName, {
      total: rows.length,
      imported: done,
      file: importState.fileName
    });
    
    // Done
    closeModal();
    alert(`✅ Import สำเร็จ!\n\n• เพิ่ม/อัปเดต: ${done} ลูกค้า\n• ข้าม (เมมแล้ว/ผิด): ${importState.rows.length - rows.length}`);
  } catch (err) {
    console.error('Import failed:', err);
    failed = rows.length - done;
    closeModal();
    alert(`❌ Import ผิดพลาด\n\n• สำเร็จ: ${done}\n• ล้มเหลว: ${failed}\n\nError: ${err?.message || err}`);
  }
}

// ⭐ Round 7.61: helper — apply filter chip
// ⭐ Round 7.62: Fix — count จาก state.bookings จริง (ลูกค้าเก่ามี bookingCount = 0)
function getCustomerBookingCount(customer) {
  if (!customer || !customer.id) return 0;
  // นับจาก state.bookings ที่ status != cancelled (เผื่อ field bookingCount ใน Firestore เก่าไม่มี)
  if (state.bookings && state.bookings.length > 0) {
    const count = state.bookings.filter(b => 
      b.customerPhone === customer.id && b.status !== 'cancelled'
    ).length;
    // ถ้านับได้ → ใช้ค่านั้น (เชื่อถือได้กว่า field เก่า)
    if (count > 0) return count;
  }
  // Fallback to stored field (สำหรับลูกค้าที่ไม่มีใน bookings เพราะ booking เก่าโดนลบ)
  return customer.bookingCount ?? 0;
}

function applyCustomerFilter(list, filter) {
  if (filter === 'all') return list;
  
  if (filter === 'member') {
    // ⭐ Round 7.62: ตรวจทั้ง customer.memberCode + booking.memberCode
    //   เพราะลูกค้าบางคนเคยจองแบบเมม แต่ยังไม่มี field ใน customer doc
    const memberPhones = new Set();
    if (state.bookings) {
      state.bookings.forEach(b => {
        if (b.memberCode && b.customerPhone) {
          memberPhones.add(b.customerPhone);
        }
      });
    }
    return list.filter(c => c.memberCode || memberPhones.has(c.id) || getCustomerMemberships(c).length > 0);
  }
  
  // ⭐ Round 7.67: filter เมมแยกร้าน
  if (filter === 'member-geisha') {
    return list.filter(c => isCustomerMemberOf(c, 'geisha'));
  }
  if (filter === 'member-yoshi') {
    return list.filter(c => isCustomerMemberOf(c, 'yoshi'));
  }
  
  if (filter === 'new') {
    // ⭐ Round 7.62: ลูกค้าใหม่ = จอง 1 ครั้ง (นับจาก state.bookings จริง)
    return list.filter(c => getCustomerBookingCount(c) === 1);
  }
  
  if (filter === 'regular') {
    // ⭐ Round 7.62: ลูกค้าประจำ = จอง 5 ครั้งขึ้นไป (นับจาก state.bookings จริง)
    return list.filter(c => getCustomerBookingCount(c) >= 5);
  }
  
  // ⭐ r38r15aaa: ลูกค้าที่เคยใช้คูปอง (match by id หรือ phone)
  if (filter === 'coupon') {
    return list.filter(c => {
      const stats = (typeof getCustomerCouponStats === 'function') ? getCustomerCouponStats(c) : null;
      return stats && stats.count > 0;
    });
  }
  
  if (filter === 'inactive') {
    // ไม่กลับมา 30 วัน = lastBookingDate เก่ากว่า 30 วัน
    const today = new Date();
    const cutoff = new Date(today);
    cutoff.setDate(cutoff.getDate() - 30);
    const cutoffStr = ymd(cutoff);
    return list.filter(c => {
      const last = c.lastBookingDate || c.lastVisit || '';
      if (!last) return false;  // ไม่เคยจอง = ไม่นับ inactive
      return last < cutoffStr;
    });
  }
  
  return list;
}

// ⭐ Round 7.61: helper — apply sort
function applyCustomerSort(list, sort) {
  const arr = list.slice();
  if (sort === 'name') {
    arr.sort((a, b) => (a.name || '').localeCompare(b.name || '', 'th'));
  } else if (sort === 'bookings') {
    // ⭐ Round 7.62: นับจาก state.bookings จริง
    arr.sort((a, b) => getCustomerBookingCount(b) - getCustomerBookingCount(a));
  } else {
    // recent (default)
    arr.sort((a, b) => 
      ((b.lastBookingDate||b.lastVisit)||'').localeCompare((a.lastBookingDate||a.lastVisit)||''));
  }
  return arr;
}

function renderCustomers() {
  if (!$('#view-customers').classList.contains('active')) return;
  const q = ($('#cust-search')?.value || '').toLowerCase().trim();
  let list = state.customers || [];
  
  // 1) Filter ตามคำค้นหา
  if (q) list = list.filter(c =>
    (c.name||'').toLowerCase().includes(q) ||
    (c.phone||'').includes(q) ||
    (c.memberCode||'').toLowerCase().includes(q));
  
  // ⭐ Round 7.63a: Filter ตามร้าน (ใช้ global state.shopFilter จาก top bar)
  //   'both' = แสดงทั้งหมด, 'geisha'/'yoshi' = กรองเฉพาะ
  if (state.shopFilter && state.shopFilter !== 'both') {
    list = list.filter(c => customerBelongsToShop(c, state.shopFilter, state.bookings));
  }
  
  // ⭐ Round 7.62: คำนวณ count สำหรับแต่ละ filter chip · 7.67: เพิ่มแยกร้าน
  const allCount = list.length;
  const memberCount = applyCustomerFilter(list, 'member').length;
  const memberGeishaCount = applyCustomerFilter(list, 'member-geisha').length;
  const memberYoshiCount = applyCustomerFilter(list, 'member-yoshi').length;
  const newCount = applyCustomerFilter(list, 'new').length;
  const regularCount = applyCustomerFilter(list, 'regular').length;
  // ⭐ r38r15aaa: เคยใช้คูปอง
  const couponCount = applyCustomerFilter(list, 'coupon').length;
  const inactiveCount = applyCustomerFilter(list, 'inactive').length;
  
  // อัพเดต count บน chip
  const chipCounts = {
    all: allCount,
    member: memberCount,
    'member-geisha': memberGeishaCount,
    'member-yoshi': memberYoshiCount,
    new: newCount,
    regular: regularCount,
    coupon: couponCount,  // ⭐ r38r15aaa
    inactive: inactiveCount
  };
  $$('#cust-filter-chips .cust-chip').forEach(chip => {
    const f = chip.dataset.filter;
    const cnt = chipCounts[f];
    // เก็บ label เดิม + เพิ่ม count
    const labels = {
      all: '🌐 ทั้งหมด',
      member: '👑 เมม',
      'member-geisha': '🌸 เมม Geisha',
      'member-yoshi': '🎌 เมม Yoshi',
      new: '🆕 ใหม่',
      regular: '🔥 ประจำ',
      coupon: '🎟️ ใช้คูปอง',  // ⭐ r38r15aaa
      inactive: '⏰ 30 วัน'
    };
    chip.textContent = `${labels[f] || ''} ${cnt > 0 ? cnt : ''}`;
  });
  
  // 2) Filter ตาม chip
  list = applyCustomerFilter(list, custViewState.filter);
  
  // 3) Sort
  list = applyCustomerSort(list, custViewState.sort);
  
  // ⭐ count badge
  const totalCustomers = state.customers?.length || 0;
  const badge = $('#cust-count-badge');
  if (badge) {
    // ⭐ Round 7.63a: badge แสดง partial count เมื่อมี search/filter/shop
    const shopActive = state.shopFilter && state.shopFilter !== 'both';
    if (q || custViewState.filter !== 'all' || shopActive) {
      badge.textContent = `· ${list.length} จาก ${totalCustomers} คน`;
    } else {
      badge.textContent = `· ${totalCustomers} คน`;
    }
  }
  
  // Empty state
  if (list.length === 0) {
    if (q) {
      $('#customers-list').innerHTML = `<div class="empty"><div class="emoji">🔍</div>ไม่พบลูกค้า "${escapeHtml(q)}"<br><span style="font-size:14px">ลองค้นด้วยคำอื่น หรือเปลี่ยน filter</span></div>`;
    } else if (state.shopFilter && state.shopFilter !== 'both') {
      // ⭐ Round 7.63a: Empty state เมื่อกรองตามร้าน (top bar)
      const shopLabel = state.shopFilter === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi';
      const filterHint = custViewState.filter !== 'all' ? `<br><span style="font-size:13px;">+ filter "${custViewState.filter}" — ลองกด "🌐 ทั้งหมด" หรือเปลี่ยนร้าน</span>` : '<br><span style="font-size:13px;">ยังไม่มีลูกค้าหรือเมมร้านนี้</span>';
      $('#customers-list').innerHTML = `<div class="empty">
        <div class="emoji">🏪</div>
        <strong>ไม่มีลูกค้าใน ${shopLabel}</strong>${filterHint}
      </div>`;
    } else if (custViewState.filter !== 'all') {
      // ⭐ Round 7.62: Empty state ที่ helpful — บอก user ว่าทำยังไง
      const filterInfo = {
        member: { 
          label: 'เมมเบอร์', 
          hint: 'ยังไม่มีลูกค้าที่สมัครเมม<br><span style="font-size:13px;">เปิดข้อมูลลูกค้า → กด "+ สมัครเมม" เพื่อสมัครให้ลูกค้า</span>'
        },
        new: { 
          label: 'ลูกค้าใหม่', 
          hint: 'ลูกค้าใหม่ = จองครั้งแรก (1 ครั้ง)<br><span style="font-size:13px;">ยังไม่มีลูกค้าใหม่ในตอนนี้</span>'
        },
        regular: { 
          label: 'ลูกค้าประจำ', 
          hint: 'ลูกค้าประจำ = จอง 5 ครั้งขึ้นไป<br><span style="font-size:13px;">ยังไม่มีลูกค้าประจำ — ต้องมีลูกค้าจอง 5 ครั้งขึ้นไปก่อน</span>'
        },
        inactive: { 
          label: 'ลูกค้าไม่กลับ 30 วัน', 
          hint: 'ลูกค้าที่จองล่าสุดเกิน 30 วัน<br><span style="font-size:13px;">ทุกคนยังจองภายใน 30 วันที่ผ่านมา 🎉</span>'
        }
      };
      const info = filterInfo[custViewState.filter] || { label: '', hint: 'ลองเลือก filter อื่น' };
      $('#customers-list').innerHTML = `<div class="empty">
        <div class="emoji">📭</div>
        <strong>ไม่มีลูกค้าใน "${info.label}"</strong><br>
        <span style="font-size:14px; color:var(--text-soft); display:block; margin-top:6px;">${info.hint}</span>
      </div>`;
    } else if (totalCustomers === 0) {
      $('#customers-list').innerHTML = `<div class="empty"><div class="emoji">👤</div>ยังไม่มีลูกค้า<br><span style="font-size:14px">ลูกค้าจะถูกเพิ่มอัตโนมัติเมื่อมีการจอง</span></div>`;
    } else {
      $('#customers-list').innerHTML = `<div class="empty"><div class="emoji">⏳</div>กำลังโหลดข้อมูล...</div>`;
    }
    return;
  }

  // ⭐ Round 7.61: Hybrid layout — render ทั้ง mobile list + desktop table (CSS toggle ตาม screen size)
  let html = '';
  
  // ── Mobile list ──
  html += `<div class="cust-list">`;
  list.forEach(c => {
    // ⭐ Round 7.62: ใช้ count จาก state.bookings จริง
    const bCount = getCustomerBookingCount(c);
    const bLast = c.lastBookingDate || c.lastVisit || '—';
    const bNote = c.bookingNote || c.note || '';
    const cCount = c.count ?? 0;
    const memberBadge = c.memberCode ? `<span class="cust-member-pill">👑 ${escapeHtml(c.memberCode)}</span>` : '';
    
    html += `<div class="cust-item" onclick="window.editCustomer('${c.id}')">
      <div class="cust-item-main">
        <div class="cust-item-name">
          <strong>${escapeHtml(c.name||'—')}</strong>
          ${memberBadge}
        </div>
        <div class="cust-item-phone mono">${escapeHtml(c.phone||'')}</div>
      </div>
      <div class="cust-item-meta">
        <div class="cust-item-stats">
          <span title="จำนวนครั้งจอง">📅 ${bCount}</span>
          ${cCount > 0 ? `<span title="คูปองที่รับไป" style="color:var(--green);">🎫 ${cCount}</span>` : ''}
        </div>
        <div class="cust-item-last mono">${bLast}</div>
      </div>
      ${bNote ? `<div class="cust-item-note">📝 ${escapeHtml(bNote)}</div>` : ''}
    </div>`;
  });
  html += `</div>`;
  
  // ── Desktop table ──
  html += `<div class="cust-table-wrap">
    <table class="cust-table">
      <thead>
        <tr>
          <th>ชื่อ</th>
          <th>เบอร์</th>
          <th>เมม</th>
          <th class="num">จอง</th>
          <th class="num">คูปอง</th>
          <th>ล่าสุด</th>
          <th>หมายเหตุ</th>
          <th></th>
        </tr>
      </thead>
      <tbody>`;
  list.forEach(c => {
    // ⭐ Round 7.62: ใช้ count จาก state.bookings จริง
    const bCount = getCustomerBookingCount(c);
    const bLast = c.lastBookingDate || c.lastVisit || '—';
    const bNote = c.bookingNote || c.note || '';
    // ⭐ r38r15aaa: คูปอง — ใช้ couponUsage stats (match by id OR phone)
    const cpnStats = (typeof getCustomerCouponStats === 'function') 
      ? getCustomerCouponStats(c) 
      : { count: 0, totalAmount: 0 };
    const cpnDisplay = cpnStats.count > 0
      ? `<span style="cursor:pointer;" onclick="event.stopPropagation(); window.openCouponHistoryModal && window.openCouponHistoryModal('${c.id}')">
          <strong>${cpnStats.count}×</strong>
          <span style="font-size:11px; color:var(--text-soft); margin-left:3px;">฿${cpnStats.totalAmount.toLocaleString()}</span>
        </span>`
      : '<span style="color:var(--text-mute);">—</span>';
    const memberBadge = c.memberCode ? `<span class="cust-member-pill">👑 ${escapeHtml(c.memberCode)}</span>` : '<span style="color:var(--text-mute);">—</span>';
    
    html += `<tr onclick="window.editCustomer('${c.id}')">
      <td><strong>${escapeHtml(c.name||'—')}</strong></td>
      <td class="mono" style="color:var(--text-soft);">${escapeHtml(c.phone||'')}</td>
      <td>${memberBadge}</td>
      <td class="num" style="color:var(--gold); font-weight:700;">${bCount}</td>
      <td class="num" style="color:${cpnStats.count > 0 ? 'var(--green)' : 'var(--text-mute)'}; font-weight:${cpnStats.count > 0 ? '700' : '400'};">${cpnDisplay}</td>
      <td class="mono" style="color:var(--text-soft);">${bLast}</td>
      <td style="color:var(--text-soft); max-width:200px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${bNote ? '📝 '+escapeHtml(bNote) : '<span style="color:var(--text-mute);">—</span>'}</td>
      <td><button class="mini-btn" onclick="event.stopPropagation(); window.editCustomer('${c.id}')">✏️</button></td>
    </tr>`;
  });
  html += `</tbody></table></div>`;
  
  $('#customers-list').innerHTML = html;
}

// ─── เลขรหัสเมมเบอร์ถัดไป ──
// Format: 69MB01 (Geisha) / 69MY01 (Yoshi)
// 69 = พ.ศ.2569 (BE 2-digit), MB/MY = Member Beauty/Male, 01-99
function getNextMemberCode(shop) {
  const yearBE2 = String((new Date().getFullYear() + 543) % 100).padStart(2,'0');
  const prefix = shop === 'yoshi' ? `${yearBE2}MY` : `${yearBE2}MB`;
  // หาเลขที่ใช้แล้ว — ใช้ทั้ง state.customers และ check แบบสด (ป้องกัน race condition)
  const used = new Set();
  state.customers.forEach(c => {
    if (c.memberCode && typeof c.memberCode === 'string' && c.memberCode.startsWith(prefix)) {
      const n = parseInt(c.memberCode.slice(prefix.length), 10);
      if (!isNaN(n)) used.add(n);
    }
  });
  for (let i = 1; i <= 99; i++) {
    if (!used.has(i)) return `${prefix}${String(i).padStart(2,'0')}`;
  }
  return null;
}

// ─── ตรวจรหัสเมมว่าซ้ำไหม ──
function findCustomerByMemberCode(code) {
  if (!code) return null;
  return state.customers.find(c => c.memberCode === code) || null;
}

window.editCustomer = (phone) => {
  const c = state.customers.find(x => x.id === phone);
  if (!c) return;
  
  const isMember = !!c.memberCode;
  const memberShop = c.memberShop || '';
  
  // ⭐ ประวัติการจอง 10 รอบล่าสุด
  const history = state.bookings
    .filter(b => b.customerPhone === phone)
    .sort((a,b) => (b.date||'').localeCompare(a.date||'') || b.startTime.localeCompare(a.startTime))
    .slice(0, 10);
  
  // นับสถิติพนักงาน
  const staffStats = {};
  state.bookings.filter(b => b.customerPhone === phone && b.status !== 'cancelled').forEach(b => {
    const name = getStaffName(b.staffId);
    staffStats[name] = (staffStats[name] || 0) + 1;
  });
  const sortedStats = Object.entries(staffStats).sort((a,b) => b[1] - a[1]).slice(0, 3);
  const statsHtml = sortedStats.length 
    ? sortedStats.map(([n, c]) => `<span style="background:var(--bg-elev-2); padding:3px 8px; border-radius:6px; font-size:12px; margin-right:4px;">${n} (${c})</span>`).join('')
    : '<span style="color:var(--text-mute);">ยังไม่มี</span>';
  
  const historyHtml = history.length === 0 
    ? '<div class="helper" style="text-align:center; padding:20px;">ยังไม่มีประวัติการจอง</div>'
    : history.map(b => {
        const sName = getStaffName(b.staffId);
        const dur = timeToMin(b.endTime) - timeToMin(b.startTime);
        const cancelled = b.status === 'cancelled';
        const memberBadge = b.memberCode ? `<span class="member-badge" style="font-size:10px; padding:1px 5px;">👑</span>` : '';
        return `<div class="history-row${cancelled?' history-cancelled':''}">
          <div class="hr-date">${b.date.slice(5)} ${b.startTime}</div>
          <div class="hr-content">
            <div class="hr-staff">${escapeHtml(sName)} ${memberBadge}</div>
            <div class="hr-detail">${dur}น · ${b.shop==='yoshi'?'🎌':'🌸'} · ${b.finalPrice ?? b.price}฿${cancelled ? ' · ❌ ยกเลิก' : ''}</div>
          </div>
        </div>`;
      }).join('');
  
  openModal(`
    <div class="modal">
      <div class="modal-head"><h3>แก้ไขลูกค้า</h3><button class="x-btn">×</button></div>
      <div class="modal-body">
        <div class="field"><label class="field-label">ชื่อ</label><input id="ec-name" value="${escapeHtml(c.name||'')}"></div>
        <div class="field"><label class="field-label">เบอร์</label><input value="${escapeHtml(c.phone||'')}" disabled></div>
        <div class="field"><label class="field-label">หมายเหตุ</label><textarea id="ec-note" rows="2">${escapeHtml(c.bookingNote || c.note || '')}</textarea></div>
        
        <div class="field" style="background:var(--bg-elev-2); padding:14px; border-radius:10px; margin-top:14px;">
          <label class="field-label" style="display:flex; align-items:center; gap:8px;">
            👑 สถานะเมมเบอร์
            ${isMember ? `<span class="member-badge">${escapeHtml(c.memberCode)}</span>` : '<span style="color:var(--text-mute); font-weight:400;">— ยังไม่ใช่เมมเบอร์</span>'}
          </label>
          
          ${isMember ? `
            <div class="helper" style="margin-bottom:8px;">
              สมัครเมื่อ: ${c.memberSince || '—'} · ร้าน: ${memberShop === 'yoshi' ? 'Yoshi' : 'Geisha'}<br>
              <strong>💡 จอง LINE จะลด 100฿ อัตโนมัติ</strong>
            </div>
            <button class="btn btn-danger mini-btn" id="ec-remove-member" style="font-size:13px;">🗑️ ลบสถานะเมมเบอร์</button>
          ` : `
            <div class="helper" style="margin-bottom:10px;">
              ลูกค้าจะได้ลด 100฿ ทุกครั้งที่จองผ่าน LINE
            </div>
            <div style="display:grid; grid-template-columns:1fr 1fr; gap:8px; margin-bottom:10px;">
              <button class="btn" id="ec-create-geisha">+ สมัครเมม Geisha</button>
              <button class="btn" id="ec-create-yoshi">+ สมัครเมม Yoshi</button>
            </div>
            <div class="helper">หรือใส่รหัสที่มีอยู่ (เช่น ${String((new Date().getFullYear() + 543) % 100).padStart(2,'0')}MB01):</div>
            <div style="display:flex; gap:8px;">
              <input id="ec-existing-code" placeholder="${String((new Date().getFullYear() + 543) % 100).padStart(2,'0')}MB01" style="flex:1; text-transform:uppercase;">
              <button class="btn" id="ec-link-existing">ผูก</button>
            </div>
          `}
        </div>

        <!-- ⭐ Customer History -->
        <div class="field" style="margin-top:14px;">
          <label class="field-label" style="display:flex; align-items:center; gap:8px;">
            📋 ประวัติการจอง
            <span style="color:var(--text-mute); font-weight:400; font-size:13px;">${history.length} ครั้งล่าสุด</span>
          </label>
          ${(c.cancelCount || 0) > 0 ? `<div class="helper" style="color:${(c.cancelCount||0) >= 3 ? 'var(--red)' : 'var(--text-soft)'};">${(c.cancelCount||0) >= 3 ? '⚠️' : '·'} ยกเลิก ${c.cancelCount} ครั้ง</div>` : ''}
          <div class="helper" style="margin:6px 0;">พนง. ที่จองบ่อย: ${statsHtml}</div>
          <div class="history-list">${historyHtml}</div>
        </div>
      </div>
      <div class="modal-foot"><span></span><div class="right-group">
        ${state.user?.role === 'owner' ? `<button class="btn btn-danger" id="ec-delete-customer" style="margin-right:auto;">🗑️ ลบลูกค้า</button>` : ''}
        <button class="btn modal-close">ยกเลิก</button>
        <button class="btn btn-accent" id="ec-save">บันทึก</button>
      </div></div>
    </div>
  `);
  
  $('#ec-save').onclick = async () => {
    await setDoc(doc(db, 'bookingCustomers', phone), {
      name: $('#ec-name').value.trim(),
      bookingNote: $('#ec-note').value.trim()
    }, { merge: true });
    toast('บันทึกแล้ว', 'success');
    closeModal();
  };
  
  if ($('#ec-create-geisha')) {
    $('#ec-create-geisha').onclick = () => assignMemberCode(phone, 'geisha');
  }
  if ($('#ec-create-yoshi')) {
    $('#ec-create-yoshi').onclick = () => assignMemberCode(phone, 'yoshi');
  }
  if ($('#ec-link-existing')) {
    $('#ec-link-existing').onclick = () => linkExistingMemberCode(phone);
  }
  if ($('#ec-remove-member')) {
    $('#ec-remove-member').onclick = () => removeMemberCode(phone);
  }
  
  // ⭐ Round 7.63b: ปุ่มลบลูกค้า
  // ⭐ Round 7.75r35: Owner-only
  if ($('#ec-delete-customer')) {
    $('#ec-delete-customer').onclick = async () => {
      if (state.user?.role !== 'owner') {
        toast('❌ เฉพาะเจ้าของเท่านั้น', 'error');
        return;
      }
      const bookingsCount = state.bookings.filter(b => b.customerPhone === phone && b.status !== 'cancelled').length;
      const memberships = getCustomerMemberships(c);
      const memberInfo = memberships.length > 0
        ? `\n• เป็นเมม: ${memberships.map(m => `${m.shop === 'geisha' ? '🌸 Geisha' : '🎌 Yoshi'} (${m.code})`).join(', ')}`
        : '';
      const bookingInfo = bookingsCount > 0
        ? `\n• มีประวัติจอง ${bookingsCount} ครั้ง (จะยังคงอยู่ในระบบจอง — แค่ไม่มีในรายการลูกค้า)`
        : '';
      
      const msg = `❌ ลบลูกค้า: ${c.name || phone}\n` +
        `เบอร์: ${phone}${memberInfo}${bookingInfo}\n\n` +
        `การลบจะลบเฉพาะข้อมูลลูกค้า — ประวัติการจองยังคงอยู่\n\n` +
        `ยืนยันลบ?`;
      
      if (!confirm(msg)) return;
      
      try {
        await deleteDoc(doc(db, 'bookingCustomers', phone));
        await writeAuditLog('delete', 'customer', phone, {
          customerName: c.name, hadMemberships: memberships.length, hadBookings: bookingsCount
        });
        toast(`✓ ลบ ${c.name || phone} แล้ว`, 'success');
        closeModal();
      } catch (err) {
        console.error('Delete customer failed:', err);
        toast('ลบไม่สำเร็จ: ' + (err?.message || err), 'error');
      }
    };
  }
};

// สมัครเมมเบอร์ใหม่ — สร้างรหัสถัดไป
async function assignMemberCode(phone, shop) {
  const code = getNextMemberCode(shop);
  if (!code) { toast('รหัสเมมเต็มแล้ว (ครบ 99)', 'error'); return; }
  if (!confirm(`สมัครเมมเบอร์ใหม่: ${code} (${shop === 'yoshi' ? 'Yoshi' : 'Geisha'})?`)) return;
  
  // ✅ Double-check ก่อน save — ป้องกัน race condition
  const existing = findCustomerByMemberCode(code);
  if (existing && existing.id !== phone) {
    toast(`รหัส ${code} ถูกใช้แล้ว — ลองอีกครั้ง`, 'error');
    return;
  }
  
  setLoading(true);
  try {
    await setDoc(doc(db, 'bookingCustomers', phone), {
      memberCode: code,
      memberShop: shop,
      memberSince: ymd(new Date())
    }, { merge: true });
    await writeAuditLog('member_create', 'customer', phone, { code, shop });
    toast(`✓ สมัครเมม ${code}`, 'success');
    closeModal();
    
    // ✅ รอจน state.customers sync แล้วถึงเปิด modal ใหม่
    await waitForCustomerSync(phone, code);
    window.editCustomer(phone);
  } catch (e) { toast(e.message, 'error'); }
  finally { setLoading(false); }
}

// รอจน state.customers มีรหัสที่ save แล้ว
async function waitForCustomerSync(phone, expectedCode, maxWaitMs = 2000) {
  const start = Date.now();
  while (Date.now() - start < maxWaitMs) {
    const c = state.customers.find(x => x.id === phone);
    if (c && c.memberCode === expectedCode) return true;
    await new Promise(r => setTimeout(r, 50));
  }
  return false; // timeout
}

// ผูกรหัสที่มี
async function linkExistingMemberCode(phone) {
  const code = $('#ec-existing-code').value.trim().toUpperCase();
  if (!code) return toast('ใส่รหัสก่อน', 'error');
  
  // ตรวจ format
  const yearBE2 = String((new Date().getFullYear() + 543) % 100).padStart(2,'0');
  const m = code.match(/^(\d{2})M([BY])(\d{2})$/);
  if (!m) {
    toast(`รหัสไม่ถูก (ต้องเป็น ${yearBE2}MB01 หรือ ${yearBE2}MY01)`, 'error');
    return;
  }
  
  const shop = m[2] === 'Y' ? 'yoshi' : 'geisha';
  
  // ตรวจซ้ำ
  const existing = findCustomerByMemberCode(code);
  if (existing && existing.id !== phone) {
    if (!confirm(`รหัส ${code} ใช้กับลูกค้า "${existing.name}" อยู่แล้ว\nต้องการย้ายมาที่ลูกค้านี้?`)) return;
    // ลบรหัสจาก existing customer ก่อน
    setLoading(true);
    try {
      await updateDoc(doc(db, 'bookingCustomers', existing.id), {
        memberCode: null, memberShop: null, memberSince: null
      });
    } catch {} 
    finally { setLoading(false); }
  }
  
  setLoading(true);
  try {
    await setDoc(doc(db, 'bookingCustomers', phone), {
      memberCode: code,
      memberShop: shop,
      memberSince: ymd(new Date())
    }, { merge: true });
    await writeAuditLog('member_link', 'customer', phone, { code, shop });
    toast(`✓ ผูกเมม ${code}`, 'success');
    closeModal();
    await waitForCustomerSync(phone, code);
    window.editCustomer(phone);
  } catch (e) { toast(e.message, 'error'); }
  finally { setLoading(false); }
}

// ลบสถานะเมม
async function removeMemberCode(phone) {
  const c = state.customers.find(x => x.id === phone);
  if (!c?.memberCode) return;
  if (!confirm(`ลบสถานะเมม ${c.memberCode} จากลูกค้านี้?`)) return;
  
  setLoading(true);
  try {
    await updateDoc(doc(db, 'bookingCustomers', phone), {
      memberCode: null, memberShop: null, memberSince: null
    });
    await writeAuditLog('member_remove', 'customer', phone, { code: c.memberCode });
    toast('ลบเมมแล้ว', 'success');
    closeModal();
    // รอ state sync (memberCode = null)
    const start = Date.now();
    while (Date.now() - start < 2000) {
      const cc = state.customers.find(x => x.id === phone);
      if (!cc?.memberCode) break;
      await new Promise(r => setTimeout(r, 50));
    }
    window.editCustomer(phone);
  } catch (e) { toast(e.message, 'error'); }
  finally { setLoading(false); }
}

