function renderOwnerSubTab(stats, range, profit, expenses, carriedOver = 0) {
  switch (ownerState.subTab) {
    case 'income': return renderOwnerIncome(stats, range, carriedOver);
    case 'expense': return renderOwnerExpense(stats, range, expenses);
    case 'pnl': return renderOwnerPnL(stats, range, profit, expenses, carriedOver);
    case 'analytics': return renderOwnerAnalytics(stats, range);
    case 'staffpay': return renderOwnerStaffPay(stats, range);
    case 'history': return renderOwnerHistory(range);
    case 'maintenance': return renderOwnerMaintenance();
    default: return renderOwnerMainDashboard(stats, range, profit, expenses, carriedOver);
  }
}

