// Helper: calculate completion %
function calcStaffProfileCompletion(profile) {
  // Private section fields (10)
  const privateFields = [
    'fullName', 'ethnicity', 'bloodType', 'phone', 'birthDate', 
    'workSchedule', 'licenseStatus', 'homeShop', 'livingNear', 'bank.name'
  ];
  // Customer section fields (10)
  const customerFields = [
    'ageDisplay', 'realMeasurements.height', 'displayMeasurements.height',
    'whitenessLevel', 'bodyType', 'breastSize', 'breastType',
    'nippleColor', 'pubicHair', 'pubicStyle'
  ];
  // Limits section fields (7)
  const limitsFields = [
    'limits.breastfeeding', 'limits.bodyPaint', 'limits.kiss', 
    'limits.fingerVagina', 'limits.spray', 'limits.slaveCourse', 'limits.licksArmpit'
  ];
  // ⭐ r38r17n: Exam scores (3 subjects)
  const examFields = [
    'examScores.thai', 'examScores.b2b', 'examScores.oil',
  ];
  
  // ⭐ r38r17aa: ถ้าไม่มี profile → return 0/N structure
  if (!profile) {
    return {
      private: { filled: 0, total: privateFields.length },
      customer: { filled: 0, total: customerFields.length },
      limits: { filled: 0, total: limitsFields.length },
      exam: { filled: 0, total: examFields.length },
      highlights: { filled: 0, total: 1 },   // ⭐ r38r29cj: จุดเด่นบริการ 1/1
    };
  }
  
  const getField = (obj, path) => path.split('.').reduce((o, k) => o?.[k], obj);
  const countFilled = (fields) => fields.filter(f => {
    // ⭐ r38r17u: ถ้า hasBank===false → ถือว่า bank.name เติมแล้ว (พนง.ไม่มีบัญชี)
    if (f === 'bank.name' && profile.hasBank === false) return true;
    const v = getField(profile, f);
    return v !== null && v !== undefined && v !== '';
  }).length;
  
  return {
    private: { filled: countFilled(privateFields), total: privateFields.length },
    customer: { filled: countFilled(customerFields), total: customerFields.length },
    limits: { filled: countFilled(limitsFields), total: limitsFields.length },
    exam: { filled: countFilled(examFields), total: examFields.length },
    highlights: { filled: (Array.isArray(profile.highlights) && profile.highlights.length > 0) ? 1 : 0, total: 1 },   // ⭐ r38r29cj
  };
}
window.calcStaffProfileCompletion = calcStaffProfileCompletion;

