  if (!file || !file.type.startsWith('image/')) throw new Error('ไฟล์ไม่ใช่รูป');
  if (typeof onProgress === 'function') onProgress('ย่อรูป…');
  const blob = await _resizeImageToBlob(file, 800, 0.8);
  if (typeof onProgress === 'function') onProgress('อัปโหลด…');
  const sref = storageRef(storage, `staff_highlight/${staffId}.jpg`);
