    const bodyMap = { slim: 'ผอม', medium: 'สมส่วน', plump: 'อวบ' };
    const breastSizeMap = { small: 'เล็ก', medium: 'กลาง', large: 'ใหญ่' };
    const breastTypeMap = { natural: '💧 แท้', enhanced: '✨ เสริม' };
    const nippleColorMap = { light: 'อ่อน', medium: 'กลาง', dark: 'เข้ม' };
    const nippleSizeMap = { small: 'เล็ก', medium: 'กลาง', large: 'ใหญ่' };
    const pubicHairMap = { low: 'น้อย', medium: 'กลาง', high: 'เยอะ' };
    const pubicStyleMap = { shaved: 'โกน', trimmed: 'ตัดแต่ง', natural: 'ปล่อยธรรมชาติ' };
    
