// ⭐ r38r29gk: export ฝั่ง browser — inject A4 landscape + fit-to-width (xlsx-js-style ไม่เขียน pageSetup/sheetPr เอง) ผ่าน JSZip
async function _downloadXlsxA4Landscape(wb, fileName) {
  let wbout;
  try { wbout = XLSX.write(wb, { type:'array', bookType:'xlsx' }); }
  catch(e){ XLSX.writeFile(wb, fileName); return false; }
  let JZ = window.JSZip;
  if (!JZ) {
    try {
      await new Promise((res, rej) => {
        const s = document.createElement('script');
        s.src = 'https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';
        s.onload = res; s.onerror = () => rej(new Error('jszip load failed'));
        document.head.appendChild(s);
      });
      JZ = window.JSZip;
    } catch(e) { JZ = null; }
  }
  if (!JZ) { XLSX.writeFile(wb, fileName); return false; }   // fallback — ไฟล์ยังใช้ได้ (แค่ไม่ fit A4)
  try {
    const zip = await JZ.loadAsync(wbout);
    const SP = '<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>';
    const PS = '<pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/>';
    const files = Object.keys(zip.files).filter(f => /^xl\/worksheets\/sheet\d+\.xml$/.test(f));
    for (const sf of files) {
      let xml = await zip.file(sf).async('string');
      if (!/<sheetPr[ >]/.test(xml)) xml = xml.replace(/(<worksheet [^>]*>)/, '$1' + SP);
      if (!/<pageSetup[ >]/.test(xml)) {
        if (/<pageMargins[^>]*\/>/.test(xml)) xml = xml.replace(/(<pageMargins[^>]*\/>)/, '$1' + PS);
        else xml = xml.replace(/(<\/worksheet>)/, PS + '$1');
      }
      zip.file(sf, xml);
    }
    const blob = await zip.generateAsync({ type:'blob', mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = fileName;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    return true;
  } catch(e) { console.error('A4 inject failed:', e); XLSX.writeFile(wb, fileName); return false; }
}

