// ⭐ r38r17n: Step 10 — Exam scores
function _step10_exam(wiz) {
  const f = wiz.form;
  const ex = f.examScores || {};
  
  const scoreColor = (score) => {
    if (score === null || score === undefined || score === '') return '#9ca3af';
    const n = Number(score);
    if (n >= 8) return '#10b981';
    if (n >= 6) return '#3b82f6';
    if (n >= 4) return '#f59e0b';
    return '#ef4444';
  };
  
  // ⭐ r38r17o: Number input + slider sync, step 0.5
  const renderScoreInput = (label, icon, field) => {
    const curVal = ex[field];
    const hasVal = curVal !== null && curVal !== undefined && curVal !== '';
    return `
    <div style="padding:12px; background:#f9fafb; border:1px solid var(--line); border-radius:8px; margin-bottom:10px;">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; gap:8px;">
        <span style="font-weight:600; font-size:13px; flex:1;">${icon} ${label}</span>
        <input type="number" id="spw-exam-num-${field}" min="0" max="10" step="0.5"
          value="${hasVal ? curVal : ''}"
          data-exam-field="${field}"
          class="spw-exam-num"
          placeholder="—"
          inputmode="decimal"
          style="width:68px; padding:6px 8px; border:1.5px solid ${scoreColor(curVal)}; border-radius:7px; font-size:18px; font-weight:700; text-align:center; color:${scoreColor(curVal)}; font-family:monospace; box-sizing:border-box;">
        <span style="font-size:12px; color:var(--text-soft); font-weight:600;">/10</span>
      </div>
      <input type="range" id="spw-exam-${field}" min="0" max="10" step="0.5" 
        value="${hasVal ? curVal : 0}" 
        data-exam-field="${field}"
        class="spw-exam-slider"
        style="width:100%; accent-color:${scoreColor(curVal)};">
      <div style="display:flex; justify-content:space-between; font-size:9px; color:var(--text-soft); margin-top:2px;">
        <span>0</span><span>2</span><span>4</span><span>6</span><span>8</span><span>10</span>
      </div>
    </div>
  `;
  };
  
  return `
    <div style="display:flex; flex-direction:column; gap:8px;">
      <div style="padding:8px 10px; background:#dbeafe; border:1px solid #3b82f6; border-radius:8px; font-size:11px; color:#1e40af;">
        💡 ให้คะแนน 1-10 ตามผลสอบ · เลื่อนเพื่อปรับ
      </div>
      
      ${renderScoreInput('นวดไทย', '🇹🇭', 'thai')}
      ${renderScoreInput('B2B', '💆', 'b2b')}
      ${renderScoreInput('นวดน้ำมัน', '🛢️', 'oil')}
      ${renderScoreInput('GF · แฟนสาว', '❤️', 'gf')}
      
      <div style="padding:12px; background:#fff5f7; border:1px solid #f9a8d4; border-radius:8px; margin-bottom:2px;">
        <div style="font-weight:700; font-size:12px; color:#9d174d; margin-bottom:6px;">⭐ จุดเด่น (ข้อความ) — โชว์บนการ์ดโปรไฟล์</div>
        <textarea id="spw-highlights-text" rows="2" placeholder="เช่น ก้นงอน อกอึ๋ม รอยยิ้มมีเสน่ห์ ขี้อ้อนสุดๆ"
          style="width:100%; padding:8px 10px; border:1px solid var(--line); border-radius:7px; font-size:13px; box-sizing:border-box; resize:vertical; font-family:inherit;">${escapeHtml(f.highlightsText || '')}</textarea>
      </div>
      
      <div style="padding:10px; background:#fef3c7; border:1px solid #f59e0b; border-radius:8px;">
        <div style="font-weight:700; font-size:12px; color:#78350f; margin-bottom:6px;">📅 ข้อมูลการสอบ (optional)</div>
        <div style="display:flex; flex-direction:column; gap:6px;">
          <input type="text" id="spw-exam-date" value="${escapeHtml(ex.lastTestDate || '')}" placeholder="วันที่สอบล่าสุด (เช่น 15/05/2569)"
            style="width:100%; padding:7px 9px; border:1px solid var(--line); border-radius:6px; font-size:12px; box-sizing:border-box;">
          <textarea id="spw-exam-note" placeholder="หมายเหตุ (จุดที่ต้องปรับปรุง / จุดเด่น)" rows="2"
            style="width:100%; padding:7px 9px; border:1px solid var(--line); border-radius:6px; font-size:12px; box-sizing:border-box; resize:vertical; font-family:inherit;">${escapeHtml(ex.note || '')}</textarea>
        </div>
      </div>
    </div>
  `;
}

