// Capture step data from inputs → wiz.form
function _captureStepData(wiz) {
  const f = wiz.form;
  switch (wiz.step) {
    case 1: {
      if (!f.staffId && !wiz.staffId) {
        const sel = $('#spw-staff-select')?.value;
        if (!sel) { toast('⚠️ กรุณาเลือกพนักงาน', 'error'); return false; }
        wiz.staffId = sel;
        f.staffId = sel;
      }
      break;
    }
    case 2:
      f.fullName = $('#spw-fullName')?.value || '';
      f.phone = $('#spw-phone')?.value || '';
      // ⭐ r38r17i: Convert พ.ศ. → ค.ศ.
      const bdInput = $('#spw-birthDate')?.value?.trim() || '';
      if (bdInput) {
        // Accept: dd/mm/yyyy พ.ศ. or dd/mm/yyyy ค.ศ. (auto-detect)
        const m = bdInput.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
        if (m) {
          let [, d, mo, y] = m;
          let year = parseInt(y);
          // พ.ศ. > 2400 → convert to ค.ศ.; otherwise treat as ค.ศ.
          if (year > 2400) year = year - 543;
          // pad month/day
          const dd = d.padStart(2, '0');
          const mm = mo.padStart(2, '0');
          // Validate
          if (year >= 1900 && year <= new Date().getFullYear() && 
              parseInt(mm) >= 1 && parseInt(mm) <= 12 && 
              parseInt(dd) >= 1 && parseInt(dd) <= 31) {
            f.birthDate = `${year}-${mm}-${dd}`;
          } else {
            toast('⚠️ วันเกิดไม่ถูกต้อง', 'error');
            return false;
          }
        } else if (bdInput) {
          toast('⚠️ รูปแบบวันเกิด: วว/ดด/พศ (เช่น 05/08/2537)', 'error');
          return false;
        }
      } else {
        f.birthDate = '';
      }
      break;
    case 4:
      f.workSchedule = $('#spw-workSchedule')?.value || '';
      // ⭐ r38r17u: hasBank toggle — ถ้าไม่มีบัญชี → clear bank fields
      if (f.hasBank === false) {
        f.bank = { name: '', accountNumber: '', accountName: '' };
      } else {
        // hasBank = true หรือ undefined (default = มี) → save จาก inputs
        f.bank = {
          name: $('#spw-bank-name')?.value || '',
          accountNumber: $('#spw-bank-account')?.value || '',
          accountName: $('#spw-bank-name-acc')?.value || '',
        };
        // ตั้ง flag ให้ชัด
        if (f.hasBank !== false) f.hasBank = true;
      }
      break;
    case 5:
      f.realMeasurements = {
        bust: parseInt($('#spw-rm-bust')?.value) || null,
        waist: parseInt($('#spw-rm-waist')?.value) || null,
        hip: parseInt($('#spw-rm-hip')?.value) || null,
        height: parseInt($('#spw-rm-height')?.value) || null,
      };
      f.displayMeasurements = {
        bust: parseInt($('#spw-dm-bust')?.value) || null,
        waist: parseInt($('#spw-dm-waist')?.value) || null,
        hip: parseInt($('#spw-dm-hip')?.value) || null,
        height: parseInt($('#spw-dm-height')?.value) || null,
      };
      break;
    case 10:
      // ⭐ r38r17n: Capture exam scores (sliders update form directly, just save date/note)
      f.examScores = f.examScores || {};
      f.examScores.lastTestDate = $('#spw-exam-date')?.value?.trim() || '';
      f.examScores.note = $('#spw-exam-note')?.value?.trim() || '';
      f.highlightsText = $('#spw-highlights-text')?.value?.trim() || '';
      break;
    case 11:
      // ⭐ r38r29cj: จุดเด่นบริการ — capture chips → f.highlights
      f.highlights = Array.from(document.querySelectorAll('#spw-highlight-chips .spw-highlight-chip')).filter(b => b.dataset.on === '1').map(b => b.dataset.hl);
      break;
  }
  return true;
}

// Wire step-specific inputs
function _wireStepInputs(wiz) {
  // ⭐ r38r17i: Auto-format birth date input (พ.ศ.)
  const bdInput = $('#spw-birthDate');
  if (bdInput) {
    bdInput.addEventListener('input', (e) => {
      let v = e.target.value.replace(/\D/g, ''); // digits only
      if (v.length > 8) v = v.slice(0, 8);
      let formatted = v;
      if (v.length > 4) formatted = `${v.slice(0,2)}/${v.slice(2,4)}/${v.slice(4)}`;
      else if (v.length > 2) formatted = `${v.slice(0,2)}/${v.slice(2)}`;
      e.target.value = formatted;
    });
  }
  
  // ⭐ r38r17o: Exam score sliders + number inputs (bidirectional sync, 0-10 step 0.5)
  const clampScore = (v) => {
    if (v === '' || v === null || v === undefined || isNaN(v)) return null;
    let n = parseFloat(v);
    if (n < 0) n = 0;
    if (n > 10) n = 10;
    // Round to nearest 0.5
    n = Math.round(n * 2) / 2;
    return n;
  };
  
  $$('.spw-exam-slider').forEach(slider => {
    slider.addEventListener('input', (e) => {
      const field = e.target.dataset.examField;
      const val = clampScore(e.target.value);
      wiz.form.examScores = wiz.form.examScores || {};
      wiz.form.examScores[field] = val;
      _rerenderStep(wiz);
    });
  });
  
  $$('.spw-exam-num').forEach(input => {
    // Update on change (after blur or Enter) to avoid disrupting typing
    input.addEventListener('change', (e) => {
      const field = e.target.dataset.examField;
      const raw = e.target.value.trim();
      const val = raw === '' ? null : clampScore(raw);
      wiz.form.examScores = wiz.form.examScores || {};
      wiz.form.examScores[field] = val;
      _rerenderStep(wiz);
    });
    // Live sync slider while typing (no rerender, just visual)
    input.addEventListener('input', (e) => {
      const field = e.target.dataset.examField;
      const raw = e.target.value.trim();
      if (raw === '') return;
      const val = clampScore(raw);
      if (val === null) return;
      const slider = document.getElementById(`spw-exam-${field}`);
      if (slider) slider.value = val;
    });
  });
  
  // Single-select chips
  $$('.spw-chip').forEach(btn => {
    btn.onclick = () => {
      const field = btn.dataset.field;
      let value = btn.dataset.value;
      const type = btn.dataset.type;
      if (type === 'bool') value = value === 'true';
      else if (type === 'number') value = parseInt(value);
      // ⭐ r38r17u: hasBank toggle — yes/no → true/false
      if (field === 'hasBank') value = (value === 'yes');
      
      // Set value (support nested path: limits.spray)
      if (field.includes('.')) {
        const [parent, child] = field.split('.');
        wiz.form[parent] = wiz.form[parent] || {};
        wiz.form[parent][child] = value;
      } else {
        wiz.form[field] = value;
      }
      // Re-render the same step
      _rerenderStep(wiz);
    };
  });
  
  // Multi-select chips
  $$('.spw-chip-multi').forEach(btn => {
    btn.onclick = () => {
      const field = btn.dataset.field;
      const value = btn.dataset.value;
      const [parent, child] = field.split('.');
      wiz.form[parent] = wiz.form[parent] || {};
      wiz.form[parent][child] = wiz.form[parent][child] || [];
      const arr = wiz.form[parent][child];
      const idx = arr.indexOf(value);
      if (idx >= 0) arr.splice(idx, 1);
      else arr.push(value);
      _rerenderStep(wiz);
    };
  });
  
  // Body map: side toggle (front/back)
  $$('.bm-side-btn').forEach(btn => {
    btn.onclick = () => {
      wiz._bmSide = btn.dataset.side;
      _rerenderStep(wiz);
    };
  });
  
  // Body map: type toggle
  $$('.bm-type-btn').forEach(btn => {
    btn.onclick = () => {
      wiz._bmType = btn.dataset.type;
      _rerenderStep(wiz);
    };
  });
  
  // Body map: click SVG to add marker
  const svg = $('#bm-svg');
  if (svg) {
    svg.addEventListener('click', (e) => {
      // Ignore if clicked on existing marker
      if (e.target.closest('.bm-marker')) return;
      
      const currentType = wiz._bmType || 'tattoo';
      if (currentType === 'csection') {
        // C-section is a simple yes/no — toggle via the button below
        toast('💡 รอยผ่าคลอดใช้ปุ่ม ✅/❌ ด้านล่าง (ไม่ต้องระบุตำแหน่ง)', 'info', 3000);
        return;
      }
      
      // Convert click position to SVG coordinates
      const pt = svg.createSVGPoint();
      pt.x = e.clientX;
      pt.y = e.clientY;
      const svgPt = pt.matrixTransform(svg.getScreenCTM().inverse());
      const x = Math.round(svgPt.x);
      const y = Math.round(svgPt.y);
      
      // Bounds check (rough body silhouette)
      if (x < 60 || x > 240 || y < 10 || y > 350) {
        toast('💡 กรุณาคลิกบนรูปร่าง', 'info', 2000);
        return;
      }
      
      // Ask for note (optional)
      const note = prompt(`เพิ่ม${currentType === 'tattoo' ? 'รอยสัก' : 'รอยแตลาย'}ที่นี่\n\nหมายเหตุ (optional):`, '');
      if (note === null) return;  // cancelled
      
      const newMarker = {
        id: 'zone_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
        side: wiz._bmSide || 'front',
        x, y,
        type: currentType,
        note: note.trim(),
      };
      
      const fieldKey = currentType === 'tattoo' ? 'tattooZones' : 'stretchMarkZones';
      const flagKey = currentType === 'tattoo' ? 'hasTattoos' : 'hasStretchMarks';
      wiz.form[fieldKey] = wiz.form[fieldKey] || [];
      wiz.form[fieldKey].push(newMarker);
      wiz.form[flagKey] = true;
      
      _rerenderStep(wiz);
    });
  }
  
  // Body map: click marker to edit/delete
  $$('.bm-marker, .bm-marker-edit').forEach(el => {
    el.onclick = (e) => {
      e.stopPropagation();
      const zoneId = el.dataset.zoneId;
      if (!zoneId) return;
      
      const currentType = wiz._bmType || 'tattoo';
      const fieldKey = currentType === 'tattoo' ? 'tattooZones' : 'stretchMarkZones';
      const flagKey = currentType === 'tattoo' ? 'hasTattoos' : 'hasStretchMarks';
      const zones = wiz.form[fieldKey] || [];
      const zone = zones.find(z => z.id === zoneId);
      if (!zone) return;
      
      const action = confirm(`${currentType === 'tattoo' ? '🔵 รอยสัก' : '🟡 รอยแตลาย'}\n` + 
        `ตำแหน่ง: ${zone.side === 'front' ? 'ด้านหน้า' : 'ด้านหลัง'}\n` +
        `หมายเหตุ: ${zone.note || '(ไม่มี)'}\n\n` +
        `กด OK = แก้หมายเหตุ\nกด Cancel = ลบ`);
      
      if (action) {
        // Edit note
        const newNote = prompt('แก้หมายเหตุ:', zone.note || '');
        if (newNote !== null) {
          zone.note = newNote.trim();
          _rerenderStep(wiz);
        }
      } else {
        // Delete
        if (confirm('ลบ marker นี้?')) {
          wiz.form[fieldKey] = zones.filter(z => z.id !== zoneId);
          if (wiz.form[fieldKey].length === 0) wiz.form[flagKey] = false;
          _rerenderStep(wiz);
        }
      }
    };
  });
  
  // Tag input (step 10)
  const tagInput = $('#spw-tag-input');
  if (tagInput) {
    tagInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        const t = tagInput.value.trim();
        if (t && !(wiz.form.tags || []).includes(t)) {
          wiz.form.tags = wiz.form.tags || [];
          wiz.form.tags.push(t);
          tagInput.value = '';
          _rerenderStep(wiz);
        }
      }
    });
    $$('.spw-tag').forEach(el => {
      el.onclick = () => {
        const t = el.dataset.tag;
        wiz.form.tags = (wiz.form.tags || []).filter(x => x !== t);
        _rerenderStep(wiz);
      };
    });
    $$('.spw-tag-suggest').forEach(btn => {
      btn.onclick = () => {
        const t = btn.dataset.tag;
        wiz.form.tags = wiz.form.tags || [];
        wiz.form.tags.push(t);
        _rerenderStep(wiz);
      };
    });
  }
}

// Helper: re-render current step
function _rerenderStep(wiz) {
  // Capture text input values before re-rendering (so they don't get lost)
  _captureStepData(wiz);
  
  const content = (function() {
    switch (wiz.step) {
      case 1: return _step1_chooseStaff(wiz, (state.staff || []).filter(s => s.active !== false && (!getStaffProfile(s.id) || s.id === wiz.staffId)), !!wiz.staffId);
      case 2: return _step2_personal1(wiz);
      case 3: return _step3_personal2(wiz);
      case 4: return _step4_bank(wiz);
      case 5: return _step5_age(wiz);
      case 6: return _step6_body(wiz);
      case 7: return _step7_marks(wiz);
      case 8: return _step8_intimate(wiz);
      case 9: return _step9_limits(wiz);
      case 10: return _step10_exam(wiz);
      case 11: return _step11_finalize(wiz);
    }
  })();
  $('#spw-content').innerHTML = content;
  _wireStepInputs(wiz);
}

// Save wizard form → Firestore
async function _saveWizardProfile(wiz, existingProfile) {
  const f = wiz.form;
  if (!wiz.staffId) {
    toast('⚠️ ยังไม่ได้เลือกพนักงาน', 'error');
    return;
  }
  
  try {
    const data = {
      ...f,
      staffId: wiz.staffId,
      lastEditedAt: serverTimestamp(),
      lastEditedBy: state.user?.name || 'unknown',
    };
    
    if (existingProfile?.id) {
      await updateDoc(doc(db, 'staff_profiles', existingProfile.id), data);
      toast('✅ บันทึกข้อมูลแล้ว', 'success');
    } else {
      data.createdAt = serverTimestamp();
      data.createdBy = state.user?.name || 'unknown';
      data.status = data.status || 'active';
      await addDoc(collection(db, 'staff_profiles'), data);
      toast('✅ เพิ่มข้อมูลใหม่แล้ว', 'success');
    }
    
    logStaffProfileAudit('edit', existingProfile?.id, wiz.staffId, ['all']);
    closeModal();
    renderStaffProfilesView();
    
    // ⭐ r38r25c: ถ้าเป็นการเพิ่ม profile ใหม่ (existingProfile===null) → migration guide
    if (!existingProfile?.id) {
      try {
        const staff = state.staff.find(s => s.id === wiz.staffId);
        if (staff) {
          const mig = addMigrationTask('add', staff);
          if (mig) {
            setTimeout(() => openMigrationGuideModal(mig.id), 600);
          }
        }
      } catch (e) { console.error('Migration task failed', e); }
    }
  } catch (e) {
    toast('❌ บันทึกล้มเหลว: ' + e.message, 'error');
  }
}

// ⭐ r36bl: History view — Snapshot list (closed months)
// ════════════════════════════════════════════════════════════════
// ⭐ r38r18p: Maintenance Tools — Owner only
//   ปัจจุบัน: ซ่อม Walk-in date ที่ถูกเขียนทับด้วยการ edit
// ════════════════════════════════════════════════════════════════
const maintenanceState = {
  selectedIds: new Set(),  // walkin IDs ที่เลือก
  filterMode: 'suspicious', // 'suspicious' | 'all' | 'edited'
  searchShop: 'all',
};
window.maintenanceState = maintenanceState;

function renderOwnerMaintenance() {
  // หา walkin ที่ "น่าจะ" date ผิด
  //   Heuristic 1: editedAt มีค่า AND startTime >= 22:00 AND date == ymd(editedAt)
  //                → น่าจะมาจาก rounded edit ที่ overwrite date
  //   Heuristic 2: createdAt มีค่า AND date == ymd(createdAt) AND startTime >= 22:00
  //                → walkin ที่ start 22:00+ แต่ date ถูก set จาก createdAt วันถัดไป
  const walkins = state.walkins || [];
  
  const allWalkinsAnalyzed = walkins.map(w => {
    if (!w.date || !w.startTime) return null;
    
    let suggestedDate = null;
    let reason = null;
    let suspicious = false;
    
    const startHour = parseInt(w.startTime.split(':')[0], 10);
    
    // Suspicious case: startTime 22:00-23:59 BUT date จาก createdAt ที่อาจเด้งวันถัดไป
    // Heuristic: ถ้า createdAt มี hour 00:00-06:59 (early morning) AND date == ymd(createdAt)
    //            AND startTime 22:00-23:59 → น่าจะของคืนก่อน
    if (w.createdAt) {
      try {
        const createdMs = w.createdAt.seconds ? w.createdAt.seconds * 1000 : (w.createdAt._seconds ? w.createdAt._seconds*1000 : null);
        if (createdMs) {
          const createdDate = new Date(createdMs);
          const createdHour = createdDate.getHours();
          const createdDateStr = ymd(createdDate);
          
          // เคสที่ "createdAt อยู่ในคืนถัดไปตอน 00-06" + "startTime อยู่ก่อน 23:59 ของวันก่อน"
          if (createdHour >= 0 && createdHour <= 6 && createdDateStr === w.date && startHour >= 20) {
            // วันก่อนหน้า
            const prev = parseYmd(w.date);
            prev.setDate(prev.getDate() - 1);
            suggestedDate = ymd(prev);
            reason = `created ${createdHour}:00 น. + เริ่ม ${w.startTime} น. — น่าจะเป็นรอบของวันก่อน`;
            suspicious = true;
          }
        }
      } catch (e) {}
    }
    
    // เคสที่ edited + ถูก overwrite ไปวันถัดไป (fix r38r18o แต่ data เก่ายังผิด)
    if (!suggestedDate && w.editedAt) {
      try {
        const editedMs = w.editedAt.seconds ? w.editedAt.seconds * 1000 : (w.editedAt._seconds ? w.editedAt._seconds*1000 : null);
        if (editedMs) {
          const editedDate = new Date(editedMs);
          const editedHour = editedDate.getHours();
          const editedDateStr = ymd(editedDate);
          
          if (editedHour >= 0 && editedHour <= 6 && editedDateStr === w.date && startHour >= 20) {
            const prev = parseYmd(w.date);
            prev.setDate(prev.getDate() - 1);
            suggestedDate = ymd(prev);
            reason = `edited ${editedHour}:00 น. + เริ่ม ${w.startTime} น. — น่าจะของวันก่อน`;
            suspicious = true;
          }
        }
      } catch (e) {}
    }
    
    return { w, suggestedDate, reason, suspicious };
  }).filter(Boolean);
  
  // Filter ตาม mode
  let displayList;
  if (maintenanceState.filterMode === 'suspicious') {
    displayList = allWalkinsAnalyzed.filter(x => x.suspicious);
  } else if (maintenanceState.filterMode === 'edited') {
    displayList = allWalkinsAnalyzed.filter(x => x.w.editedAt);
  } else {
    displayList = allWalkinsAnalyzed;
  }
  
  // Shop filter
  if (maintenanceState.searchShop !== 'all') {
    displayList = displayList.filter(x => x.w.shop === maintenanceState.searchShop);
  }
  
  // Sort: น่าสงสัยขึ้นก่อน → recent date
  displayList.sort((a, b) => {
    if (a.suspicious !== b.suspicious) return b.suspicious ? 1 : -1;
    return (b.w.date || '').localeCompare(a.w.date || '');
  });
  
  const totalSuspicious = allWalkinsAnalyzed.filter(x => x.suspicious).length;
  
  return `
    <div style="background:var(--bg-elev); padding:14px; border-radius:12px; margin-bottom:14px;">
      <h3 style="margin:0 0 6px; font-size:15px;">🔧 ซ่อม Walk-in date</h3>
      <div style="font-size:11px; color:var(--text-soft); line-height:1.5;">
        ตรวจหา walkin ที่อาจมี date ผิด (เช่น ลงด่วนตอน 23:50 → เติมข้อมูล 00:30 → date เด้งไปวันถัดไป)<br>
        <b>Fix r38r18o แล้ว</b> — แต่ data เก่าที่ผิดอยู่ ใช้ tool นี้ย้ายกลับวันที่ถูกต้อง
      </div>
    </div>
    
    <!-- Filters -->
    <div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:12px;">
      <button class="maint-filter-btn ${maintenanceState.filterMode === 'suspicious' ? 'active' : ''}" data-mode="suspicious" 
        style="padding:7px 14px; border:1.5px solid ${maintenanceState.filterMode === 'suspicious' ? '#dc2626' : 'var(--line)'}; background:${maintenanceState.filterMode === 'suspicious' ? '#fee2e2' : '#fff'}; color:${maintenanceState.filterMode === 'suspicious' ? '#991b1b' : 'var(--text)'}; border-radius:8px; font-size:12px; font-weight:600; cursor:pointer;">
        🚨 น่าสงสัย (${totalSuspicious})
      </button>
      <button class="maint-filter-btn ${maintenanceState.filterMode === 'edited' ? 'active' : ''}" data-mode="edited"
        style="padding:7px 14px; border:1.5px solid ${maintenanceState.filterMode === 'edited' ? '#7c3aed' : 'var(--line)'}; background:${maintenanceState.filterMode === 'edited' ? '#ede9fe' : '#fff'}; color:${maintenanceState.filterMode === 'edited' ? '#5b21b6' : 'var(--text)'}; border-radius:8px; font-size:12px; font-weight:600; cursor:pointer;">
        ✏️ ที่เคยแก้
      </button>
      <button class="maint-filter-btn ${maintenanceState.filterMode === 'all' ? 'active' : ''}" data-mode="all"
        style="padding:7px 14px; border:1.5px solid ${maintenanceState.filterMode === 'all' ? '#3b82f6' : 'var(--line)'}; background:${maintenanceState.filterMode === 'all' ? '#dbeafe' : '#fff'}; color:${maintenanceState.filterMode === 'all' ? '#1e40af' : 'var(--text)'}; border-radius:8px; font-size:12px; font-weight:600; cursor:pointer;">
        📋 ทั้งหมด
      </button>
      
      <div style="flex:1;"></div>
      
      <select id="maint-shop" style="padding:7px 12px; border:1px solid var(--line); border-radius:8px; font-size:12px;">
        <option value="all" ${maintenanceState.searchShop === 'all' ? 'selected' : ''}>🏪 ทั้ง 2 ร้าน</option>
        <option value="geisha" ${maintenanceState.searchShop === 'geisha' ? 'selected' : ''}>🌸 Geisha</option>
        <option value="yoshi" ${maintenanceState.searchShop === 'yoshi' ? 'selected' : ''}>🎌 Yoshi</option>
      </select>
    </div>
    
    <!-- Action buttons -->
    ${maintenanceState.selectedIds.size > 0 ? `
      <div style="background:#dcfce7; border:1.5px solid #16a34a; padding:10px 14px; border-radius:10px; margin-bottom:12px; display:flex; align-items:center; gap:10px;">
        <span style="font-size:12px; color:#15803d; font-weight:600;">เลือก ${maintenanceState.selectedIds.size} รายการ</span>
        <div style="flex:1;"></div>
        <button id="maint-bulk-fix" style="padding:7px 14px; background:#16a34a; color:#fff; border:none; border-radius:7px; font-size:12px; font-weight:600; cursor:pointer;">
          ✅ ย้ายไปวันที่แนะนำ
        </button>
        <button id="maint-clear-sel" style="padding:7px 14px; background:#fff; color:#374151; border:1px solid var(--line); border-radius:7px; font-size:12px; font-weight:600; cursor:pointer;">
          ✗ ยกเลิก
        </button>
      </div>
    ` : ''}
    
    <!-- Table -->
    ${displayList.length === 0 ? `
      <div style="text-align:center; padding:40px 20px; color:var(--text-soft);">
        <div style="font-size:36px; margin-bottom:8px;">✨</div>
        <div style="font-size:14px;">ไม่พบรายการที่ต้องซ่อม</div>
      </div>
    ` : `
      <div style="background:#fff; border:1px solid var(--line); border-radius:10px; overflow:auto;">
        <table style="width:100%; border-collapse:collapse; font-size:12px; min-width:800px;">
          <thead style="background:#f9fafb;">
            <tr>
              <th style="padding:8px; text-align:center; width:32px;">
                <input type="checkbox" id="maint-check-all" ${displayList.every(x => maintenanceState.selectedIds.has(x.w.id)) && displayList.length > 0 ? 'checked' : ''}>
              </th>
              <th style="padding:8px; text-align:left; font-size:11px; color:#6b7280;">ลูกค้า / พนง.</th>
              <th style="padding:8px; text-align:center; font-size:11px; color:#6b7280;">ร้าน</th>
              <th style="padding:8px; text-align:center; font-size:11px; color:#6b7280;">เวลา</th>
              <th style="padding:8px; text-align:center; font-size:11px; color:#6b7280;">วันที่ปัจจุบัน</th>
              <th style="padding:8px; text-align:center; font-size:11px; color:#6b7280;">→ แนะนำ</th>
              <th style="padding:8px; text-align:left; font-size:11px; color:#6b7280;">เหตุผล</th>
              <th style="padding:8px; text-align:center; font-size:11px; color:#6b7280;">Action</th>
            </tr>
          </thead>
          <tbody>
            ${displayList.slice(0, 200).map(x => {
              const w = x.w;
              const staff = (state.staff || []).find(s => s.id === w.staffId);
              const staffName = staff ? (staff.nickname || staff.shortCode || staff.nameEn) : '—';
              const isSelected = maintenanceState.selectedIds.has(w.id);
              return `
                <tr style="border-bottom:0.5px solid #f3f4f6; ${isSelected ? 'background:#f0fdf4;' : ''}">
                  <td style="padding:8px; text-align:center;">
                    ${x.suggestedDate ? `<input type="checkbox" class="maint-row-check" data-wid="${w.id}" ${isSelected ? 'checked' : ''}>` : ''}
                  </td>
                  <td style="padding:8px;">
                    <div style="font-weight:600; color:#1f2937;">${escapeHtml(w.customerName || 'Walk-in')}</div>
                    <div style="font-size:10px; color:var(--text-soft);">${escapeHtml(staffName)}</div>
                  </td>
                  <td style="padding:8px; text-align:center;">
                    <span style="font-size:10px; padding:2px 7px; border-radius:999px; background:${w.shop === 'yoshi' ? '#fef3c7' : '#fce7f3'}; color:${w.shop === 'yoshi' ? '#92400e' : '#be185d'}; font-weight:600;">${w.shop === 'yoshi' ? '🎌 Yoshi' : '🌸 Geisha'}</span>
                  </td>
                  <td style="padding:8px; text-align:center; font-family:monospace; font-size:11px;">${w.startTime}-${w.endTime || ''}</td>
                  <td style="padding:8px; text-align:center; font-family:monospace; font-size:11px;">
                    <span style="${x.suspicious ? 'color:#dc2626; font-weight:700;' : ''}">${w.date}</span>
                  </td>
                  <td style="padding:8px; text-align:center; font-family:monospace; font-size:11px;">
                    ${x.suggestedDate ? `
                      <span style="color:#15803d; font-weight:700;">${x.suggestedDate}</span>
                    ` : '<span style="color:#9ca3af;">—</span>'}
                  </td>
                  <td style="padding:8px; font-size:10px; color:var(--text-soft);">${x.reason || ''}</td>
                  <td style="padding:8px; text-align:center;">
                    <button class="maint-single-fix" data-wid="${w.id}" style="padding:4px 10px; background:#fff; color:#7c3aed; border:1px solid #7c3aed; border-radius:6px; font-size:11px; font-weight:600; cursor:pointer;">
                      🛠 เลือก date
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
        ${displayList.length > 200 ? `<div style="padding:10px; text-align:center; font-size:11px; color:var(--text-soft); border-top:0.5px solid var(--line);">แสดง 200 จาก ${displayList.length} รายการ — ใช้ filter เพื่อจำกัด</div>` : ''}
      </div>
    `}
    
    <div style="margin-top:14px; padding:10px 14px; background:#fef9c3; border:1px solid #facc15; border-radius:10px; font-size:11px; color:#713f12;">
      💡 <b>Tips:</b> "น่าสงสัย" = walkin เริ่ม 20:00+ AND created/edited ตอน 00:00-06:00 ของวันถัดไป → น่าจะคืนก่อน
    </div>
  `;
}

// Wire maintenance tab events
function wireMaintenanceEvents() {
  // Filter buttons
  $$('.maint-filter-btn').forEach(b => {
    b.onclick = () => {
      maintenanceState.filterMode = b.dataset.mode;
      maintenanceState.selectedIds.clear();
      renderOwnerDashboard();
    };
  });
  
  // Shop filter
  $('#maint-shop')?.addEventListener('change', (e) => {
    maintenanceState.searchShop = e.target.value;
    maintenanceState.selectedIds.clear();
    renderOwnerDashboard();
  });
  
  // Check-all
  $('#maint-check-all')?.addEventListener('change', (e) => {
    const checked = e.target.checked;
    $$('.maint-row-check').forEach(c => {
      c.checked = checked;
      const wid = c.dataset.wid;
      if (checked) maintenanceState.selectedIds.add(wid);
      else maintenanceState.selectedIds.delete(wid);
    });
    renderOwnerDashboard();
  });
  
  // Row check
  $$('.maint-row-check').forEach(c => {
    c.onchange = () => {
      const wid = c.dataset.wid;
      if (c.checked) maintenanceState.selectedIds.add(wid);
      else maintenanceState.selectedIds.delete(wid);
      renderOwnerDashboard();
    };
  });
  
  // Bulk fix
  $('#maint-bulk-fix')?.addEventListener('click', async () => {
    const ids = Array.from(maintenanceState.selectedIds);
    if (ids.length === 0) return;
    if (!confirm(`ย้าย ${ids.length} รายการไปวันที่แนะนำ?\n\n* ทำซ้ำได้ — ถ้าผิด ใช้ "เลือก date" ทีละรายการ`)) return;
    
    let success = 0, failed = 0;
    for (const wid of ids) {
      const w = (state.walkins || []).find(x => x.id === wid);
      if (!w) { failed++; continue; }
      // คำนวณ suggested date อีกครั้ง (defensive)
      const startHour = parseInt((w.startTime || '00:00').split(':')[0], 10);
      let newDate = null;
      try {
        const ts = w.createdAt?.seconds || w.editedAt?.seconds;
        if (ts && startHour >= 20) {
          const tsDate = new Date(ts * 1000);
          if (tsDate.getHours() >= 0 && tsDate.getHours() <= 6 && ymd(tsDate) === w.date) {
            const prev = parseYmd(w.date);
            prev.setDate(prev.getDate() - 1);
            newDate = ymd(prev);
          }
        }
      } catch (e) {}
      
      if (!newDate) { failed++; continue; }
      
      try {
        await updateDoc(doc(db, 'walkins', wid), {
          date: newDate,
          dateFixedFromMaintenance: true,
          dateFixedFrom: w.date,
          dateFixedAt: serverTimestamp(),
          dateFixedBy: state.user?.name || 'owner',
        });
        // Audit log
        try {
          await addDoc(collection(db, 'audit_logs'), {
            action: 'walkin_date_fixed',
            target: 'walkins', targetId: wid,
            data: { oldDate: w.date, newDate, customer: w.customerName, startTime: w.startTime, shop: w.shop },
            user: state.user?.name || 'unknown',
            timestamp: serverTimestamp(),
          });
        } catch (e) {}
        success++;
      } catch (e) {
        console.error('Fix failed:', e);
        failed++;
      }
    }
    
    maintenanceState.selectedIds.clear();
    toast(`✓ ย้าย ${success}/${ids.length} รายการสำเร็จ${failed > 0 ? ` (พลาด ${failed})` : ''}`, success === ids.length ? 'success' : 'info');
    setTimeout(() => renderOwnerDashboard(), 500);
  });
  
  // Clear selection
  $('#maint-clear-sel')?.addEventListener('click', () => {
    maintenanceState.selectedIds.clear();
    renderOwnerDashboard();
  });
  
  // Single fix
  $$('.maint-single-fix').forEach(b => {
    b.onclick = () => {
      const wid = b.dataset.wid;
      const w = (state.walkins || []).find(x => x.id === wid);
      if (!w) return;
      openMaintenanceDateModal(w);
    };
  });
}
window.wireMaintenanceEvents = wireMaintenanceEvents;

// Modal: เลือก date ทีละรายการ
function openMaintenanceDateModal(w) {
  const currentDate = w.date || '';
  const customerName = w.customerName || 'Walk-in';
  const staff = (state.staff || []).find(s => s.id === w.staffId);
  const staffName = staff ? (staff.nickname || staff.shortCode || staff.nameEn) : '—';
  
  // ปกติแนะนำวันก่อนหน้า
  const prev = parseYmd(currentDate);
  prev.setDate(prev.getDate() - 1);
  const prevDate = ymd(prev);
  
  openModal(`
    <div class="modal" style="max-width:420px;">
      <div class="modal-header">
        <h3 style="margin:0; font-size:15px;">🛠 ย้าย Walk-in ไปวันที่ใหม่</h3>
        <button class="x-btn">×</button>
      </div>
      <div class="modal-body" style="padding:16px;">
        <div style="background:#f9fafb; padding:10px; border-radius:8px; margin-bottom:14px; font-size:12px;">
          <div><b>${escapeHtml(customerName)}</b> · ${escapeHtml(staffName)}</div>
          <div style="color:var(--text-soft); margin-top:3px;">${w.shop === 'yoshi' ? '🎌 Yoshi' : '🌸 Geisha'} · ${w.startTime}-${w.endTime || ''}</div>
        </div>
        
        <div style="margin-bottom:10px;">
          <label style="display:block; font-size:11px; color:var(--text-soft); margin-bottom:5px;">ปัจจุบัน:</label>
          <div style="font-family:monospace; font-size:14px; color:#dc2626; font-weight:700;">${currentDate}</div>
        </div>
        
        <div style="margin-bottom:14px;">
          <label style="display:block; font-size:11px; color:var(--text-soft); margin-bottom:5px;">ย้ายไปวันที่:</label>
          <input type="text" id="maint-new-date" value="${prevDate}" 
            style="width:100%; padding:10px 12px; border:1.5px solid var(--line); border-radius:8px; font-family:monospace; font-size:14px; text-align:center;">
          <div style="font-size:10px; color:var(--text-soft); margin-top:4px;">รูปแบบ YYYY-MM-DD เช่น 2026-05-20</div>
        </div>
        
        <div style="display:flex; gap:8px;">
          <button id="maint-modal-suggest" style="flex:1; padding:8px; background:#fef3c7; color:#92400e; border:1px solid #fbbf24; border-radius:7px; font-size:12px; font-weight:600; cursor:pointer;">
            📍 วันก่อนหน้า (${prevDate})
          </button>
        </div>
        
        <div style="display:flex; gap:8px; margin-top:14px;">
          <button id="maint-modal-cancel" style="flex:1; padding:10px; background:#fff; color:#374151; border:1px solid var(--line); border-radius:8px; font-weight:600; cursor:pointer;">ยกเลิก</button>
          <button id="maint-modal-save" style="flex:1; padding:10px; background:#7c3aed; color:#fff; border:none; border-radius:8px; font-weight:600; cursor:pointer;">💾 ย้ายเลย</button>
        </div>
      </div>
    </div>
  `);
  
  $('#maint-modal-suggest').onclick = () => { $('#maint-new-date').value = prevDate; };
  $('#maint-modal-cancel').onclick = () => closeModal();
  $('#maint-modal-save').onclick = async () => {
    const newDate = $('#maint-new-date').value.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(newDate)) return toast('❌ รูปแบบไม่ถูก (YYYY-MM-DD)');
    if (newDate === currentDate) return toast('❌ วันที่เหมือนเดิม');
    if (!confirm(`ย้าย walkin จาก ${currentDate} → ${newDate}?`)) return;
    
    try {
      await updateDoc(doc(db, 'walkins', w.id), {
        date: newDate,
        dateFixedFromMaintenance: true,
        dateFixedFrom: currentDate,
        dateFixedAt: serverTimestamp(),
        dateFixedBy: state.user?.name || 'owner',
      });
      try {
        await addDoc(collection(db, 'audit_logs'), {
          action: 'walkin_date_fixed',
          target: 'walkins', targetId: w.id,
          data: { oldDate: currentDate, newDate, customer: customerName, startTime: w.startTime, shop: w.shop },
          user: state.user?.name || 'unknown',
          timestamp: serverTimestamp(),
        });
      } catch (e) {}
      toast(`✓ ย้ายไป ${newDate} แล้ว`);
      closeModal();
      setTimeout(() => renderOwnerDashboard(), 300);
    } catch (e) {
      console.error(e);
      toast('❌ ย้ายไม่สำเร็จ: ' + e.message);
    }
  };
}
window.openMaintenanceDateModal = openMaintenanceDateModal;

function renderOwnerHistory(range) {
  const allSnapshots = (state.balanceSheets || [])
    .filter(b => ownerState.shopFilter === 'both' || b.shop === ownerState.shopFilter || b.shop === 'both')
    .sort((a, b) => (b.ym || '').localeCompare(a.ym || ''));
  
  // Compute totals across history
  let totalProfit = 0, totalRevenue = 0, totalRounds = 0;
  allSnapshots.forEach(b => {
    totalProfit += (b.profit || 0);
    totalRevenue += (b.revenue || 0);
    totalRounds += (b.rounds || 0);
  });
  
  return `
    <div style="background:linear-gradient(135deg, #2a1f0f, #1a1408); border:1.5px solid var(--gold); border-radius:16px; padding:20px; margin-bottom:16px; color:#fff;">
      <div style="font-size:13px; opacity:0.8;">📂 ประวัติงบดุล (ปิดบัญชีแล้ว)</div>
      <div style="font-size:24px; font-weight:700; color:var(--gold-light, #e8c89d); margin-top:6px;">${allSnapshots.length} เดือน</div>
      <div style="font-size:13px; opacity:0.9; margin-top:6px;">💰 รวมรายรับ ${fmtMoneyFull(totalRevenue)} · 💎 กำไรรวม ${fmtMoneyFull(totalProfit)} · ${totalRounds} รอบ</div>
    </div>
    
    ${allSnapshots.length === 0 ? `
      <div style="background:var(--bg-elev); border:1px dashed var(--line); border-radius:12px; padding:30px; text-align:center;">
        <div style="font-size:32px; margin-bottom:8px;">📂</div>
        <div style="color:var(--text-soft); font-size:14px;">ยังไม่มีประวัติงบดุล</div>
        <div style="color:var(--text-mute); font-size:12px; margin-top:4px;">เมื่อปิดบัญชีรายเดือนแล้ว — จะปรากฏที่นี่</div>
      </div>
    ` : `
      ${(() => {
        // ⭐ r36bl: Yearly grouping
        const byYear = {};
        allSnapshots.forEach(b => {
          const y = (b.ym || '').slice(0, 4);
          if (!byYear[y]) byYear[y] = { revenue: 0, profit: 0, rounds: 0, count: 0 };
          byYear[y].revenue += (b.revenue || 0);
          byYear[y].profit += (b.profit || 0);
          byYear[y].rounds += (b.rounds || 0);
          byYear[y].count++;
        });
        if (Object.keys(byYear).length <= 1) return '';
        return `
          <div style="background:var(--bg-elev); border:1px solid var(--line); border-radius:14px; padding:16px; margin-bottom:14px;">
            <h3 style="font-size:14px; margin-bottom:12px;">📆 สรุปรายปี</h3>
            ${Object.entries(byYear).sort((a, b) => b[0].localeCompare(a[0])).map(([y, d]) => {
              const profitColor = d.profit >= 0 ? 'var(--green)' : 'var(--red)';
              return `
                <div style="display:flex; align-items:center; gap:12px; padding:10px 0; border-bottom:1px solid var(--line);">
                  <div style="font-size:22px;">📅</div>
                  <div style="flex:1;">
                    <div style="font-weight:700;">ปี ${parseInt(y) + 543}</div>
                    <div style="font-size:11px; color:var(--text-mute);">${d.count} เดือน · ${d.rounds} รอบ</div>
                  </div>
                  <div style="text-align:right;">
                    <div style="font-weight:700; color:${profitColor};">${fmtMoneyFull(d.profit)}</div>
                    <div style="font-size:10px; color:var(--text-mute);">${fmtMoneyFull(d.revenue)} รายรับ</div>
                  </div>
                </div>
              `;
            }).join('')}
          </div>
        `;
      })()}
      
      <div style="background:var(--bg-elev); border:1px solid var(--line); border-radius:14px; padding:16px; margin-bottom:14px;">
        <h3 style="font-size:14px; margin-bottom:12px;">📋 รายการเดือน</h3>
        ${allSnapshots.map(b => {
          const shopIcon = b.shop === 'geisha' ? '🌸' : b.shop === 'yoshi' ? '🎌' : '💎';
          const profitColor = b.profit >= 0 ? 'var(--green)' : 'var(--red)';
          return `
            <div class="history-row" data-id="${b.id}" style="display:flex; align-items:center; gap:12px; padding:12px 0; border-bottom:1px solid var(--line); cursor:pointer;">
              <div style="font-size:24px;">${shopIcon}</div>
              <div style="flex:1;">
                <div style="font-weight:600;">${b.ym || '?'}</div>
                <div style="font-size:11px; color:var(--text-mute);">${b.rounds || 0} รอบ · ${fmtMoneyFull(b.revenue || 0)}</div>
              </div>
              <div style="text-align:right;">
                <div style="font-weight:700; color:${profitColor}; font-size:15px;">${fmtMoneyFull(b.profit || 0)}</div>
                <div style="font-size:10px; color:var(--text-mute);">กำไรสุทธิ</div>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `}
    
    <!-- ⭐ r36bl: Import historical data -->
    <button class="btn" id="import-historical-btn" style="width:100%; padding:12px; background:var(--bg-elev); border:1px solid var(--gold); border-radius:10px; color:var(--gold); font-weight:600; cursor:pointer; margin-bottom:8px;">
      📥 นำเข้าข้อมูลย้อนหลัง (จาก Excel)
    </button>
    ${allSnapshots.length >= 2 ? `
    <button class="btn" id="compare-months-btn" style="width:100%; padding:12px; background:var(--bg-elev); border:1px solid var(--line); border-radius:10px; color:var(--text); font-weight:600; cursor:pointer; margin-bottom:8px;">
      📊 เปรียบเทียบ 2 เดือน
    </button>
    ` : ''}
    ${allSnapshots.length > 0 ? `
    <button class="btn" id="export-history-btn" style="width:100%; padding:12px; background:var(--bg-elev); border:1px solid var(--line); border-radius:10px; color:var(--text); font-weight:600; cursor:pointer; margin-bottom:8px;">
      📄 Export ประวัติเป็น CSV
    </button>
    ` : ''}
    <button class="btn" id="backup-all-btn" style="width:100%; padding:12px; background:var(--bg-elev); border:1px solid var(--line); border-radius:10px; color:var(--text-soft); font-weight:600; cursor:pointer;">
      💾 Backup ข้อมูลทั้งหมด (JSON)
    </button>
  `;
}

