    const cpl = rptOfDate.filter(r => r.type === 'couple_invite' && (r.shop === shop || r.shop === 'both'))
      .sort((x, yv) => (x.timestamp?.seconds || 0) - (yv.timestamp?.seconds || 0));
    _blockTitle(55, 58, '💑 ลงบันทึกคู่', 'BE185D');
