// ⭐ r38r26w Phase 1: Bulk PIN setup — shared function ใช้จากทั้งหน้า "💁 พนักงาน" + "📁 ข้อมูลพนง."
// ⭐ r38r29ej: รหัสแอปพนักงาน 6 หลัก (เข้า PR Staff app) — สุ่มให้คนที่ยังไม่มี + ตารางรหัสให้แจก
window.runBulkAppPinSetup = async function() {
  if (state.user?.role !== 'owner') { toast('❌ เฉพาะ Owner', 'error'); return; }
  const active = (state.staff || []).filter(s => !(typeof isStaffResigned === 'function' && isStaffResigned(s)));
  const missing = active.filter(s => !s.appPin);
  if (!confirm(`📱 รหัสแอปพนักงาน (6 หลัก)\n\n• พนง.ทำงานอยู่: ${active.length} คน\n• ยังไม่มีรหัส: ${missing.length} คน → สุ่มให้ใหม่\n• คนที่มีแล้ว: ไม่เปลี่ยน\n\nดำเนินการเลย?`)) return;
  setLoading(true);
  let done = 0;
  for (const s of missing) {
    const pin = String(Math.floor(Math.random() * 900000) + 100000);
    try {
      await updateDoc(doc(db, 'staff', s.id), { appPin: pin });
      s.appPin = pin;
      done++;
    } catch (e) { console.error('appPin fail', s.id, e); }
  }
  setLoading(false);
  const rows = active
    .sort((a, b) => String(a.nameEn || a.nickname || '').localeCompare(String(b.nameEn || b.nickname || ''), 'en'))
    .map(s => `<tr><td style="padding:6px 10px; border-bottom:1px solid #f3e8ee;">${escapeHtml(s.nameEn || s.nickname || s.name || '?')}</td><td style="padding:6px 10px; border-bottom:1px solid #f3e8ee; font-family:monospace; font-size:16px; font-weight:700; letter-spacing:2px; color:#9d174d;">${s.appPin || '—'}</td></tr>`)
    .join('');
  const copyText = active.map(s => `${s.nameEn || s.nickname || '?'} : ${s.appPin || '-'}`).join('\n');
  const wrapHtml = `
    <div id="apppin-modal" style="position:fixed; inset:0; background:rgba(0,0,0,0.5); z-index:9999; display:flex; align-items:center; justify-content:center; padding:14px;">
      <div style="background:#fff; border-radius:12px; max-width:380px; width:100%; max-height:88vh; display:flex; flex-direction:column;">
        <div style="padding:14px 16px; border-bottom:1.5px solid #fce7f3;">
          <h3 style="margin:0; font-size:16px;">📱 รหัสแอปพนักงาน (สุ่มใหม่ ${done} คน)</h3>
          <div style="font-size:12px; color:#6b7280;">ใช้เข้า PR Staff app (staff.html) · แจกพนง.รายคน</div>
        </div>
        <div style="flex:1; overflow-y:auto; padding:8px 6px;">
          <table style="width:100%; font-size:14px; border-collapse:collapse;"><thead><tr><th style="text-align:left; padding:6px 10px;">ชื่อ</th><th style="text-align:left; padding:6px 10px;">รหัส</th></tr></thead><tbody>${rows}</tbody></table>
        </div>
        <div style="padding:12px 16px; border-top:1.5px solid #fce7f3; display:flex; gap:8px;">
          <button id="apppin-copy" style="flex:1; padding:11px; background:#fdf2f8; color:#9d174d; border:1.5px solid #f9a8d4; border-radius:8px; font-weight:700;">📋 คัดลอกทั้งหมด</button>
          <button id="apppin-close" style="flex:1; padding:11px; background:#f3f4f6; color:#374151; border:none; border-radius:8px; font-weight:700;">ปิด</button>
        </div>
      </div>
    </div>`;
  const wrap = document.createElement('div');
  wrap.innerHTML = wrapHtml;
  document.body.appendChild(wrap);
  wrap.querySelector('#apppin-close').onclick = () => document.body.removeChild(wrap);
  wrap.querySelector('#apppin-copy').onclick = async () => {
    try { await navigator.clipboard.writeText(copyText); toast('📋 คัดลอกแล้ว', 'success'); } catch (e) { prompt('คัดลอกด้วยมือ:', copyText); }
  };
  try {
    await addDoc(collection(db, 'audit_logs'), { action: 'staff_apppin_bulk_setup', count: done, createdAt: serverTimestamp(), createdBy: state.user?.email || 'owner' });
  } catch (e) {}
};

window.runBulkPinSetup = async function() {
  const missingPin = state.staff.filter(s => !s.pin && s.active !== false);
  if (missingPin.length === 0) {
    toast('✅ พนง.ทุกคนตั้ง PIN ครบแล้ว', 'success');
    return;
  }
  const proceed = confirm(`พบ ${missingPin.length} พนง.ที่ยังไม่ตั้ง PIN — สุ่ม PIN ให้อัตโนมัติ?\n\n(จะแสดง PIN ที่สุ่มได้ใน list หลังเสร็จ — ให้บันทึก/แชร์กับพนง.)`);
  if (!proceed) return;
  
  const results = [];
  for (const s of missingPin) {
    const newPin = String(Math.floor(Math.random() * 9000) + 1000);
    try {
      await updateDoc(doc(db, 'staff', s.id), { pin: newPin });
      results.push({ name: s.nickname || s.shortCode, pin: newPin, ok: true });
    } catch (e) {
      results.push({ name: s.nickname || s.shortCode, ok: false, err: e.message });
    }
  }
  
  // Show results modal
  const successList = results.filter(r => r.ok);
  const failList = results.filter(r => !r.ok);
  
  const resultHtml = `
    <div class="modal" style="max-width:480px;">
      <div style="padding:14px 16px; border-bottom:1px solid var(--line); background:#f0fdf4;">
        <h3 style="margin:0; font-size:17px; color:#15803d;">
          🔑 สุ่ม PIN สำเร็จ ${successList.length}/${results.length}
        </h3>
        <div style="font-size:11px; color:#166534; margin-top:4px;">
          ⚠️ บันทึก/แชร์ PIN ให้พนง.ทันที — ไม่แสดงอีก
        </div>
      </div>
      <div style="padding:14px; max-height:60vh; overflow-y:auto;">
        ${successList.map(r => `
          <div style="display:flex; justify-content:space-between; padding:8px 12px; margin-bottom:5px; background:#f8fafc; border:1px solid var(--line); border-radius:8px;">
            <span style="font-weight:600;">${escapeHtml(r.name)}</span>
            <span class="mono" style="font-size:18px; font-weight:800; letter-spacing:4px; color:#16a34a;">${r.pin}</span>
          </div>
        `).join('')}
        ${failList.length > 0 ? `
          <div style="margin-top:10px; padding:10px; background:#fef2f2; border:1px solid #fca5a5; border-radius:8px; font-size:12px; color:#991b1b;">
            <strong>ล้มเหลว ${failList.length} ราย:</strong><br>
            ${failList.map(r => `• ${escapeHtml(r.name)}: ${escapeHtml(r.err || '?')}`).join('<br>')}
          </div>
        ` : ''}
      </div>
      <div style="padding:10px 14px 14px; border-top:1px solid var(--line);">
        <button class="x-btn" style="
          width:100%; padding:11px; background:var(--accent); border:none; color:#fff;
          border-radius:8px; cursor:pointer; font-size:13px; font-weight:700;
        ">✓ บันทึกแล้ว</button>
      </div>
    </div>
  `;
  openModal(resultHtml);
};

