function openFreebieEditor(freebieId) {
  if (!state.user || state.user.role !== 'owner') {
    toast('เฉพาะ Owner ใช้งานได้', 'error');
    return;
  }
  const f = freebieId ? state.freebies.find(x => x.id === freebieId) : null;
  const editing = !!f;
  
  openModal(`
    <div class="modal">
      <div class="modal-head"><h3>${editing ? 'แก้ไข' : '+ เพิ่ม'}ของแถม</h3><button class="x-btn">×</button></div>
      <div class="modal-body">
        <div class="field">
          <label class="field-label">ชื่อของแถม <span style="color:#ef4444;">*</span></label>
          <input type="text" id="fb-name" value="${escapeHtml(f?.name || '')}" placeholder="เช่น แถมนวดน้ำมันฟรี" style="width:100%; padding:10px; border-radius:8px; border:1px solid var(--line);">
        </div>
        
        <div class="field" style="margin-top:12px;">
          <label class="field-label">ประเภท <span style="color:#ef4444;">*</span></label>
          <select id="fb-type" style="width:100%; padding:10px; border-radius:8px; border:1px solid var(--line);">
            <option value="oil" ${(!f || f?.type === 'oil') ? 'selected' : ''}>🛢️ น้ำมัน (set oilAddon=true ฟรี)</option>
            <option value="other" ${f?.type === 'other' ? 'selected' : ''}>🎁 อื่นๆ (ของแถมทั่วไป)</option>
          </select>
        </div>
        
        <div class="field" style="margin-top:12px;">
          <label class="field-label">ใช้ที่ร้าน <span style="color:#ef4444;">*</span></label>
          <select id="fb-shop" style="width:100%; padding:10px; border-radius:8px; border:1px solid var(--line);">
            <option value="both" ${(!f || f?.shop === 'both') ? 'selected' : ''}>🌸+🎌 ทั้งสองร้าน</option>
            <option value="geisha" ${f?.shop === 'geisha' ? 'selected' : ''}>🌸 Geisha เท่านั้น</option>
            <option value="yoshi" ${f?.shop === 'yoshi' ? 'selected' : ''}>🎌 Yoshi เท่านั้น</option>
          </select>
        </div>
        
        <div class="field" style="margin-top:12px;">
          <label class="field-label">หมายเหตุ (ถ้ามี)</label>
          <input type="text" id="fb-note" value="${escapeHtml(f?.note || '')}" placeholder="เช่น แถมทุกคอร์สเดี่ยว" style="width:100%; padding:10px; border-radius:8px; border:1px solid var(--line);">
        </div>
        
        <div style="display:flex; gap:8px; margin-top:18px;">
          <button class="btn modal-close" style="flex:1;">ยกเลิก</button>
          <button class="btn btn-accent" id="fb-save-btn" style="flex:2;">💾 บันทึก</button>
        </div>
      </div>
    </div>
  `);
  
  $('#fb-save-btn').onclick = async () => {
    const name = $('#fb-name').value.trim();
    const type = $('#fb-type').value;
    const shop = $('#fb-shop').value;
    const note = $('#fb-note').value.trim();
    
    if (!name) { toast('กรุณาใส่ชื่อของแถม', 'error'); return; }
    
    try {
      await saveFreebie(freebieId, { name, type, shop, note });
      toast(editing ? '✓ แก้ไขของแถมแล้ว' : '✓ เพิ่มของแถมแล้ว', 'success');
      closeModal();
    } catch (e) {
      toast('❌ บันทึกไม่สำเร็จ: ' + e.message, 'error');
    }
  };
}

