// ⭐ Round 7.71: Infer category from legacy flags (สำหรับคอร์สเก่าที่ไม่มี category field)
function inferCategory(s) {
  if (!s) return 'regular';
  if (s.category) return s.category;
  if (s.memberOnly) return 'member';
  if (s.isPromo) return 'monthly';
  return 'regular';
}

// ⭐ Round 7.71: Category meta (icon, label, sort order)
const CATEGORY_META = {
  regular: { icon: '⬜', label: 'ราคาปกติ',       order: 1 },
  monthly: { icon: '🟧', label: 'ราคาพิเศษ',       order: 2 },  // ⭐ Round 7.74: rename (เดิม "โปรประจำเดือน" — เปลี่ยนเพราะมีหน้าใหม่ "โปรประจำเดือน" แยก)
  member:  { icon: '👑', label: 'Member',          order: 3 },
  web:     { icon: '🌐', label: 'โปรเว็บ',         order: 4 },
  line:    { icon: '💚', label: 'โปร LINE',        order: 5 },
  special: { icon: '⚫', label: 'คอร์สพิเศษ',     order: 6 }   // ⭐ Round 7.75r37: คอร์สกลุ่ม/ทาส
};

// ⭐ r38r29fy: จัดกลุ่ม service ใน dropdown ตามหมวด (optgroup คั่น + สีพื้นหลัง — กดง่าย กันพลาด)
//   ลำดับหมวด = CATEGORY_META.order (ปกติ → โปร/พิเศษ → Member/เว็บ/LINE → คอร์สพิเศษ) · ในหมวดคงลำดับเดิม (stable)
const _SVC_GROUP_META = {
  regular: { color: '#f0fdf4', label: '🟢 ราคาปกติ' },
  monthly: { color: '#fff7e6', label: '🎁 โปร/ราคาพิเศษ' },
  member:  { color: '#eaf3ff', label: '👑 Member' },
  web:     { color: '#eaf3ff', label: '🌐 โปรเว็บ' },
  line:    { color: '#eaf3ff', label: '💚 โปร LINE' },
  special: { color: '#f3eaff', label: '💜 คอร์สพิเศษ' },
};
function _svcGroupMeta(s) {
  const cat = (typeof inferCategory === 'function') ? inferCategory(s) : 'regular';
  return _SVC_GROUP_META[cat] || _SVC_GROUP_META.regular;
}
function _sortSvcByCategory(list) {
  const ord = (s) => {
    const cat = (typeof inferCategory === 'function') ? inferCategory(s) : 'regular';
    return (typeof CATEGORY_META !== 'undefined' && CATEGORY_META[cat]) ? CATEGORY_META[cat].order : 99;
  };
  return (list || []).map((s, i) => [s, i]).sort((a, b) => { const d = ord(a[0]) - ord(b[0]); return d !== 0 ? d : a[1] - b[1]; }).map(x => x[0]);
}
function _groupedServiceOptionsHtml(list, renderOpt) {
  const sorted = _sortSvcByCategory(list);
  let html = '', cur = null;
  for (const s of sorted) {
    const meta = _svcGroupMeta(s);
    if (meta.label !== cur) {
      if (cur !== null) html += '</optgroup>';
      html += `<optgroup label="${meta.label}">`;
      cur = meta.label;
    }
    html += renderOpt(s, meta.color);
  }
  if (cur !== null) html += '</optgroup>';
  return html;
}
window._groupedServiceOptionsHtml = _groupedServiceOptionsHtml;
window._sortSvcByCategory = _sortSvcByCategory;
window._svcGroupMeta = _svcGroupMeta;

// ⭐ Round 7.72k: Debug helper — เปิด console (F12) → window.debugServices()
