// ⭐ Round 7.75r38r8: Debug staff status — ดูพนง.ที่ติด + raw data
//   วิธีใช้: 
//     debugStaffStatus()              → ทั้ง 2 ร้าน
//     debugStaffStatus('geisha')      → เฉพาะ Geisha
//     debugStaffStatus('yoshi')       → เฉพาะ Yoshi
//     debugStaffStatus('geisha', 'soon')   → เฉพาะคนที่ "ติด soon" (รอบจะเต็มใน 15')
// ⭐ Round 7.75r38r9: Debug — ดูทำไม edit booking dropdown ว่าง
//   วิธีใช้: debugBookingEdit('yoshi', 'single')
window.debugBookingEdit = (shop = 'geisha', btype = 'single') => {
  const requiredCount = btype === 'single' ? 1 : (btype === 'couple' ? 2 : parseInt(btype.replace('group', ''), 10));
  
  console.log(`%c🔍 Debug Edit Booking — shop=${shop} type=${btype} (need ${requiredCount} staff)`,
    'background:#1e293b; color:#fff; padding:4px 8px; font-weight:700;');
  
  const all = state.services || [];
  console.log(`Total services: ${all.length}`);
  
  // Step 1: filter ตาม bookingType (groupSize)
  const matchType = all.filter(s => {
    const sz = getServiceGroupSize(s);
    if (btype === 'single' && sz !== 1) return false;
    if (btype === 'couple' && sz !== 2) return false;
    if (btype.startsWith('group') && sz !== requiredCount) return false;
    return true;
  });
  console.log(`%c→ Match type "${btype}": ${matchType.length}`, 'color:#10b981;');
  
  // Step 2: filter ตาม shop
  const matchShop = matchType.filter(s => {
    if (Array.isArray(s.availableShops) && s.availableShops.length > 0) {
      return s.availableShops.includes(shop);
    }
    return true;
  });
  console.log(`%c→ Match shop "${shop}": ${matchShop.length}`, 'color:#10b981;');
  
  // ดู rows
  console.table(matchType.map(s => ({
    name: s.name,
    groupSize: getServiceGroupSize(s),
    availableShops: Array.isArray(s.availableShops) 
      ? (s.availableShops.length === 0 ? '(empty = all)' : s.availableShops.join(','))
      : '(undefined = all)',
    ['available@' + shop]: (Array.isArray(s.availableShops) && s.availableShops.length > 0) 
      ? (s.availableShops.includes(shop) ? '✅' : '❌')
      : '✅ (default all)',
    durationMin: s.durationMin,
    priceGeisha: s.priceGeisha,
    priceYoshi: s.priceYoshi,
  })));
  
  return matchShop;
};

window.debugStaffStatus = (shop = null, filterStatus = null) => {
  const todayStr = ymd(new Date());
  const now = new Date();
  const nowMin = now.getHours() * 60 + now.getMinutes();
  const shops = shop ? [shop] : ['geisha', 'yoshi'];
  
  console.log(`%c🔍 Debug Staff Status — ${todayStr} ${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,
    'background:#1e293b; color:#fff; padding:4px 8px; font-weight:700;');
  
  for (const sh of shops) {
    console.log(`%c=== ${sh.toUpperCase()} ===`, 'color:#9333ea; font-weight:700;');
    
    // หาพนง.ที่ทำงาน shop นี้วันนี้
    const onDuty = (state.staff || []).filter(st => {
      const sched = getStaffWorkingOn(todayStr, st.id);
      return sched && sched.shop === sh;
    });
    
    const rows = [];
    for (const st of onDuty) {
      const status = getStaffStatusNow(st.id, sh);
      
      // ถ้า filter status ระบุ — กรอง
      if (filterStatus) {
        if (filterStatus === 'soon' && !status.status.startsWith('soon-')) continue;
        if (filterStatus === 'busy' && status.status !== 'busy') continue;
        if (filterStatus === 'free' && status.status !== 'free') continue;
      }
      
      // หา walkin active ของเขา
      const myWalkins = (state.walkins || []).filter(w => {
        if (w.date !== todayStr) return false;
        if (w.shop !== sh) return false;
        if (w.status !== 'active' && w.status !== 'walkin') return false;
        const ids = getStaffIdsFromRecord(w);
        return ids.includes(st.id);
      });
      
      // หา pending booking
      const todayWalkinsAll = (state.walkins || []).filter(w => 
        w.date === todayStr && w.active !== false && w.status !== 'cancelled'
      );
      const linkedIds = new Set(todayWalkinsAll.filter(w => w.bookingId).map(w => w.bookingId));
      const myBookings = (state.bookings || []).filter(b => {
        if (b.date !== todayStr) return false;
        if (b.shop !== sh) return false;
        const ids = getStaffIdsFromRecord(b);
        if (!ids.includes(st.id)) return false;
        const bst = b.status || 'confirmed';
        if (['canceled', 'cancelled', 'no-show', 'noshow', 'completed', 'arrived'].includes(bst)) return false;
        if (linkedIds.has(b.id)) return false;
        if (b.checkedInWalkinId) return false;
        const bStart = timeToMin(b.startTime || '00:00');
        const diff = bStart - nowMin;
        return diff >= -45 && diff <= 180;
      });
      
      const walkinStrs = myWalkins.map(w => {
        const endMin = timeToMin(getEffectiveEndTime(w));
        const rem = endMin - nowMin;
        return `[${w.id?.slice(-4)}] ${w.customerName || '?'} ${w.startTime}→${w.endTime} (${rem >= 0 ? 'เหลือ '+rem : 'เลย '+(-rem)}') status=${w.status}`;
      });
      
      const bookingStrs = myBookings.map(b => {
        const bStart = timeToMin(b.startTime || '00:00');
        const diff = bStart - nowMin;
        return `[${b.id?.slice(-4)}] ${b.customerName || '?'} ${b.startTime}-${b.endTime} (${diff > 0 ? 'อีก '+diff : 'เลย '+(-diff)}')`;
      });
      
      rows.push({
        '👤 พนง.': st.nickname || st.shortCode || '?',
        '📊 status': status.status,
        '⏰ remaining': status.remainingMin != null ? status.remainingMin + "'" : '-',
        '⏳ maxAvailMin': status.maxAvailableMin != null ? status.maxAvailableMin + "'" : '-',
        '📏 maxCourse': status.maxCourseFits != null ? status.maxCourseFits + "'" : '-',
        '🚶 walkins': walkinStrs.length > 0 ? walkinStrs.join(' | ') : '(ไม่มี)',
        '📅 bookings': bookingStrs.length > 0 ? bookingStrs.join(' | ') : '(ไม่มี)',
      });
    }
    
    if (rows.length === 0) {
      console.log('(ไม่มีพนง.ตรงเงื่อนไข)');
    } else {
      console.table(rows);
    }
  }
  
  console.log(`%c💡 Tips: debugStaffStatus('geisha', 'soon')  → ดูเฉพาะคนที่ "ว่างใน 15 นาที"`, 'color:#10b981;');
  return 'Done — ดูตารางด้านบน';
};

// ⭐ Round 7.75r36at: Debug staff — เปิด console → window.debugStaff('ฟิว') หรือ window.debugStaff()
window.debugStaff = (filter) => {
  let list = state.staff || [];
  if (filter) {
    const f = filter.toLowerCase();
    list = list.filter(s => 
      (s.nickname || '').toLowerCase().includes(f) ||
      (s.shortCode || '').toLowerCase().includes(f) ||
      (s.nameEn || '').toLowerCase().includes(f) ||
      (s.fullName || '').toLowerCase().includes(f)
    );
  }
  console.table(list.map(s => ({
    id: s.id?.slice(0, 8),
    nickname: s.nickname || '',
    shortCode: s.shortCode || '',
    nameEn: s.nameEn || '',
    shop: s.shop || '',
    active: s.active !== false ? '✅' : '❌',
    tier: s.tier || ''
  })));
  return list;
};

// ⭐ Round 7.75r36at: Debug parser — ลองยิงข้อความ → ดูผล parse แต่ละขั้น
//   window.debugParse("พัฒน์\nฟิว\n15.00\n60\n0927789810")
window.debugParse = (text) => {
  if (!text) return console.log('ใช้: debugParse("ข้อความ")');
  const r = (typeof parseBookingText === 'function') ? parseBookingText(text) : null;
  console.log('=== Input ===');
  console.log(text);
  console.log('\n=== Parsed ===');
  console.log({
    name: r?.name,
    _nameFromFirstLine: r?._nameFromFirstLine,
    staffMatch: r?.staffMatch?.staff?.nickname || r?.staffMatch?.name,
    staffMatch2: r?.staffMatch2?.staff?.nickname,
    time: r?.time,
    durationMin: r?.durationMin,
    phone: r?.phone,
    shop: r?.shop,
    memberCode: r?.memberCode,
    courseHint: r?.courseHint,
  });
  return r;
};

